test "Generator.generate: builds an executable that uses the standard streams and a file" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::convert::To\nimport mn::filesystem\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process::stdin\nimport mn::process::stdout\nimport mn::stream::Reader\nimport mn::stream::Writer\nimport mn::text\n\nfn main -> !void\n    try text::print(&stdout, \"hi\\n\", {})\n    var buffer: [64]u8 = undefined\n    const count = try stdin.read(&buffer)\n    try stdout.write(buffer[..count])\n    var heap = memory::Heap::init()\n    var own path = try \"cards.toml\".to(filesystem::Path) with &heap\n    defer path.deinit(own) with &heap\n    _ = try measure(path)\n\nfn measure(path: filesystem::Path) -> filesystem::Error!usize\n    const file = filesystem::File::open(path) catch return 0\n    defer file.close()\n    var buffer: [64]u8 = undefined\n    const count = try file.read(&buffer)\n    return count + try file.size()\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const executable = try output_directory.dir.statFile(std.testing.io, "build/main", .{});
    try std.testing.expectEqual(.file, executable.kind);
    const io_source = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, "generators/c/runtime/io.c", allocator, .unlimited);
    const filesystem_source = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, "generators/c/runtime/filesystem.c", allocator, .unlimited);
    try std.testing.expectEqualStrings(io_source, try output_directory.dir.readFileAlloc(std.testing.io, "build/source/runtime/io.c", allocator, .unlimited));
    try std.testing.expectEqualStrings(filesystem_source, try output_directory.dir.readFileAlloc(std.testing.io, "build/source/runtime/filesystem.c", allocator, .unlimited));
}

test "Generator.generate: builds an executable that writes files" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::convert::To\nimport mn::filesystem\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::stream::Writer\nimport mn::text\n\nfn report(writer: *Writer, value: u8) -> !void\n    const own line = try text::format(\"value {x} done {}\\n\", { value, value })\n    defer memory::free(own line)\n    try writer.write(line)\n\nfn open_for_writing(content: []const(u8)) -> !filesystem::File\n    var own path = try content.to(filesystem::Path)\n    defer path.deinit(own)\n    return filesystem::File::open(path, { mode = ::Write })\n\nfn main -> !void\n    with memory::Heap\n    const created = try open_for_writing(\"created.txt\")\n    defer created.close()\n    try created.write(\"exact bytes\")\n    const emptied = try open_for_writing(\"emptied.txt\")\n    defer emptied.close()\n    try emptied.write(\"short\")\n    const formatted = try open_for_writing(\"formatted.txt\")\n    defer formatted.close()\n    const number: u8 = 7\n    const own line = try text::format(\"{} and {s}\\n\", { number, \"text\" })\n    defer memory::free(own line)\n    try formatted.write(line)\n    try report(&formatted, 255)\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);
    try build_directory.writeFile(std.testing.io, .{ .sub_path = "emptied.txt", .data = "a much longer text than the init one" });

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{ "sh", "-c", "umask 0 && exec ./main" }, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqual(0, result.term.exited);
    const limit: std.Io.Limit = .limited(1024);
    try std.testing.expectEqualStrings("exact bytes", try build_directory.readFileAlloc(std.testing.io, "created.txt", allocator, limit));
    try std.testing.expectEqualStrings("short", try build_directory.readFileAlloc(std.testing.io, "emptied.txt", allocator, limit));
    try std.testing.expectEqualStrings("7 and text\nvalue ff done 255\n", try build_directory.readFileAlloc(std.testing.io, "formatted.txt", allocator, limit));
    const created = try build_directory.statFile(std.testing.io, "created.txt", .{});
    try std.testing.expectEqual(0o666, created.permissions.toMode() & 0o777);
}

