test "Generator.generate: builds an executable that reports the errors of opening and writing files" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::convert::To\nimport mn::filesystem\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::stream::Reader\nimport mn::stream::Writer\nimport mn::text\n\nfn report_open(content: []const(u8), mode: filesystem::File::Mode) -> !void\n    var own path = try content.to(filesystem::Path)\n    defer path.deinit(own)\n    match filesystem::File::open(path, { mode = mode })\n        case filesystem::File as file\n            file.close()\n            try text::print(&stdout, \"opened\\n\", {})\n        case (filesystem::Error::IsDirectory) try text::print(&stdout, \"is_directory\\n\", {})\n        case (filesystem::Error::NotFound) try text::print(&stdout, \"not_found\\n\", {})\n        else try text::print(&stdout, \"unexpected open error\\n\", {})\n\nfn report_write(file: filesystem::File) -> !void\n    match file.write(\"overwritten\")\n        case (void) try text::print(&stdout, \"written\\n\", {})\n        case (filesystem::Error::NotOpen) try text::print(&stdout, \"not_open\\n\", {})\n        else try text::print(&stdout, \"unexpected write error\\n\", {})\n\nfn main -> !void\n    with memory::Heap\n    try report_open(\"missing.txt\", filesystem::File::Mode::Read)\n    try report_open(\"directory\", filesystem::File::Mode::Read)\n    try report_open(\"directory\", filesystem::File::Mode::Write)\n    try report_open(\"missing/created.txt\", filesystem::File::Mode::Write)\n    var own path = try \"existing.txt\".to(filesystem::Path)\n    defer path.deinit(own)\n    const file = try filesystem::File::open(path)\n    defer file.close()\n    var buffer: [64]u8 = undefined\n    const count = try Reader::read(&file, buffer[..])\n    try text::print(&stdout, \"{s}\\n\", { buffer[..count] })\n    try report_write(file)\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
