    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("not_found\nis_directory\nis_directory\nnot_found\nexisting bytes\nnot_open\n", result.stdout);
