test "Generator.generate: builds an executable that handles one error of a match and returns what is left through try" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::process\nimport mn::process::stdout\nimport mn::stream::Writer\nimport mn::text\n\nerror OpenError\n    NotFound\n    Denied: u8\n\nerror CreateError\n    Full\n\nstruct File\n    id: i32\n\nfn open(mode: []const(u8)) -> OpenError!File\n    if (mode[0] == 'o') return File{ id = 1 }\n    if (mode[0] == 'm') return OpenError::NotFound\n    return OpenError::Denied{ 7 }\n\nfn create(mode: []const(u8)) -> CreateError!File\n    if (mode[1] == 'f') return CreateError::Full\n    return File{ id = 2 }\n\nfn load(mode: []const(u8)) -> !i32\n    const file = try match open(mode)\n        case (NotFound) create(mode)\n        else (_ as rest) rest\n    return file.id\n\nfn main -> !void\n    const id = try load(process::arguments()[0])\n    try text::print(&stdout, \"{}\\n\", { id })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const run_0 = try std.process.run(allocator, std.testing.io, .{ .argv = &.{ "./main", "open" }, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("1\n", run_0.stdout);
    try std.testing.expectEqual(0, run_0.term.exited);

    const run_1 = try std.process.run(allocator, std.testing.io, .{ .argv = &.{ "./main", "mm" }, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("2\n", run_1.stdout);
    try std.testing.expectEqual(0, run_1.term.exited);

    const run_2 = try std.process.run(allocator, std.testing.io, .{ .argv = &.{ "./main", "mf" }, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("", run_2.stdout);
    try std.testing.expectEqual(1, run_2.term.exited);
    try std.testing.expect(std.mem.indexOf(u8, run_2.stderr, "Full") != null);

    const run_3 = try std.process.run(allocator, std.testing.io, .{ .argv = &.{ "./main", "denied" }, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("", run_3.stdout);
    try std.testing.expectEqual(1, run_3.term.exited);
}

test "Generator.generate: builds an executable that names the smallest type of what is left of a match" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::process::stdout\nimport mn::stream::Writer\nimport mn::text\n\nerror Failure\n    One\n    Two: u8\n    Three\nfn pick(mode: usize) -> Failure!i32\n    if (mode == 0) return 10\n    if (mode == 1) return Failure::One\n    if (mode == 2) return Failure::Two{ 5 }\n    return Failure::Three\nfn show_some(mode: usize) -> !void\n    match pick(mode)\n        case (One) try text::print(&stdout, \"handled\\n\", {})\n        else _ as rest\n            match rest\n                case i32 as value\n                    try text::print(&stdout, \"value {}\\n\", { value })\n                case Two{ digit }\n                    try text::print(&stdout, \"two {}\\n\", { digit })\n                case (Three)\n                    try text::print(&stdout, \"three\\n\", {})\nfn show_all(mode: usize) -> !void\n    match pick(mode)\n        case (One, Two, Three) try text::print(&stdout, \"error\\n\", {})\n        else (_ as rest) try text::print(&stdout, \"{}\\n\", { rest })\nfn show_value(mode: usize) -> !void\n    match pick(mode)\n        case i32 as value\n            try text::print(&stdout, \"{}\\n\", { value })\n        else _ as rest\n            match rest\n                case (One) try text::print(&stdout, \"one\\n\", {})\n                case (Two{ digit }) try text::print(&stdout, \"two {}\\n\", { digit })\n                case (Three) try text::print(&stdout, \"three\\n\", {})\nfn show_value_and_some(mode: usize) -> !void\n    match pick(mode)\n        case (i32) try text::print(&stdout, \"value\\n\", {})\n        case (One) try text::print(&stdout, \"one\\n\", {})\n        else _ as rest\n            match rest\n                case (Two{ digit }) try text::print(&stdout, \"two {}\\n\", { digit })\n                case (Three) try text::print(&stdout, \"three\\n\", {})\nfn show_nothing(mode: usize) -> !void\n    match pick(mode)\n        else (_ as rest) try text::print(&stdout, \"{}\\n\", { rest catch 8 })\nfn show_named(mode: usize) -> !void\n    match pick(mode)\n        case Two as failure\n            match failure\n                case (Two{ digit }) try text::print(&stdout, \"named {}\\n\", { digit })\n        else noop\nfn show_set(failure: Failure) -> !void\n    match failure\n        case (One) try text::print(&stdout, \"one\\n\", {})\n        else _ as rest\n            try text::print(&stdout, \"{}\\n\", { rest == Failure::Three })\nfn find(mode: usize) -> ?i32\n    if (mode == 0) return 4\n    return null\nfn find_pointer(pointer: *i32, mode: usize) -> ?*i32\n    if (mode == 0) return pointer\n    return null\nfn show_optional(mode: usize, pointer: *i32) -> !void\n    match find(mode)\n        case (null) try text::print(&stdout, \"null\\n\", {})\n        else (_ as rest) try text::print(&stdout, \"{}\\n\", { rest })\n    match find(mode)\n        else (_ as rest) try text::print(&stdout, \"{}\\n\", { rest orelse 9 })\n    match find(mode)\n        case (i32) try text::print(&stdout, \"value\\n\", {})\n        else (_ as rest) try text::print(&stdout, \"{}\\n\", { rest orelse 9 })\n    match find_pointer(pointer, mode)\n        case (null) try text::print(&stdout, \"null\\n\", {})\n        else (_ as rest) try text::print(&stdout, \"{}\\n\", { rest.* })\nenum Kind\n    One\n    Two: i32\nfn show_kind(kind: Kind) -> !void\n    match kind\n        case (One) try text::print(&stdout, \"one\\n\", {})\n        else (_ as rest) try text::print(&stdout, \"{}\\n\", { rest == Kind::One })\nfn show_integer(value: u8) -> !void\n    match value\n        case (0) try text::print(&stdout, \"zero\\n\", {})\n        else (_ as rest) try text::print(&stdout, \"{}\\n\", { rest })\nfn main -> !void\n    var pointed: i32 = 6\n    for mode in 0..4\n        try show_some(mode)\n        try show_all(mode)\n        try show_value(mode)\n        try show_value_and_some(mode)\n        try show_nothing(mode)\n        try show_named(mode)\n        try show_optional(mode, &pointed)\n    try show_set(Failure::One)\n    try show_set(Failure::Two{ 1 })\n    try show_set(Failure::Three)\n    try show_kind(Kind::One)\n    try show_kind(Kind::Two{ 3 })\n    try show_integer(0)\n    try show_integer(9)\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const run_0 = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("value 10\n10\n10\nvalue\n10\n4\n4\nvalue\n6\nhandled\nerror\none\none\n8\nnull\n9\n9\nnull\ntwo 5\nerror\ntwo 5\ntwo 5\n8\nnamed 5\nnull\n9\n9\nnull\nthree\nerror\nthree\nthree\n8\nnull\n9\n9\nnull\none\nfalse\ntrue\none\nfalse\nzero\n9\n", run_0.stdout);
    try std.testing.expectEqual(0, run_0.term.exited);
}

test "Generator.generate: builds an executable that converts what is left to larger sets and keeps its tags and data" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::process::stdout\nimport mn::stream::Writer\nimport mn::text\n\nerror Failure\n    One\n    Two: u8\n    Three\nfn pick(mode: usize) -> Failure!i32\n    if (mode == 0) return 10\n    if (mode == 1) return Failure::One\n    if (mode == 2) return Failure::Two{ 5 }\n    return Failure::Three\nerror Other\n    Four\nfn other(mode: usize) -> Other!i32\n    if (mode == 5) return Other::Four\n    return 20\nfn note() -> !void\n    try text::print(&stdout, \"note\\n\", {})\nfn load(mode: usize) -> !i32\n    const value = try match pick(mode)\n        case (One) other(mode)\n        case Two as failure\n            try note()\n            failure\n        else (_ as rest) rest\n    return value + 1\nfn widen(mode: usize) -> (Failure || Other)!i32\n    match pick(mode)\n        case (One) return Other::Four\n        else (_ as rest) return rest\nfn show(result: (Failure || Other)!i32) -> !void\n    match result\n        case (i32 as value) try text::print(&stdout, \"value {}\\n\", { value })\n        case (Four) try text::print(&stdout, \"four\\n\", {})\n        case (Two{ digit }) try text::print(&stdout, \"two {}\\n\", { digit })\n        else try text::print(&stdout, \"other\\n\", {})\nfn main -> !void\n    for mode in 0..4\n        match load(mode)\n            case (i32 as value) try text::print(&stdout, \"{}\\n\", { value })\n            case (Two) try text::print(&stdout, \"two\\n\", {})\n            case (Three) try text::print(&stdout, \"three\\n\", {})\n            else try text::print(&stdout, \"left\\n\", {})\n        try show(widen(mode))\n    const wide: (Failure || Other)!i32 = match pick(2)\n        case (One) other(0)\n        else (_ as rest) rest\n    try show(wide)\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const run_0 = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("11\nvalue 10\n21\nfour\nnote\ntwo\ntwo 5\nthree\nother\ntwo 5\n", run_0.stdout);
    try std.testing.expectEqual(0, run_0.term.exited);
}

test "Generator.generate: builds an executable that handles results without a value and tells the forms of else apart" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::process::stdout\nimport mn::stream::Writer\nimport mn::text\n\nerror Failure\n    One\n    Two\nfn act(mode: usize) -> Failure!void\n    if (mode == 1) return Failure::One\n    if (mode == 2) return Failure::Two\nfn note() -> void = noop\nfn run(mode: usize) -> !void\n    try match act(mode)\n        case (One) noop\n        else (_ as rest) rest\n    try text::print(&stdout, \"first {}\\n\", { mode })\nfn run_call(mode: usize) -> !void\n    try match act(mode)\n        case (One) note()\n        else (_ as rest) rest\n    try text::print(&stdout, \"second {}\\n\", { mode })\nfn run_value(mode: usize) -> !void\n    try match act(mode)\n        case (void) noop\n        else (_ as rest) rest\n    try text::print(&stdout, \"third {}\\n\", { mode })\nfn show(mode: usize) -> !void\n    match run(mode)\n        case (void) noop\n        else try text::print(&stdout, \"run failed {}\\n\", { mode })\n    match run_call(mode)\n        case (void) noop\n        else try text::print(&stdout, \"call failed {}\\n\", { mode })\n    match run_value(mode)\n        case (void) noop\n        else try text::print(&stdout, \"value failed {}\\n\", { mode })\nfn main -> !void\n    for mode in 0..3\n        try show(mode)\n    match act(2)\n        else noop\n    match act(2)\n        case (One) noop\n        else _ = note2()\n    match act(2)\n        case (One) noop\n        else (try text::print(&stdout, \"expression\\n\", {}))\nfn note2() -> i32 = 1\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const run_0 = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("first 0\nsecond 0\nthird 0\nfirst 1\nsecond 1\nvalue failed 1\nrun failed 2\ncall failed 2\nvalue failed 2\nexpression\n", run_0.stdout);
    try std.testing.expectEqual(0, run_0.term.exited);
}

