test "Generator.generate: builds an executable that opens a file or creates it and returns any other error" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::convert::To\nimport mn::filesystem\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process\nimport mn::process::stdout\nimport mn::stream::Writer\nimport mn::text\n\nfn open_or_create(content: []const(u8)) -> !usize\n    var own path = try content.to(filesystem::Path)\n    defer path.deinit(own)\n    const file = try match filesystem::File::open(path)\n        case (NotFound) filesystem::File::open(path, { mode = ::Write })\n        else (_ as rest) rest\n    defer file.close()\n    return file.size()\n\nfn main -> !void\n    with memory::Heap\n    const size = try open_or_create(process::arguments()[0])\n    try text::print(&stdout, \"{}\\n\", { size })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);
    try build_directory.writeFile(std.testing.io, .{ .sub_path = "input.txt", .data = "bytes" });

    const run_0 = try std.process.run(allocator, std.testing.io, .{ .argv = &.{ "./main", "input.txt" }, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("5\n", run_0.stdout);
    try std.testing.expectEqual(0, run_0.term.exited);

    const run_1 = try std.process.run(allocator, std.testing.io, .{ .argv = &.{ "./main", "created.txt" }, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("0\n", run_1.stdout);
    try std.testing.expectEqual(0, run_1.term.exited);

    const run_2 = try std.process.run(allocator, std.testing.io, .{ .argv = &.{ "./main", "input.txt/inner" }, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("", run_2.stdout);
    try std.testing.expectEqual(1, run_2.term.exited);
    try std.testing.expect(std.mem.indexOf(u8, run_2.stderr, "NotDirectory") != null);
    const created = try build_directory.statFile(std.testing.io, "created.txt", .{});
    try std.testing.expectEqual(.file, created.kind);
}

