    const runtime_source = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, "generators/c/runtime/time.c", allocator, .unlimited);
    try std.testing.expectEqualStrings(runtime_source, try output_directory.dir.readFileAlloc(std.testing.io, "build/source/runtime/time.c", allocator, .unlimited));
    try build_directory.writeFile(std.testing.io, .{ .sub_path = "reference.c", .data = "#define _POSIX_C_SOURCE 200809L\n\n#include <stdio.h>\n#include <time.h>\n\nint main(void) {\n    struct timespec monotonic;\n    clock_gettime(CLOCK_MONOTONIC, &monotonic);\n    printf(\"%lld %lld\\n\", (long long)time(NULL), (long long)monotonic.tv_sec * 1000000000LL + (long long)monotonic.tv_nsec);\n    return 0;\n}\n" });
    const compiled = try std.process.run(allocator, std.testing.io, .{ .argv = &.{ "gcc", "-std=c23", "-w", "reference.c", "-o", "reference" }, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("", compiled.stderr);

    const before = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./reference"}, .cwd = .{ .dir = build_directory } });
    const clocks = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    const after = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./reference"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqual(0, clocks.term.exited);

    var numbers: std.ArrayList(i64) = .empty;
    for ([_][]const u8{ before.stdout, clocks.stdout, after.stdout }) |output| {
        var parts = std.mem.tokenizeAny(u8, output, " \n");
        while (parts.next()) |part| try numbers.append(allocator, try std.fmt.parseInt(i64, part, 10));
    }
    try std.testing.expectEqual(10, numbers.items.len);
    const seconds_before = numbers.items[0];
    const monotonic_before = numbers.items[1];
    const wall_seconds_one = numbers.items[2];
    const wall_nanoseconds_one = numbers.items[3];
    const wall_seconds_two = numbers.items[4];
    const wall_nanoseconds_two = numbers.items[5];
    const monotonic_one = numbers.items[6];
    const monotonic_two = numbers.items[7];
    const seconds_after = numbers.items[8];
    const monotonic_after = numbers.items[9];
    try std.testing.expect(wall_seconds_one >= seconds_before);
    try std.testing.expect(wall_seconds_two <= seconds_after + 1);
    for ([_]i64{ wall_nanoseconds_one, wall_nanoseconds_two }) |nanoseconds| {
        try std.testing.expect(nanoseconds >= 0 and nanoseconds <= 999_999_999);
    }
    try std.testing.expect(wall_nanoseconds_one != 0 or wall_nanoseconds_two != 0);
    try std.testing.expect(monotonic_one >= monotonic_before);
    try std.testing.expect(monotonic_two <= monotonic_after);
    try std.testing.expect(@rem(monotonic_one, 1_000_000_000) != 0 or @rem(monotonic_two, 1_000_000_000) != 0);
}

