test "Generator.generate: builds an executable that requires a typeclass with one type left unknown" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::convert::To\nimport mn::filesystem\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::stream::Writer\nimport mn::text\n\nerror FirstFailure\n    First\n\nerror SecondFailure\n    Second\n\nstruct One\n    value: u8\n\nstruct Two\n    value: u8\n\ninstance To(One, []u8)\n\n    fn to(one: One, type U) -> own !U\n        if (one.value == 0) return FirstFailure::First\n        const own content = try memory::allocate(u8, 1)\n        content[0] = one.value\n        return content\n\ninstance To(Two, []u8)\n\n    fn to(two: Two, type U) -> own !U\n        if (two.value == 0) return SecondFailure::Second\n        const own content = try memory::allocate(u8, 2)\n        content[0] = two.value\n        content[1] = two.value\n        return content\n\nfn save(value: To(_, []u8)) -> !void\n    const own content = try value.to([]u8)\n    defer memory::free(own content)\n    try text::print(&stdout, \"{s}\\n\", { content })\n\ntypeclass Convert(type A, type B)\n\n    fn make(value: B) -> A\n\ninstance Convert(u8, One)\n\n    fn make(value: One) -> u8 = value.value\n\ninstance Convert(u8, Two)\n\n    fn make(value: Two) -> u8 = value.value + 1\n\nfn second_position(value: Convert(u8, _)) -> u8 = Convert::make(value)\n\ntypeclass Change(type A, type B)\n\n    fn change(value: *A) -> B\n\ninstance Change(One, u8)\n\n    fn change(value: *One) -> u8\n        value.value += 1\n        return value.value\n\ninstance Change(Two, u8)\n\n    fn change(value: *Two) -> u8\n        value.value += 2\n        return value.value\n\nfn pointer_form(value: *Change(_, u8)) -> u8 = value.change()\n\nfn main -> !void\n    with memory::Heap\n    try save(One{ value = 65 })\n    try save(Two{ value = 66 })\n    var own path = try \"c/d\".to(filesystem::Path)\n    defer path.deinit(own)\n    try save(path)\n    const own fixed = try \"e/f\".to(filesystem::Path)\n    defer fixed.deinit(own)\n    try save(fixed)\n    match save(One{ value = 0 })\n        case (First) try text::print(&stdout, \"first\\n\", {})\n        else try text::print(&stdout, \"other\\n\", {})\n    match save(Two{ value = 0 })\n        case (Second) try text::print(&stdout, \"second\\n\", {})\n        else try text::print(&stdout, \"other\\n\", {})\n    try text::print(&stdout, \"{} {}\\n\", { second_position(One{ value = 3 }), second_position(Two{ value = 3 }) })\n    var one: One = { value = 1 }\n    var two: Two = { value = 1 }\n    try text::print(&stdout, \"{} {} {} {}\\n\", { pointer_form(&one), pointer_form(&two), one.value, two.value })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const run_0 = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("A\nBB\nc/d\ne/f\nfirst\nsecond\n3 4\n2 3 2 3\n", run_0.stdout);
    try std.testing.expectEqual(0, run_0.term.exited);
}

test "Generator.generate: builds an executable that swaps, replaces, takes and moves values through pointers with mn::memory" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [262144]u8\n    used: usize\n    fail_at: usize\n    allocations: usize\n    frees: usize\n    live: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        counting.allocations += 1\n        if (counting.allocations == counting.fail_at) return memory::Error::OutOfMemory\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(counting: *Counting, items: []T, count: usize) -> bool\n        if (count > items.length) return false\n        counting.live -= mn::size(T) * (items.length - count)\n        return true\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        counting.frees += 1\n        counting.live -= mn::size(T) * items.length\n\nfn start(counting: *Counting)\n    counting.used = 0\n    counting.fail_at = 0\n    counting.allocations = 0\n    counting.frees = 0\n    counting.live = 0\n\nstruct Record\n    own name: []u8\n    size: usize\n\nstruct Node\n    value: u32\n    own next: ?*Node\n\nfn make(size: usize) -> own memory::Error!Record\n    const own name = try memory::allocate(u8, size)\n    for index in 0..size\n        name[index] = 'a' + mn::truncate(u8, index)\n    return { name = own name, size = size }\n\nfn main -> !void\n    var counting: Counting = undefined\n    start(&counting)\n    try run(&counting)\n    try text::print(&stdout, \"live {}\\n\", { counting.live })\n\nfn run(counting: *Counting) -> !void\n    with counting\n    var own records: [2]Record = { try make(1), try make(2) }\n    defer memory::free(own records[0].name)\n    defer memory::free(own records[1].name)\n    memory::swap(&records[0], &records[1])\n    try text::print(&stdout, \"swap {} {s} {} {s}\\n\", { records[0].size, records[0].name, records[1].size, records[1].name })\n    var numbers: [2]u32 = { 1, 2 }\n    memory::swap(&numbers[0], &numbers[1])\n    memory::swap(&numbers[1], &numbers[1])\n    try text::print(&stdout, \"numbers {} {}\\n\", { numbers[0], numbers[1] })\n    const own fresh = try make(3)\n    const own old = memory::replace(&records[0], own fresh)\n    defer memory::free(own old.name)\n    try text::print(&stdout, \"replace {} {s} {} {s}\\n\", { old.size, old.name, records[0].size, records[0].name })\n    var own maybe: ?Record = try make(4)\n    const own taken = memory::take(&maybe)\n    defer memory::free(own taken.?.name)\n    const own nothing = memory::take(&maybe)\n    const emptied = maybe == null\n    const found_nothing = nothing == null\n    if maybe as own left\n        memory::free(own left.name)\n    if nothing as own left\n        memory::free(own left.name)\n    try text::print(&stdout, \"take {} {}\\n\", { taken.?.size, emptied })\n    try text::print(&stdout, \"empty {} {}\\n\", { found_nothing, emptied })\n    var own first: Node = { value = 1, next = try memory::create(Node) }\n    first.next.?.* = { value = 3, next = null }\n    const own unlinked = memory::take(&first.next)\n    const unlinked_all = first.next == null\n    if first.next as own next\n        memory::destroy(own next)\n    defer memory::destroy(own unlinked.?)\n    try text::print(&stdout, \"unlink {} {} {}\\n\", { unlinked.?.value, unlinked_all, counting.allocations })\n    var own extra: [1]Record = { try make(5) }\n    const own moved = memory::move(&extra[0])\n    extra[0] = { name = {}, size = 0 }\n    memory::free(own extra[0].name)\n    defer memory::free(own moved.name)\n    try text::print(&stdout, \"move {} {s}\\n\", { moved.size, moved.name })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("swap 2 ab 1 a\nnumbers 2 1\nreplace 2 ab 3 abc\ntake 4 true\nempty true true\nunlink 3 true 5\nmove 5 abcde\nlive 0\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that turns lists into memory of their exact length" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container::ArrayList\nimport mn::convert::ToOwned\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::stream::Writer\nimport mn::text\n\nstruct Counting\n    bytes: [65536]u8\n    used: usize\n    allocations: usize\n    resizes: usize\n    frees: usize\n    last_free: usize\n    live: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        counting.allocations += 1\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(counting: *Counting, items: []T, count: usize) -> bool\n        counting.resizes += 1\n        if (count > items.length) return false\n        counting.live -= mn::size(T) * (items.length - count)\n        return true\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        counting.frees += 1\n        counting.last_free = items.length\n        counting.live -= mn::size(T) * items.length\n\nfn report(label: []const(u8), counting: *const(Counting)) -> !void\n    try text::print(&stdout, \"{s} {} {} {} {} {}\\n\", { label, counting.allocations, counting.resizes, counting.frees, counting.last_free, counting.live })\n\nfn start(counting: *Counting)\n    counting.used = 0\n    counting.allocations = 0\n    counting.resizes = 0\n    counting.frees = 0\n    counting.last_free = 0\n    counting.live = 0\n\nfn shrink_bytes(counting: *Counting) -> !void\n    start(counting)\n    var own list = ArrayList(u8)::init()\n    errdefer list.deinit(own) with counting\n    try list.write(\"hello\") with counting\n    const own owned: []u8 = try list.to_owned(own) with counting\n    errdefer memory::free(own owned) with counting\n    try text::print(&stdout, \"{s}\\n\", { owned })\n    try report(\"shrink\", counting)\n    memory::free(own owned) with counting\n    try report(\"free\", counting)\n\nfn shrink_numbers(counting: *Counting) -> !void\n    start(counting)\n    var own list = ArrayList(i32)::init()\n    errdefer list.deinit(own) with counting\n    for index in 0..3\n        try list.append(mn::convert(i32, index) + 1) with counting\n    const own owned: []i32 = try list.to_owned(own) with counting\n    errdefer memory::free(own owned) with counting\n    try text::print(&stdout, \"{} {} {} {}\\n\", { owned[0], owned[1], owned[2], owned.length })\n    try report(\"numbers\", counting)\n    memory::free(own owned) with counting\n    try report(\"free\", counting)\n\nfn exact_length(counting: *Counting) -> !void\n    start(counting)\n    var own list = ArrayList(u8)::init()\n    errdefer list.deinit(own) with counting\n    for _ in 0..8\n        try list.append(1) with counting\n    const own owned: []u8 = try list.to_owned(own) with counting\n    errdefer memory::free(own owned) with counting\n    try text::print(&stdout, \"{}\\n\", { owned.length })\n    try report(\"exact\", counting)\n    memory::free(own owned) with counting\n    try report(\"free\", counting)\n\nfn never_grown(counting: *Counting) -> !void\n    start(counting)\n    var own list = ArrayList(u8)::init()\n    errdefer list.deinit(own) with counting\n    const own owned: []u8 = try list.to_owned(own) with counting\n    errdefer memory::free(own owned) with counting\n    try text::print(&stdout, \"{}\\n\", { owned.length })\n    try report(\"empty\", counting)\n    memory::free(own owned) with counting\n    try report(\"free\", counting)\n\nfn emptied_by_pop(counting: *Counting) -> !void\n    start(counting)\n    var own list = ArrayList(u16)::init()\n    errdefer list.deinit(own) with counting\n    try list.append(1) with counting\n    _ = list.pop()\n    const own owned: []u16 = try list.to_owned(own) with counting\n    errdefer memory::free(own owned) with counting\n    const nothing: []u16 = {}\n    try text::print(&stdout, \"{} {}\\n\", { owned.length, owned.pointer == nothing.pointer })\n    try report(\"emptied\", counting)\n    memory::free(own owned) with counting\n    try report(\"free\", counting)\n\nfn through_the_heap() -> !void\n    var own bytes = ArrayList(u8)::init()\n    errdefer bytes.deinit(own)\n    try bytes.write(\"heap\")\n    const own owned_bytes: []u8 = try bytes.to_owned(own)\n    defer memory::free(own owned_bytes)\n    var own emptied = ArrayList(u8)::init()\n    errdefer emptied.deinit(own)\n    try emptied.append(1)\n    _ = emptied.pop()\n    const own owned_emptied: []u8 = try emptied.to_owned(own)\n    defer memory::free(own owned_emptied)\n    var own never = ArrayList(u8)::init()\n    errdefer never.deinit(own)\n    const own owned_never: []u8 = try never.to_owned(own)\n    defer memory::free(own owned_never)\n    try text::print(&stdout, \"{s} {} {}\\n\", { owned_bytes, owned_emptied.length, owned_never.length })\n\nfn main -> !void\n    with memory::Heap\n    var counting: Counting = undefined\n    try shrink_bytes(&counting)\n    try shrink_numbers(&counting)\n    try exact_length(&counting)\n    try never_grown(&counting)\n    try emptied_by_pop(&counting)\n    try through_the_heap()\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const run_0 = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("hello\nshrink 1 1 0 0 5\nfree 1 1 1 5 0\n1 2 3 3\nnumbers 1 1 0 0 12\nfree 1 1 1 3 0\n8\nexact 1 0 0 0 8\nfree 1 0 1 8 0\n0\nempty 0 0 1 0 0\nfree 0 0 2 0 0\n0 true\nemptied 1 0 1 8 0\nfree 1 0 2 0 0\nheap 0 0\n", run_0.stdout);
    try std.testing.expectEqual(0, run_0.term.exited);
}

test "Generator.generate: builds an executable that hands receivers to methods with own and frees every allocation" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container::ArrayList\nimport mn::convert::ToOwned\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [65536]u8\n    used: usize\n    live: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(counting: *Counting, items: []T, count: usize) -> bool\n        if (count > items.length) return false\n        counting.live -= mn::size(T) * (items.length - count)\n        return true\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        counting.live -= mn::size(T) * items.length\n\nstruct Builder\n    own list: ArrayList(u8)\n\n    fn finish(own self: *Self, suffix: u8) -> own memory::Error![]u8\n        try self.list.append(suffix)\n        return self.list.to_owned(own)\n\nfn run(counting: *Counting) -> !void\n    with counting\n    var own builder = Builder{ list = ArrayList(u8)::init() }\n    errdefer builder.list.deinit(own)\n    try builder.list.append('a')\n    const own bytes = try builder.finish(own, 'b')\n    defer memory::free(own bytes)\n    var own records = ArrayList([]u8)::init()\n    defer records.deinit(own)\n    const own record = try memory::allocate(u8, 3)\n    errdefer memory::free(own record)\n    try records.append(own record)\n    try text::print(&stdout, \"{s} {}\\n\", { bytes, records.length() })\n    while records.pop() as own element\n        memory::free(own element)\n\nfn main -> !void\n    var counting: Counting = undefined\n    counting.used = 0\n    counting.live = 0\n    try run(&counting)\n    try text::print(&stdout, \"live {}\\n\", { counting.live })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("ab 1\nlive 0\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that hands receivers to a method of a struct and of a typeclass that take them over" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
