    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container::ArrayList\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [65536]u8\n    used: usize\n    live: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(_: *Counting, _: []T, _: usize) -> bool = false\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        counting.live -= mn::size(T) * items.length\n\nstruct Store\n    own records: ArrayList([]u8)\n    count: usize\n\n    fn release(own self: *Self)\n        while self.records.pop() as own record\n            memory::free(own record)\n        self.records.deinit(own)\n\nfn fill(store: *Store, size: usize) -> !void\n    const own record = try memory::allocate(u8, size)\n    errdefer memory::free(own record)\n    try store.records.append(own record)\n    store.count += 1\n\nfn main -> !void\n    var counting: Counting = undefined\n    counting.used = 0\n    counting.live = 0\n    with &counting\n    var own store = Store{ records = ArrayList([]u8)::init(), count = 0 }\n    errdefer store.release(own)\n    try fill(&store, 3)\n    try fill(&store, 5)\n    try text::print(&stdout, \"held {} {}\\n\", { store.count, counting.live > 0 })\n    store.release(own)\n    try text::print(&stdout, \"live {}\\n\", { counting.live })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const run_0 = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("held 2 true\nlive 0\n", run_0.stdout);
    try std.testing.expectEqual(0, run_0.term.exited);
}

test "Generator.generate: builds an executable that builds, changes and ends a struct with private fields of another module through its functions" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "buffer.mn", .data = "import mn::memory\nimport mn::memory::Deinit\n\n\nstruct Buffer\n    private own bytes: []u8\n    private length: usize\n\n    fn init() -> own Self = { bytes = {}, length = 0 }\n\n\n    fn push(self: *Self, byte: u8) -> memory::Error!void\n        if self.length == self.bytes.length\n            const own grown = try memory::allocate(u8, self.length + 4)\n            memory::copy(grown[..self.length], self.bytes[..self.length])\n            memory::free(memory::replace(&self.bytes, own grown))\n        self.bytes[self.length] = byte\n        self.length += 1\n\n\n    fn view(self: *const(Self)) -> []const(u8) = self.bytes[..self.length]\n\n\ninstance Deinit(Buffer)\n\n    fn deinit(own buffer: *Buffer) = memory::free(own buffer.bytes)\n" });
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nimport buffer::Buffer\n\nstruct Counting\n    bytes: [65536]u8\n    used: usize\n    live: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(_: *Counting, _: []T, _: usize) -> bool = false\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        counting.live -= mn::size(T) * items.length\n\nfn run(counting: *const(Counting)) -> !void\n    var own buffer = Buffer::init()\n    defer buffer.deinit(own)\n    for byte in \"monolith\"\n        try buffer.push(byte)\n    try text::print(&stdout, \"{s} {} {}\\n\", { buffer.view(), buffer.view().length, counting.live })\n\nfn main -> !void\n    var counting: Counting = undefined\n    counting.used = 0\n    counting.live = 0\n    with &counting\n    try run(&counting)\n    try text::print(&stdout, \"live {}\\n\", { counting.live })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const run_0 = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("monolith 8 8\nlive 0\n", run_0.stdout);
    try std.testing.expectEqual(0, run_0.term.exited);
}

