    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container::HashMap\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [65536]u8\n    used: usize\n    live: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(_: *Counting, _: []T, _: usize) -> bool = false\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        counting.live -= mn::size(T) * items.length\n\nenum Slot\n    Filled: []u8\n    Empty\n\nfn release(own slot: Slot) -> usize\n    match slot\n        case Filled{ own bytes }\n            const length = bytes.length\n            memory::free(own bytes)\n            return length\n        case Empty\n            return 0\n\nfn make() -> own Slot = Slot::Filled{ {} }\n\nfn run() -> !void\n    var own map = HashMap(u8, []u8)::init()\n    defer map.deinit(own)\n    const own bytes = try memory::allocate(u8, 3)\n    errdefer memory::free(own bytes)\n    const key: u8 = 7\n    const own previous = try map.put(&key, own bytes)\n    if previous as own old\n        memory::free(own old)\n    const own found = map.remove(&key)\n    if found as own entry\n        var own { number, removed } = own entry\n        number += 1\n        const length = removed.length\n        memory::free(own removed)\n        try text::print(&stdout, \"removed {} {}\\n\", { number, length })\n    const pair: [u8, bool] = { 1, true }\n    var { count, flag } = pair\n    count += 2\n    flag = !flag\n    try text::print(&stdout, \"pair {} {}\\n\", { count, flag })\n    try text::print(&stdout, \"slot {}\\n\", { release(make()) })\n\nfn main -> !void\n    var counting: Counting = undefined\n    counting.used = 0\n    counting.live = 0\n    with &counting\n    try run()\n    try text::print(&stdout, \"live {}\\n\", { counting.live })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const run_0 = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("removed 8 3\npair 3 false\nslot 0\nlive 0\n", run_0.stdout);
    try std.testing.expectEqual(0, run_0.term.exited);
}

test "Generator.generate: builds an executable that builds cases with their values in braces, matches them in braces and ends with no live allocation" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [4096]u8\n    used: usize\n    live: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(_: *Counting, _: []T, _: usize) -> bool = false\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        counting.live -= mn::size(T) * items.length\n\nenum Data\n    Bytes: []u8\n    Pair: [[]u8, u32]\n    Point: [i32, i32]\n    Count: u32\n    Empty\n\n    fn origin() -> Self = ::Point{ 0, 0 }\n\nfn release(own data: Data) -> usize\n    match data\n        case Bytes{ own bytes }\n            const length = bytes.length\n            memory::free(own bytes)\n            return length\n        case Pair{ own bytes, own count }\n            const length = bytes.length + mn::convert(usize, count)\n            memory::free(own bytes)\n            return length\n        case Point{ _, _ }\n            return 0\n        case Count{ _ }\n            return 0\n        case Empty\n            return 0\n\nfn measure(data: Data) -> i32 = match data\n    case (Point{ x, y }) x + y\n    else 0\n\nfn bump(data: *Data)\n    match data.*\n        case Count{ *count }\n            count.* += 1\n        else\n            noop\n\nfn count_of(data: Data) -> u32 = match data\n    case (Count{ value }) value\n    else 0\n\nfn run() -> !void\n    const own bytes = try memory::allocate(u8, 3)\n    const own first: Data = ::Bytes{ own bytes }\n    try text::print(&stdout, \"bytes {}\\n\", { release(own first) })\n    const own other = try memory::allocate(u8, 2)\n    try text::print(&stdout, \"pair {}\\n\", { release(::Pair{ own other, 5 }) })\n    const start: Data = ::origin()\n    const moved: Data = ::Point{ 3, 4 }\n    try text::print(&stdout, \"points {} {}\\n\", { measure(start), measure(moved) })\n    var counter: Data = ::Count{ 1 }\n    bump(&counter)\n    bump(&counter)\n    try text::print(&stdout, \"count {} {}\\n\", { count_of(counter), count_of(Data::Count{ 7 }) })\n    try text::print(&stdout, \"empty {}\\n\", { count_of(::Empty) })\n\nfn main -> !void\n    var counting: Counting = undefined\n    counting.used = 0\n    counting.live = 0\n    with &counting\n    try run()\n    try text::print(&stdout, \"live {}\\n\", { counting.live })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const run_0 = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("bytes 3\npair 7\npoints 0 7\ncount 3 7\nempty 0\nlive 0\n", run_0.stdout);
    try std.testing.expectEqual(0, run_0.term.exited);
}

