test "Generator.generate: builds an executable that formats text through a counting allocator" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [65536]u8\n    used: usize\n    allowed: usize\n    allocations: usize\n    frees: usize\n    last_free: usize\n    live: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        if (counting.allocations == counting.allowed) return memory::Error::OutOfMemory\n        counting.allocations += 1\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(counting: *Counting, items: []T, count: usize) -> bool\n        if (count > items.length) return false\n        counting.live -= mn::size(T) * (items.length - count)\n        return true\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        counting.frees += 1\n        counting.last_free = items.length\n        counting.live -= mn::size(T) * items.length\n\nfn start(counting: *Counting, allowed: usize)\n    counting.used = 0\n    counting.allowed = allowed\n    counting.allocations = 0\n    counting.frees = 0\n    counting.last_free = 0\n    counting.live = 0\n\nfn report(label: []const(u8), counting: *const(Counting)) -> !void\n    try text::print(&stdout, \"{s} {} {} {}\\n\", { label, counting.frees, counting.last_free, counting.live })\n\nfn main -> !void\n    var counting: Counting = undefined\n    start(&counting, 100)\n    const own longer = try text::format(\"{s}/{s}\", { \"parent\", \"name\" }) with &counting\n    errdefer memory::free(own longer) with &counting\n    try text::print(&stdout, \"{s} {} {}\\n\", { longer, longer.length, counting.live })\n    memory::free(own longer) with &counting\n    try report(\"longer\", &counting)\n    start(&counting, 100)\n    const own empty = try text::format(\"\", {}) with &counting\n    errdefer memory::free(own empty) with &counting\n    try text::print(&stdout, \"{} {} {}\\n\", { empty.length, counting.allocations, counting.live })\n    memory::free(own empty) with &counting\n    try report(\"empty\", &counting)\n    start(&counting, 0)\n    const own owned_63 = text::format(\"x\", {}) with &counting\n    match owned_63\n        case []u8 as own found\n            defer memory::free(own found) with &counting\n            try text::print(&stdout, \"found {}\\n\", { found.length })\n        case OutOfMemory\n            try report(\"first\", &counting)\n    start(&counting, 1)\n    const own owned_68 = text::format(\"{s}\", { \"more than eight bytes\" }) with &counting\n    match owned_68\n        case []u8 as own found\n            defer memory::free(own found) with &counting\n            try text::print(&stdout, \"found {}\\n\", { found.length })\n        case OutOfMemory\n            try report(\"growing\", &counting)\n    start(&counting, 1)\n    const own owned_73 = text::format(\"short\", {}) with &counting\n    match owned_73\n        case []u8 as own found\n            defer memory::free(own found) with &counting\n            try text::print(&stdout, \"found {}\\n\", { found.length })\n        case OutOfMemory\n            try report(\"exact\", &counting)\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const run_0 = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("parent/name 11 11\nlonger 2 11 0\n0 0 0\nempty 2 0 0\nfirst 1 0 0\ngrowing 1 8 0\nfound 5\n", run_0.stdout);
    try std.testing.expectEqual(0, run_0.term.exited);
}

