test "Generator.generate: builds an executable that allocates and frees zero lengths and zero-sized elements through the heap without a leak" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container::ArrayList\nimport mn::convert::ToOwned\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nstruct Marker\n\nstruct Data\n    one: Marker\n    two: [2]Marker\n\nfn main -> !void\n    with memory::Heap\n    const own empty: []u8 = {}\n    defer memory::free(own empty)\n    const own zero = try memory::allocate(u8, 0)\n    defer memory::free(own zero)\n    try text::print(&stdout, \"{} {}\\n\", { zero.length, zero.pointer == empty.pointer })\n    const own zero_numbers = try memory::allocate(i64, 0)\n    defer memory::free(own zero_numbers)\n    const own markers = try memory::allocate(Marker, 3)\n    defer memory::free(own markers)\n    try text::print(&stdout, \"{} {}\\n\", { markers.length, mn::size(Marker) })\n    try text::print(&stdout, \"{} {}\\n\", { memory::resize(markers, 2), memory::resize(markers, 4) })\n    const own data = try memory::allocate(Data, 2)\n    defer memory::free(own data)\n    const own nothing = try memory::allocate([0]i64, 5)\n    defer memory::free(own nothing)\n    const own zero_markers = try memory::allocate(Marker, 0)\n    defer memory::free(own zero_markers)\n    try text::print(&stdout, \"{} {} {}\\n\", { data.length, nothing.length, zero_markers.length })\n    const own single = try memory::create(Marker)\n    defer memory::destroy(own single)\n    var own list = ArrayList(Marker)::init()\n    errdefer list.deinit(own)\n    for _ in 0..20\n        try list.append(Marker{})\n    const own popped = list.pop()\n    try text::print(&stdout, \"{} {}\\n\", { list.length(), popped != null })\n    const own owned: []Marker = try list.to_owned(own)\n    defer memory::free(own owned)\n    try text::print(&stdout, \"{}\\n\", { owned.length })\n    var own other = ArrayList(Marker)::init()\n    defer other.deinit(own)\n    try other.append(Marker{})\n    _ = other.pop()\n    const own none = other.pop()\n    try text::print(&stdout, \"{} {}\\n\", { none == null, other.length() })\n    const own bytes = try memory::allocate(u8, 2)\n    defer memory::free(own bytes)\n    bytes[0] = 1\n    bytes[1] = 2\n    try text::print(&stdout, \"{} {}\\n\", { bytes[0], bytes[1] })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const run_0 = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    const lines = "0 true\n3 0\ntrue false\n2 5 0\n19 true\n19\ntrue 0\n1 2\n";
    try std.testing.expectEqualStrings(lines, run_0.stdout);
    try std.testing.expectEqual(0, run_0.term.exited);

    const source_directory = try build_directory.openDir(std.testing.io, "source", .{});
    defer source_directory.close(std.testing.io);
    try source_directory.writeFile(std.testing.io, .{ .sub_path = "counting.c", .data = "#include <stddef.h>\n#include <stdio.h>\n\nvoid *__real_aligned_alloc(size_t alignment, size_t size);\nvoid __real_free(void *pointer);\n\nstatic size_t allocated;\nstatic size_t freed;\n\nvoid *__wrap_aligned_alloc(size_t alignment, size_t size) {\n    allocated += 1;\n    return __real_aligned_alloc(alignment, size);\n}\n\nvoid __wrap_free(void *pointer) {\n    if (pointer != NULL) freed += 1;\n    __real_free(pointer);\n}\n\n__attribute__((destructor)) static void report(void) {\n    printf(\"allocated %zu freed %zu\\n\", allocated, freed);\n}\n" });
    const counted_build = try std.process.run(allocator, std.testing.io, .{ .argv = &.{ "sh", "-c", "gcc -std=c23 -w -Wl,--wrap=aligned_alloc -Wl,--wrap=free $(find . -name '*.c') -o counted" }, .cwd = .{ .dir = source_directory } });
    try std.testing.expectEqualStrings("", counted_build.stderr);
    try std.testing.expectEqual(0, counted_build.term.exited);
    const counted = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./counted"}, .cwd = .{ .dir = source_directory } });
    try std.testing.expectEqualStrings(lines ++ "allocated 1 freed 1\n", counted.stdout);
    try std.testing.expectEqual(0, counted.term.exited);
}

test "Generator.generate: builds an executable that gives the allocator of a with statement to the rest of its block and what it calls" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container::ArrayList\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [4096]u8\n    used: usize\n    allocations: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        counting.allocations += 1\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + mn::size(T) * count\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(_: *Counting, _: []T, _: usize) -> bool = false\n\n    fn(type T) free(_: *Counting, own _: []const(T)) = noop\n\nfn start(counting: *Counting)\n    counting.used = 0\n    counting.allocations = 0\n\nfn add() -> !void\n    var own list = ArrayList(u8)::init()\n    defer list.deinit(own)\n    try list.append(1)\n\nfn build() -> !usize\n    var local: Counting = undefined\n    start(&local)\n    with &local\n    try add()\n    try add()\n    return local.allocations\n\nfn main -> !void\n    var one: Counting = undefined\n    start(&one)\n    var two: Counting = undefined\n    start(&two)\n    var three: Counting = undefined\n    start(&three)\n    try add() with &three\n    with &one\n    try add()\n    for _ in 0..3\n        try add()\n    if one.allocations > 0\n        with &two\n        try add()\n        try add() with &three\n        if two.allocations > 0\n            try add()\n    try add()\n    const built = try build()\n    try add() with &three\n    try text::print(&stdout, \"{} {} {} {}\\n\", { one.allocations, two.allocations, three.allocations, built })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("5 2 3 2\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

