test "Generator.generate: builds an executable that keeps owning values in a list and a map and frees them all" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container::ArrayList\nimport mn::container::HashMap\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [262144]u8\n    used: usize\n    fail_at: usize\n    allocations: usize\n    frees: usize\n    live: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        counting.allocations += 1\n        if (counting.allocations == counting.fail_at) return memory::Error::OutOfMemory\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(_: *Counting, _: []T, _: usize) -> bool = false\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        counting.frees += 1\n        counting.live -= mn::size(T) * items.length\n\nfn start(counting: *Counting)\n    counting.used = 0\n    counting.fail_at = 0\n    counting.allocations = 0\n    counting.frees = 0\n    counting.live = 0\n\nstruct Record\n    own name: []u8\n    size: usize\n\nfn make(content: []const(u8)) -> own memory::Error!Record\n    const own name = try memory::allocate(u8, content.length)\n    memory::copy(name, content)\n    return { name = own name, size = content.length }\n\nfn key(letter: u8) -> own memory::Error![]u8\n    const own bytes = try memory::allocate(u8, 1)\n    bytes[0] = letter\n    return bytes\n\nfn release(own record: Record) = memory::free(own record.name)\n\nfn main -> !void\n    var counting: Counting = undefined\n    start(&counting)\n    with &counting\n    try fill_records()\n    try fill_table()\n    try text::print(&stdout, \"live {}\\n\", { counting.live })\n\nfn fill_records() -> !void\n    var own records = ArrayList(Record)::init()\n    defer end_records(own &records)\n    try records.append(try make(\"one\"))\n    try records.append(try make(\"three\"))\n    const own last = records.pop() orelse return\n    defer release(own last)\n    try text::print(&stdout, \"{s} {} {}\\n\", { last.name, last.size, records.length() })\n\nfn end_records(own records: *ArrayList(Record))\n    while records.pop() as own record\n        release(own record)\n    records.deinit(own)\n\nfn fill_table() -> !void\n    var own table = HashMap([]u8, Record)::init()\n    defer end_table(own &table)\n    const own letter = try key('a')\n    defer memory::free(own letter)\n    const own first = try table.put(&letter, try make(\"first\"))\n    const first_empty = first == null\n    if first as own old_record\n        release(own old_record)\n    const own replaced = (try table.put(&letter, try make(\"second\"))) orelse return\n    defer release(own replaced)\n    try text::print(&stdout, \"{} {s} {s} {}\\n\", { first_empty, table.keys()[0], replaced.name, table.length() })\n    const lookup_751: []u8 = table.keys()[0]\n    const own entry = table.remove(&lookup_751) orelse return\n    defer memory::free(own entry[0])\n    defer release(own entry[1])\n    try text::print(&stdout, \"{s} {s} {}\\n\", { entry[0], entry[1].name, table.length() })\n\nfn end_table(own table: *HashMap([]u8, Record))\n    while table.pop() as own { key, record }\n        memory::free(own key)\n        release(own record)\n    table.deinit(own)\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("three 5 1\ntrue a first 1\na second 0\nlive 0\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that ends and clones values of types that own nothing through requirements of Deinit and Clone without an instance, a call or an allocation" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Clone\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [256]u8\n    used: usize\n    allocations: usize\n    frees: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        counting.allocations += 1\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(_: *Counting, _: []T, _: usize) -> bool = false\n\n    fn(type T) free(counting: *Counting, own _: []const(T))\n        counting.frees += 1\n\nstruct Pair\n    one: u32\n    two: u32\n\nfn end(type T: Deinit, own value: T)\n    var own held = own value\n    held.deinit(own)\n\nfn copy(type T: Clone, value: *const(T)) -> own !T = value.clone()\n\nfn main -> !void\n    var counting: Counting = undefined\n    counting.used = 0\n    counting.allocations = 0\n    counting.frees = 0\n    with &counting\n    end(u32, 5)\n    end(Pair, { one = 1, two = 2 })\n    const number: u32 = 7\n    const copied = try copy(u32, &number)\n    const pair: Pair = { one = 3, two = 4 }\n    const cloned = try copy(Pair, &pair)\n    try text::print(&stdout, \"{} {} {}\\n\", { copied, cloned.one, cloned.two })\n    try text::print(&stdout, \"{} {}\\n\", { counting.allocations, counting.frees })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("7 3 4\n0 0\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
    const source = try output_directory.dir.readFileAlloc(std.testing.io, "build/source/main.c", allocator, .unlimited);
    try std.testing.expect(std.mem.indexOf(u8, source, "Deinit_deinit") == null);
    try std.testing.expect(std.mem.indexOf(u8, source, "Clone_clone") == null);
}

