test "Generator.generate: builds an executable that pops and frees each element of a list and each value of a map in a loop through a written instance of Deinit" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container::ArrayList\nimport mn::container::HashMap\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [262144]u8\n    used: usize\n    live: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(_: *Counting, _: []T, _: usize) -> bool = false\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        counting.live -= mn::size(T) * items.length\n\nstruct Order\n    numbers: [8]u8\n    count: usize\n\nstruct Record\n    own name: []u8\n    number: u8\n    order: *Order\n\ninstance Deinit(Record)\n\n    fn deinit(own record: *Record)\n        memory::free(own record.name)\n        record.order.numbers[record.order.count] = record.number\n        record.order.count += 1\n\nfn make(number: u8, order: *Order) -> own memory::Error!Record\n    const own name = try memory::allocate(u8, mn::convert(usize, number))\n    return { name = own name, number = number, order = order }\n\nfn main -> !void\n    var counting: Counting = undefined\n    counting.used = 0\n    counting.live = 0\n    var order: Order = undefined\n    order.count = 0\n    with &counting\n    try fill_list(&order, &counting)\n    try text::print(&stdout, \"freed {} {}\\n\", { counting.live, order.count })\n    try fill_map(&order, &counting)\n    try text::print(&stdout, \"freed {} {}\\n\", { counting.live, order.count })\n    try text::print(&stdout, \"{} {} {} {} {}\\n\", { order.numbers[0], order.numbers[1], order.numbers[2], order.numbers[3], order.numbers[4] })\n\nfn fill_list(order: *Order, counting: *const(Counting)) -> !void\n    var own list = ArrayList(Record)::init()\n    defer end_list(own &list)\n    try list.append(try make(1, order))\n    try list.append(try make(2, order))\n    try list.append(try make(3, order))\n    try text::print(&stdout, \"list {} {}\\n\", { counting.live > 0, order.count })\n\nfn end_list(own list: *ArrayList(Record))\n    while list.pop() as own record\n        record.deinit(own)\n    list.deinit(own)\n\nfn fill_map(order: *Order, counting: *const(Counting)) -> !void\n    var own map = HashMap(u32, Record)::init()\n    defer end_map(own &map)\n    const four: u32 = 4\n    const own first = try map.put(&four, try make(4, order))\n    if first as own record\n        record.deinit(own)\n    const five: u32 = 5\n    const own second = try map.put(&five, try make(5, order))\n    if second as own record\n        record.deinit(own)\n    try text::print(&stdout, \"map {} {}\\n\", { counting.live > 0, order.count })\n\nfn end_map(own map: *HashMap(u32, Record))\n    while map.pop() as own { _, record }\n        record.deinit(own)\n    map.deinit(own)\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("list true 0\nfreed 0 3\nmap true 3\nfreed 0 5\n3 2 1 5 4\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that moves parts out of owned values, ends the rest through the addresses of their fields and leaves no live memory" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container::ArrayList\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [4096]u8\n    used: usize\n    live: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(_: *Counting, _: []T, _: usize) -> bool = false\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        counting.live -= mn::size(T) * items.length\n\nstruct Record\n    own name: []u8\n    own list: ArrayList(u8)\n    size: usize\n\nstruct Owner\n    own record: Record\n    count: usize\n\nfn text_of(content: []const(u8)) -> own memory::Error![]u8\n    const own bytes = try memory::allocate(u8, content.length)\n    memory::copy(bytes, content)\n    return bytes\n\nfn end_list(own list: *ArrayList(u8)) = list.deinit(own)\n\nfn end_pair(own pair: [[]u8, []u8])\n    memory::free(own pair[0])\n    memory::free(own pair[1])\n\nfn run() -> !void\n    var own owner = Owner{ record = { name = try text_of(\"abc\"), list = ArrayList(u8)::init(), size = 3 }, count = 1 }\n    defer end_list(own &owner.record.list)\n    const own name = own owner.record.name\n    defer memory::free(own name)\n    try owner.record.list.append(7)\n    try text::print(&stdout, \"{s} {} {} {}\\n\", { name, owner.record.list.length(), owner.record.size, owner.count })\n    const own pair: [[]u8, []u8] = { try text_of(\"de\"), try text_of(\"f\") }\n    defer end_pair(own pair)\n    try text::print(&stdout, \"{s} {s}\\n\", { pair[0], pair[1] })\n\nfn main -> !void\n    var counting: Counting = undefined\n    counting.used = 0\n    counting.live = 0\n    try run() with &counting\n    try text::print(&stdout, \"live {}\\n\", { counting.live })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const source = try output_directory.dir.readFileAlloc(std.testing.io, "build/source/main.c", allocator, .unlimited);
    try std.testing.expect(std.mem.indexOf(u8, source, "(&owner.record.list") != null);
    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("abc 1 3 1\nde f\nlive 0\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that moves owned values into the elements of tuples and arrays and the cases of enums and leaves no live memory" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [262144]u8\n    used: usize\n    fail_at: usize\n    allocations: usize\n    frees: usize\n    live: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        counting.allocations += 1\n        if (counting.allocations == counting.fail_at) return memory::Error::OutOfMemory\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(counting: *Counting, items: []T, count: usize) -> bool\n        if (count > items.length) return false\n        counting.live -= mn::size(T) * (items.length - count)\n        return true\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        counting.frees += 1\n        counting.live -= mn::size(T) * items.length\n\nfn start(counting: *Counting)\n    counting.used = 0\n    counting.fail_at = 0\n    counting.allocations = 0\n    counting.frees = 0\n    counting.live = 0\n\nenum Data\n    Bytes: []u8\n    Nothing\n\nfn make(size: usize) -> own memory::Error![]u8\n    const own bytes = try memory::allocate(u8, size)\n    for (index in 0..size) bytes[index] = 'a' + mn::truncate(u8, index)\n    return bytes\n\nfn release(own data: Data)\n    match data\n        case Bytes{ own items }\n            memory::free(own items)\n        else noop\n\nfn content(data: *const(Data)) -> []const(u8) = match data.*\n    case (Bytes{ items }) items\n    else \"\"\n\nfn main -> !void\n    var counting: Counting = undefined\n    start(&counting)\n    try run(&counting)\n    try text::print(&stdout, \"live {}\\n\", { counting.live })\n\nfn run(counting: *Counting) -> !void\n    with counting\n    const own one = try make(1)\n    errdefer memory::free(own one)\n    const own two = try make(2)\n    const own pair: [[]u8, []u8] = { own one, own two }\n    defer memory::free(own pair[0])\n    defer memory::free(own pair[1])\n    const own first = try make(3)\n    errdefer memory::free(own first)\n    const own items: [2][]u8 = { own first, try make(4) }\n    defer memory::free(own items[0])\n    defer memory::free(own items[1])\n    const own three = try make(5)\n    const own data = Data::Bytes{ own three }\n    defer release(own data)\n    const own other: Data = ::Bytes{ try make(6) }\n    defer release(own other)\n    try text::print(&stdout, \"pair {s} {s}\\n\", { pair[0], pair[1] })\n    try text::print(&stdout, \"items {s} {s}\\n\", { items[0], items[1] })\n    try text::print(&stdout, \"data {s} {s}\\n\", { content(&data), content(&other) })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("pair a ab\nitems abc abcd\ndata abcde abcdef\nlive 0\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that goes over Iterables through their cursors, keeping pointers with * and copying out of them without" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container::HashMap\nimport mn::iterator::Iterable\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::range\nimport mn::text\n\nstruct Counting\n    bytes: [262144]u8\n    used: usize\n    fail_at: usize\n    allocations: usize\n    frees: usize\n    live: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        counting.allocations += 1\n        if (counting.allocations == counting.fail_at) return memory::Error::OutOfMemory\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(counting: *Counting, items: []T, count: usize) -> bool\n        if (count > items.length) return false\n        counting.live -= mn::size(T) * (items.length - count)\n        return true\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        counting.frees += 1\n        counting.live -= mn::size(T) * items.length\n\nfn start(counting: *Counting)\n    counting.used = 0\n    counting.fail_at = 0\n    counting.allocations = 0\n    counting.frees = 0\n    counting.live = 0\n\nstruct Deck\n    cards: [3]u32\n\n\ninstance Iterable(*Deck, mn::iterator::SliceIterator([]u32))\n\n    fn iterator(deck: *Deck) -> mn::iterator::SliceIterator([]u32) = { remaining = deck.cards[..] }\n\n\nfn(type T: Iterable(_, C), type C) count(values: T) -> usize\n    var result: usize = 0\n    for (_ in values) result += 1\n    return result\n\n\nfn main -> !void\n    var counting: Counting = undefined\n    start(&counting)\n    try run(&counting)\n    try text::print(&stdout, \"live {}\\n\", { counting.live })\n\n\nfn run(counting: *Counting) -> !void\n    with counting\n    var deck: Deck = { cards = { 1, 2, 3 } }\n    for (*card in &deck) card.* += 10\n    var deck_sum: u32 = 0\n    for (card in &deck) deck_sum += card\n    try text::print(&stdout, \"deck {} {} {}\\n\", { deck_sum, deck.cards[0], count(&deck) })\n    const range: mn::range::Range = 2..5\n    var range_sum: usize = 0\n    for (index in range) range_sum += index\n    try text::print(&stdout, \"range {} {}\\n\", { range_sum, count(range) })\n    var own map: HashMap(u32, u32) = ::init()\n    defer map.deinit(own)\n    const one: u32 = 1\n    _ = try map.put(&one, 10)\n    const two: u32 = 2\n    _ = try map.put(&two, 20)\n    for { *key, *value } in map.iterator()\n        value.* += key.*\n    var keys: u32 = 0\n    var values: u32 = 0\n    for { key, value } in map.iterator()\n        keys += key\n        values += value\n    try text::print(&stdout, \"map {} {} {}\\n\", { keys, values, count(map.keys()) })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("deck 36 11 3\nrange 9 3\nmap 3 33 2\nlive 0\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that clones a literal key into a map and a view into a list and leaves no live memory" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
