    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container::ArrayList\nimport mn::container::HashMap\nimport mn::convert::View\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Clone\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [4096]u8\n    used: usize\n    live: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(_: *Counting, _: []T, _: usize) -> bool = false\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        counting.live -= mn::size(T) * items.length\n\nfn end_map(own map: *HashMap([]const(u8), u8))\n    while map.pop() as own { key, _ }\n        memory::free(own key)\n    map.deinit(own)\n\nfn end_list(own list: *ArrayList([]u8))\n    while list.pop() as own item\n        memory::free(own item)\n    list.deinit(own)\n\nfn run() -> !void\n    var own map = HashMap([]const(u8), u8)::init()\n    defer end_map(own &map)\n    const first = try map.put(\"alpha\", 1)\n    const replaced = first == null\n    const lookup: []const(u8) = \"alpha\"\n    try text::print(&stdout, \"{} {} {}\\n\", { replaced, map.length(), map.get(&lookup).?.* })\n    var own list = ArrayList([]u8)::init()\n    defer end_list(own &list)\n    var letters: [2]u8 = { 'o', 'k' }\n    const view: []u8 = letters[..]\n    try list.append(try view.clone())\n    letters[0] = 'n'\n    try text::print(&stdout, \"{s} {s}\\n\", { list.view([]const([]u8))[0], view })\n\nfn main -> !void\n    var counting: Counting = undefined\n    counting.used = 0\n    counting.live = 0\n    try run() with &counting\n    try text::print(&stdout, \"live {}\\n\", { counting.live })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
