test "Generator.generate: builds an executable that pops and frees lists, maps and paths held in lists in a loop through the instances of the library" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container::ArrayList\nimport mn::container::HashMap\nimport mn::convert::To\nimport mn::filesystem\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [262144]u8\n    used: usize\n    live: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(_: *Counting, _: []T, _: usize) -> bool = false\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        counting.live -= mn::size(T) * items.length\n\nfn main -> !void\n    var counting: Counting = undefined\n    counting.used = 0\n    counting.live = 0\n    with &counting\n    try fill_lists(&counting)\n    try text::print(&stdout, \"freed {}\\n\", { counting.live })\n    try fill_paths()\n    try text::print(&stdout, \"paths {}\\n\", { counting.live })\n    try fill_maps()\n    try text::print(&stdout, \"freed {}\\n\", { counting.live })\n    try end_through_typeclass()\n    try text::print(&stdout, \"typeclass {}\\n\", { counting.live })\n    try end_through_function()\n    try text::print(&stdout, \"method {}\\n\", { counting.live })\n\nfn end_lists(own lists: *ArrayList(ArrayList(u8)))\n    while lists.pop() as own list\n        list.deinit(own)\n    lists.deinit(own)\n\n\nfn end_paths(own paths: *ArrayList(filesystem::Path))\n    while paths.pop() as own path\n        path.deinit(own)\n    paths.deinit(own)\n\n\nfn end_maps(own maps: *ArrayList(HashMap(u8, u8)))\n    while maps.pop() as own map\n        map.deinit(own)\n    maps.deinit(own)\n\nfn list_of(values: []const(u8)) -> own !ArrayList(u8)\n    var own list = ArrayList(u8)::init()\n    errdefer list.deinit(own)\n    for (value in values) try list.append(value)\n    return list\n\nfn fill_lists(counting: *const(Counting)) -> !void\n    var own lists = ArrayList(ArrayList(u8))::init()\n    defer end_lists(own &lists)\n    try lists.append(try list_of({ 1 }))\n    try lists.append(try list_of({ 2, 3 }))\n    try text::print(&stdout, \"lists {}\\n\", { counting.live > 0 })\n\nfn fill_paths() -> !void\n    var own paths = ArrayList(filesystem::Path)::init()\n    defer end_paths(own &paths)\n    try paths.append(try \"a/b\".to(filesystem::Path))\n    try paths.append(try \"c\".to(filesystem::Path))\n\nfn map_of(key: u8, value: u8) -> own !HashMap(u8, u8)\n    var own map = HashMap(u8, u8)::init()\n    errdefer map.deinit(own)\n    _ = try map.put(&key, value)\n    return map\n\nfn fill_maps() -> !void\n    var own maps = ArrayList(HashMap(u8, u8))::init()\n    defer end_maps(own &maps)\n    try maps.append(try map_of(1, 2))\n\nfn end_through_typeclass() -> !void\n    var own single = ArrayList(u8)::init()\n    defer single.deinit(own)\n    try single.append(7)\n\nfn end_through_function() -> !void\n    var own method = ArrayList(u8)::init()\n    defer method.deinit(own)\n    try method.append(8)\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("lists true\nfreed 0\npaths 0\nfreed 0\ntypeclass 0\nmethod 0\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that frees through the allocator in effect where each defer and errdefer is written" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container::ArrayList\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [4096]u8\n    used: usize\n    allocations: usize\n    frees: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        counting.allocations += 1\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + mn::size(T) * count\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(_: *Counting, _: []T, _: usize) -> bool = false\n\n    fn(type T) free(counting: *Counting, own _: []const(T))\n        counting.frees += 1\n\nfn start(counting: *Counting)\n    counting.used = 0\n    counting.allocations = 0\n    counting.frees = 0\n\nerror Failure\n    Stopped\n\nfn run(one: *Counting, two: *Counting, three: *Counting) -> !void\n    with one\n    var own first = ArrayList(u8)::init()\n    defer first.deinit(own)\n    try first.append(1)\n    with two\n    var own second = ArrayList(u8)::init()\n    defer second.deinit(own)\n    try second.append(1)\n    if two.allocations > 0\n        var own third = ArrayList(u8)::init()\n        defer third.deinit(own)\n        with three\n        try third.append(1)\n\nfn fail(one: *Counting, two: *Counting) -> !void\n    with one\n    var own kept = ArrayList(u8)::init()\n    errdefer kept.deinit(own)\n    try kept.append(1)\n    with two\n    var own dropped = ArrayList(u8)::init()\n    errdefer dropped.deinit(own)\n    try dropped.append(1)\n    return Failure::Stopped\n\nfn main -> !void\n    var one: Counting = undefined\n    start(&one)\n    var two: Counting = undefined\n    start(&two)\n    var three: Counting = undefined\n    start(&three)\n    try run(&one, &two, &three)\n    try text::print(&stdout, \"{} {} {} {} {} {}\\n\", { one.allocations, one.frees, two.allocations, two.frees, three.allocations, three.frees })\n    start(&one)\n    start(&two)\n    match fail(&one, &two)\n        case (Failure::Stopped) try text::print(&stdout, \"stopped\\n\", {})\n        else try text::print(&stdout, \"other\\n\", {})\n    try text::print(&stdout, \"{} {} {} {}\\n\", { one.allocations, one.frees, two.allocations, two.frees })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("1 1 1 2 1 0\nstopped\n1 1 1 1\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

