    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [4096]u8\n    used: usize\n    allocations: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        counting.allocations += 1\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + mn::size(T) * count\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(_: *Counting, _: []T, _: usize) -> bool = false\n\n    fn(type T) free(_: *Counting, own _: []const(T)) = noop\n\nfn start(counting: *Counting)\n    counting.used = 0\n    counting.allocations = 0\n\nfn mixed(local: *Counting, inner: *Counting) -> !void\n    with allocator\n    const own ignored_28 = try allocator.allocate(u8, 1)\n    allocator.free(own ignored_28)\n    with local\n    with allocator\n    const own ignored_31 = try allocator.allocate(u8, 1)\n    allocator.free(own ignored_31)\n    const own ignored_32 = try allocator.allocate(u8, 1)\n    allocator.free(own ignored_32)\n    if local.allocations > 0\n        with inner\n        with allocator\n        const own ignored_36 = try allocator.allocate(u8, 1)\n        allocator.free(own ignored_36)\n    const own ignored_37 = try memory::allocate(u8, 1)\n    memory::free(own ignored_37)\n\n\nfn isolated() -> !usize\n    var counting: Counting = undefined\n    start(&counting)\n    with &counting\n    with allocator\n    const own ignored_46 = try allocator.allocate(u8, 1)\n    allocator.free(own ignored_46)\n    return counting.allocations\n\nfn main -> !void\n    var given: Counting = undefined\n    start(&given)\n    var local: Counting = undefined\n    start(&local)\n    var inner: Counting = undefined\n    start(&inner)\n    try mixed(&local, &inner) with &given\n    const owned = try isolated()\n    try text::print(&stdout, \"{} {} {} {}\\n\", { given.allocations, local.allocations, inner.allocations, owned })\n" });
