test "Generator.generate: builds an executable without a warning that slices pointers to zero-sized elements and runs each call once" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::process::stdout\nimport mn::text\n\nstruct Marker\n\nstruct Data\n    pointer: *many(Marker)\n    value: i32\n\nerror Error\n    Failed\n\nenum Choice\n    One: i32\n    Two\n\nstruct Tagged\n    choice: Choice\n    pointer: *many(Marker)\n\nfn make(counter: *i32) -> *many(Marker)\n    counter.* += 1\n    return mn::cast(*many(Marker), counter)\n\nfn make_data(counter: *i32) -> Data\n    counter.* += 1\n    return { pointer = mn::cast(*many(Marker), counter), value = 1 }\n\nfn attempt(counter: *i32) -> Error!*many(Marker)\n    counter.* += 1\n    return mn::cast(*many(Marker), counter)\n\nfn next(counter: *i32) -> usize\n    counter.* += 10\n    return 1\n\nfn identity(counter: *i32, pointer: *many(Marker)) -> *many(Marker)\n    counter.* += 100\n    return pointer\n\ninline fn make_inline(counter: *i32) -> *many(Marker)\n    counter.* += 1\n    return mn::cast(*many(Marker), counter)\n\nfn slice_cast(pointer: *void, count: usize) -> []Marker = return mn::cast(*many(Marker), pointer)[0..count]\n\nfn slice_nested_cast(pointer: *void, count: usize) -> []Marker = return mn::cast(*many(Marker), mn::cast(*many(u8), pointer))[0..count]\n\nfn slice_cast_of_call(counter: *i32, count: usize) -> []Marker = return mn::cast(*many(Marker), mn::cast(*void, make(counter)))[0..count]\n\nfn slice_cast_of_field(counter: *i32, count: usize) -> []Marker = return mn::cast(*many(Marker), make_data(counter).pointer)[0..count]\n\nfn slice_case_field(pointer: *many(Marker), count: usize) -> []Marker = return Tagged{ choice = Choice::One{ 1 }, pointer = pointer }.pointer[0..count]\n\nfn slice_before_call(counter: *i32, count: usize) -> []Marker = return make(counter)[next(counter)..count]\n\nfn slice_cast_before_call(counter: *i32, pointer: *void, count: usize) -> []Marker = return mn::cast(*many(Marker), pointer)[next(counter)..count]\n\nfn slice_cast_of_call_before_call(counter: *i32, count: usize) -> []Marker = return mn::cast(*many(Marker), mn::cast(*void, make(counter)))[next(counter)..count]\n\nfn slice_variable_before_call(counter: *i32, count: usize) -> []Marker\n    var pointer = make(counter)\n    pointer = identity(counter, pointer)\n    return pointer[next(counter)..count]\n\nfn slice_try(counter: *i32, count: usize) -> Error![]Marker\n    return (try attempt(counter))[0..count]\n\nfn slice_cast_of_try(counter: *i32, count: usize) -> Error![]Marker\n    return mn::cast(*many(Marker), mn::cast(*void, try attempt(counter)))[0..count]\n\nfn slice_call_of_try(counter: *i32, count: usize) -> Error![]Marker\n    return identity(counter, try attempt(counter))[0..count]\n\nfn slice_branch(counter: *i32, flag: bool, count: usize) -> []Marker\n    return (if (flag) make(counter) else identity(counter, make(counter)))[0..count]\n\nfn slice_cast_of_branch(flag: bool, pointer: *void, count: usize) -> []Marker\n    return mn::cast(*many(Marker), if (flag) pointer else pointer)[0..count]\n\nfn slice_inline(counter: *i32, count: usize) -> []Marker\n    return make_inline(counter)[0..count]\n\nfn slice_of_slice(counter: *i32, count: usize) -> []Marker\n    return make(counter)[0..count][1..]\n\nfn report(label: []const(u8), length: usize, counter: *i32) -> !void\n    try text::print(&stdout, \"{s} {} {}\\n\", { label, length, counter.* })\n    counter.* = 0\n\nfn main -> !void\n    var counter: i32 = 0\n    const pointer = mn::cast(*void, &counter)\n    try report(\"cast\", slice_cast(pointer, 3).length, &counter)\n    try report(\"nested\", slice_nested_cast(pointer, 3).length, &counter)\n    try report(\"call\", slice_cast_of_call(&counter, 3).length, &counter)\n    try report(\"field\", slice_cast_of_field(&counter, 3).length, &counter)\n    try report(\"case\", slice_case_field(mn::cast(*many(Marker), pointer), 3).length, &counter)\n    try report(\"before\", slice_before_call(&counter, 3).length, &counter)\n    try report(\"cast before\", slice_cast_before_call(&counter, pointer, 3).length, &counter)\n    try report(\"call before\", slice_cast_of_call_before_call(&counter, 3).length, &counter)\n    try report(\"variable\", slice_variable_before_call(&counter, 3).length, &counter)\n    try report(\"try\", (try slice_try(&counter, 3)).length, &counter)\n    try report(\"cast try\", (try slice_cast_of_try(&counter, 3)).length, &counter)\n    try report(\"call try\", (try slice_call_of_try(&counter, 3)).length, &counter)\n    try report(\"branch\", slice_branch(&counter, false, 3).length, &counter)\n    try report(\"cast branch\", slice_cast_of_branch(true, pointer, 3).length, &counter)\n    try report(\"inline\", slice_inline(&counter, 3).length, &counter)\n    try report(\"slice\", slice_of_slice(&counter, 3).length, &counter)\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);
    const source_directory = try build_directory.openDir(std.testing.io, "source", .{});
    defer source_directory.close(std.testing.io);
    const strict = try std.process.run(allocator, std.testing.io, .{ .argv = &.{ "sh", "-c", "gcc -std=c23 -Wall -Wextra -Wno-unused-parameter -Wno-unused-variable -pedantic -O2 -flto -Werror $(find . -name '*.c') -o strict" }, .cwd = .{ .dir = source_directory } });
    try std.testing.expectEqualStrings("", strict.stderr);
    try std.testing.expectEqual(0, strict.term.exited);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("cast 3 0\nnested 3 0\ncall 3 1\nfield 3 1\ncase 3 0\nbefore 2 11\ncast before 2 10\ncall before 2 11\nvariable 2 111\ntry 3 1\ncast try 3 1\ncall try 3 101\nbranch 3 101\ncast branch 3 0\ninline 3 1\nslice 2 1\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

