    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::container::HashMap\nimport mn::convert::To\nimport mn::filesystem::Path\nimport mn::memory\nimport mn::memory::Clone\nimport mn::memory::Deinit\nimport mn::process\nimport mn::process::stdout\nimport mn::text\nimport mn::time::WallTime\n\nstruct Record\n    own path: Path\n    digest: [32]u8\n    time: WallTime\n\ninstance Deinit(Record)\n\n    fn deinit(own record: *Self) = record.path.deinit(own)\n\nstruct Index\n    own records: HashMap(Path, Record)\n\n    fn init() -> own Self\n        const own records = HashMap(Path, Record)::init()\n        return { records = own records }\n\n    fn put(self: *Self, own record: Record) -> !void\n        const own key = try record.path.clone()\n        errdefer key.deinit(own)\n        const slot = try self.records.get_or_put(&record.path)\n        if slot.found\n            key.deinit(own)\n            const own old = memory::replace(slot.value, own record)\n            old.deinit(own)\n        else\n            slot.key.* = own key\n            slot.value.* = own record\n\ninstance Deinit(Index)\n\n    fn deinit(own index: *Self)\n        while index.records.pop() as own { key, value }\n            key.deinit(own)\n            value.deinit(own)\n        index.records.deinit(own)\n\nfn add(index: *Index, name: []const(u8), seed: u8) -> !void\n    var digest: [32]u8 = undefined\n    for position in 0..32\n        digest[position] = seed\n    const own path = try name.to(Path)\n    try index.put({ path = own path, digest = digest, time = WallTime::now() })\n\nfn main -> !void\n    with memory::Heap\n    var own index = Index::init()\n    defer index.deinit(own)\n    for argument in process::arguments()\n        try add(&index, argument, argument[0])\n    try add(&index, \"fixed\", 7)\n    for argument in process::arguments()\n        var digest: [32]u8 = undefined\n        for position in 0..32\n            digest[position] = argument[0]\n        const own path = try argument.to(Path)\n        try index.put({ path = own path, digest = digest, time = WallTime::now() })\n    try text::print(&stdout, \"{}\\n\", { index.records.length() })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);
    const source_directory = try build_directory.openDir(std.testing.io, "source", .{});
    defer source_directory.close(std.testing.io);
    const strict = try std.process.run(allocator, std.testing.io, .{ .argv = &.{ "sh", "-c", "gcc -std=c23 -Wall -Wextra -Wno-unused-parameter -Wno-unused-variable -pedantic -O2 -flto -Werror $(find . -name '*.c') -o strict" }, .cwd = .{ .dir = source_directory } });
    try std.testing.expectEqualStrings("", strict.stderr);
    try std.testing.expectEqual(0, strict.term.exited);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{ "./main", "one", "two", "one" }, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("3\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

