test "Generator.generate: builds an executable that takes the enum of a case from the surrounding code" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "other.mn", .data = "enum Mode\n    Write\n    Read\n\nfn code(mode: Mode) -> u8 = match mode\n    case (Write) 7\n    case (Read) 8\n" });
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::process::stdout\nimport mn::stream::Writer\nimport mn::text\nimport other\n\nenum Mode\n    Read\n    Write\n\nenum Token\n    Name: []const(u8)\n    Number: u32\n    End\n\nstruct Holder\n    mode: Mode\n    fallback: Mode = ::Write\n\nstruct Outer\n    enum Inner\n        Left\n        Right\n\nerror Failure\n    Bad\n\nfn match(number: u8) -> u8 = number + 1\n\nfn code(mode: Mode) -> u8 = match mode\n    case (Read) 1\n    case (Write) 2\n\nfn code_optional(mode: ?Mode) -> u8 = match mode\n    case (null) 0\n    case (Mode as value) code(value)\n\nfn code_inner(inner: Outer::Inner) -> u8 = match inner\n    case (Left) 3\n    case (Right) 4\n\nfn describe(token: Token) -> !void\n    match token\n        case Name{ content }\n            try text::print(&stdout, \"{s}\\n\", { content })\n        case Number{ value }\n            try text::print(&stdout, \"{}\\n\", { value })\n        case End\n            try text::print(&stdout, \"end\\n\", {})\n\nfn give() -> Mode\n    return ::Write\n\nfn give_one_line() -> Mode = ::Write\n\nfn give_last_line() -> Mode\n    const unused_free: u8 = 0\n    if (unused_free == 1) return ::Read\n    ::Write\n\nfn give_branch(flag: bool) -> Mode = if (flag) ::Write else ::Read\n\nfn give_match(number: u8) -> Mode = match number\n    case (0) ::Write\n    else ::Read\n\nfn give_optional() -> ?Mode = ::Write\n\nfn give_none() -> ?Mode = null\n\nfn give_result(flag: bool) -> Failure!Mode\n    if (flag) return Failure::Bad\n    return ::Write\n\nfn main -> !void\n    try text::print(&stdout, \"argument {}\\n\", { code(::Write) })\n    const spanning = code(\n        ::Write\n    )\n    try text::print(&stdout, \"spanning {}\\n\", { spanning })\n    const annotated: Mode = ::Write\n    try text::print(&stdout, \"annotated {}\\n\", { code(annotated) })\n    var assigned: Mode = ::Read\n    assigned = ::Write\n    try text::print(&stdout, \"assignment {}\\n\", { code(assigned) })\n    try text::print(&stdout, \"return {} {} {}\\n\", { code(give()), code(give_one_line()), code(give_last_line()) })\n    try text::print(&stdout, \"branch {} {}\\n\", { code(give_branch(true)), code(give_match(0)) })\n    const holder = Holder{ mode = ::Read }\n    try text::print(&stdout, \"field {} {}\\n\", { code(holder.mode), code(holder.fallback) })\n    const items: [2]Mode = { ::Read, ::Write }\n    const pair: [Mode, bool] = { ::Write, true }\n    const slice: []const(Mode) = { ::Write, ::Read }\n    try text::print(&stdout, \"elements {} {} {} {}\\n\", { code(items[1]), code(pair[0]), code(slice[0]), code(slice[1]) })\n    try text::print(&stdout, \"equal {} {} {} {}\\n\", { annotated == ::Write, ::Read == annotated, annotated != ::Write, annotated != ::Read })\n    const optional: ?Mode = ::Write\n    try text::print(&stdout, \"optional {} {} {}\\n\", { code_optional(optional), code_optional(::Read), code_optional(give_optional()) })\n    try text::print(&stdout, \"orelse {}\\n\", { code(give_none() orelse ::Write) })\n    try text::print(&stdout, \"catch {}\\n\", { code(give_result(true) catch ::Write) })\n    const result = try give_result(false)\n    try text::print(&stdout, \"result {}\\n\", { code(result) })\n    const token: Token = ::Name{ \"cards\" }\n    try describe(token)\n    try describe(::Number{ 7 })\n    try describe(::End)\n    const read: u8 = 40\n    try text::print(&stdout, \"local {}\\n\", { read + code(::Read) })\n    const Mode: u8 = 50\n    try text::print(&stdout, \"shadowed {}\\n\", { Mode + code(::Write) })\n    const nested: Outer::Inner = ::Right\n    try text::print(&stdout, \"nested {} {}\\n\", { code_inner(nested), code_inner(::Left) })\n    try text::print(&stdout, \"module {} {}\\n\", { other::code(::Read), other::code(::Write) })\n    const module: u8 = 3\n    try text::print(&stdout, \"current {} {}\\n\", { module, module::match(4) })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings(
        "argument 2\nspanning 2\nannotated 2\nassignment 2\nreturn 2 2 2\nbranch 2 2\nfield 1 2\nelements 2 2 2 1\nequal true false false true\noptional 2 1 2\norelse 2\ncatch 2\nresult 2\ncards\n7\nend\nlocal 41\nshadowed 52\nnested 4 3\nmodule 8 7\ncurrent 3 5\n",
        result.stdout,
    );
    try std.testing.expectEqual(0, result.term.exited);
}

