test "Generator.generate: builds an executable that ends inline structs through their fields with nothing left allocated" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::stream::Writer\nimport mn::text\n\nstruct Counting\n    bytes: [256]u8\n    used: usize\n    live: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(_: *Counting, _: []T, _: usize) -> bool = false\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        counting.live -= mn::size(T) * items.length\n\ninline struct Name\n    bytes: []const(u8)\n\ninstance Deinit(Name)\n\n    fn deinit(own name: *Name) = memory::free(own name.bytes)\n\ninline struct Label\n    name: Name\n\nstruct Record\n    own label: Label\n    size: usize\n\nfn make(text: []const(u8)) -> own memory::Error!Name\n    const own bytes = try memory::allocate(u8, text.length)\n    memory::copy(bytes, text)\n    return { bytes = own bytes }\n\nfn first(name: Name) -> u8 = name.bytes[0]\n\nfn run(counting: *const(Counting)) -> !void\n    const own name = try make(\"abc\")\n    const view = name\n    const viewed = first(view)\n    const before = counting.live\n    const own record: Record = { label = { name = own name }, size = view.bytes.length }\n    const held = first(record.label.name)\n    memory::free(own record.label.name.bytes)\n    const freed = counting.live\n    const own other = try make(\"de\")\n    const other_first = first(other)\n    const other_live = counting.live\n    other.deinit(own)\n    try text::print(&stdout, \"{} {} {} {} {} {} {}\\n\", { viewed, before, held, record.size, freed, other_first, other_live })\n\nfn main -> !void\n    var counting: Counting = undefined\n    counting.used = 0\n    counting.live = 0\n    try run(&counting) with &counting\n    try text::print(&stdout, \"{}\\n\", { counting.live })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("97 3 97 3 0 100 2\n0\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

