    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::memory\nimport mn::process::stdout\nimport mn::stream::Writer\nimport mn::text\n\ninline struct Count\n    value: u32\n\nstruct Point\n    x: i32\n    y: i32\n\nstruct Line\n    one: Point\n    two: Point\n    count: Count\n\nstruct Record\n    own name: []u8\n    size: usize\n\nfn make(x: i32, y: i32) -> Point = return { x, y }\n\nfn run() -> !void\n    const x: i32 = 1\n    const y: i32 = 2\n    const two: Point = { y = 5, x }\n    const value: u32 = 7\n    const count = Count{ value }\n    const line = Line{ one = { y, x = 3 }, two, count }\n    const one = make(y, x)\n    const own name = try memory::allocate(u8, 3)\n    const size = name.length\n    const own record = Record{ own name, size }\n    defer memory::free(own record.name)\n    try text::print(&stdout, \"{} {} {} {} {} {} {} {}\\n\", { line.one.x, line.one.y, line.two.x, line.two.y, line.count.value, one.x, one.y, record.size })\n\nfn main -> !void\n    with memory::Heap\n    try run()\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
