    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("3 2 1 5 7 2 1 3\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that joins viewed names to paths, finds their parents and keeps them in a set" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::compare::Equal\nimport mn::container::HashSet\nimport mn::convert::To\nimport mn::convert::View\nimport mn::filesystem\nimport mn::hash::Hash\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Clone\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::stream::Writer\nimport mn::text\n\nstruct Counting\n    bytes: [4096]u8\n    used: usize\n    allocations: usize\n    frees: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        if (start + size > 4096) return memory::Error::OutOfMemory\n        if (count > 0) counting.allocations += 1\n        counting.used = start + size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n    fn(type T) resize(_: *Counting, _: []T, _: usize) -> bool = false\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        if (items.length > 0) counting.frees += 1\n\nfn show(path: filesystem::Path) -> !void\n    const own content = try path.to([]u8)\n    defer memory::free(own content)\n    try text::print(&stdout, \"[{s}] {}\\n\", { content, path.is_absolute() })\n\nfn show_parent(content: []const(u8)) -> !void\n    const own path = try content.to(filesystem::Path)\n    defer path.deinit(own)\n    const own parent = try path.parent()\n    defer parent.deinit(own)\n    try show(parent)\n\nfn run() -> !void\n    const own base = try \"a/b\".to(filesystem::Path)\n    defer base.deinit(own)\n    const own joined = try base.join(\"c\".view(filesystem::Path))\n    defer joined.deinit(own)\n    try show(joined)\n    const own rooted = try \"/\".to(filesystem::Path)\n    defer rooted.deinit(own)\n    const own top = try rooted.join(\"top\".view(filesystem::Path))\n    defer top.deinit(own)\n    try show(top)\n    const own empty = filesystem::Path::init()\n    defer empty.deinit(own)\n    const own alone = try empty.join(\"name\".view(filesystem::Path))\n    defer alone.deinit(own)\n    try show(alone)\n    try show_parent(\"a/b/c\")\n    try show_parent(\"a/b/\")\n    try show_parent(\"/a\")\n    try show_parent(\"/\")\n    try show_parent(\"a\")\n    try show_parent(\"//a\")\n    const own copy = try joined.clone()\n    defer copy.deinit(own)\n    try text::print(&stdout, \"{} {} {}\\n\", { Equal::equal(&copy, &joined), Equal::equal(&copy, &base), Hash::hash(&copy) == Hash::hash(&joined) })\n    var own seen = HashSet(filesystem::Path)::init()\n    defer seen.deinit(own)\n    const own replaced = try seen.insert(try \"x/y\".to(filesystem::Path))\n    if replaced as own old\n        old.deinit(own)\n    const own probe = try \"x/y\".to(filesystem::Path)\n    defer probe.deinit(own)\n    try text::print(&stdout, \"{} {}\\n\", { seen.contains(&probe), seen.contains(&joined) })\n    while seen.pop() as own kept\n        kept.deinit(own)\n\nfn main -> !void\n    var counting: Counting = undefined\n    counting.used = 0\n    counting.allocations = 0\n    counting.frees = 0\n    try run() with &counting\n    try text::print(&stdout, \"{} {}\\n\", { counting.allocations > 0, counting.allocations == counting.frees })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("[a/b/c] false\n[/top] true\n[name] false\n[a/b] false\n[a] false\n[/] true\n[/] true\n[] false\n[/] true\ntrue false true\ntrue false\ntrue true\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

