test "Generator.generate: builds an executable that turns a path into text" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::convert::To\nimport mn::filesystem\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::stream::Writer\nimport mn::text\n\nstruct Fixed\n    bytes: [64]u8\n    used: usize\n\ninstance Allocator(Fixed)\n\n    fn allocate(fixed: *Fixed, type T, count: usize) -> own memory::Error![]T\n        const size = mn::size(T) * count\n        if (fixed.used + size > 64) return memory::Error::OutOfMemory\n        const start = fixed.used\n        fixed.used += size\n        return mn::cast(*many(T), fixed.bytes[start..fixed.used].pointer)[0..count]\n    fn(type T) resize(_: *Fixed, _: []T, _: usize) -> bool = false\n    fn(type T) free(_: *Fixed, own _: []const(T)) = noop\n\nfn through(type Target, value: any) -> own !Target = value.to(Target)\n\nfn save(content: []u8) -> !void\n    try text::print(&stdout, \"saved [{s}]\\n\", { content })\n\nfn show(input: []const(u8)) -> !void\n    var own path = try input.to(filesystem::Path)\n    defer path.deinit(own)\n    const own written = try path.to([]u8)\n    defer memory::free(own written)\n    const own inferred: []u8 = try path.to(_)\n    defer memory::free(own inferred)\n    try text::print(&stdout, \"[{s}] [{s}]\\n\", { written, inferred })\n\nfn main -> !void\n    with memory::Heap\n    try show(\"\")\n    try show(\"/\")\n    try show(\"one\")\n    try show(\"one/two/three\")\n    try show(\"/one/two\")\n    var own path = try \"left/right\".to(filesystem::Path)\n    defer path.deinit(own)\n    var fixed: Fixed = undefined\n    fixed.used = 0\n    const own from_default = try path.to([]u8)\n    defer memory::free(own from_default)\n    try text::print(&stdout, \"default {}\\n\", { fixed.used })\n    const own from_fixed = try path.to([]u8) with &fixed\n    defer memory::free(own from_fixed) with &fixed\n    try text::print(&stdout, \"fixed {} [{s}]\\n\", { fixed.used, from_fixed })\n    const own inferred_fixed: []u8 = try path.to(_) with &fixed\n    defer memory::free(own inferred_fixed) with &fixed\n    try text::print(&stdout, \"fixed {} [{s}]\\n\", { fixed.used, inferred_fixed })\n    const own owned_57: []u8 = try path.to(_)\n    defer memory::free(own owned_57)\n    try save(owned_57)\n    const own generic = try through([]u8, path)\n    defer memory::free(own generic)\n    try text::print(&stdout, \"generic [{s}]\\n\", { generic })\n    const own generic_fixed = try through([]u8, path) with &fixed\n    defer memory::free(own generic_fixed) with &fixed\n    try text::print(&stdout, \"generic fixed {} [{s}]\\n\", { fixed.used, generic_fixed })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings(
        "[] []\n[/] [/]\n[one] [one]\n[one/two/three] [one/two/three]\n[/one/two] [/one/two]\ndefault 0\nfixed 10 [left/right]\nfixed 20 [left/right]\nsaved [left/right]\ngeneric [left/right]\ngeneric fixed 30 [left/right]\n",
        result.stdout,
    );
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that selects an instance by its target" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "convert.mn", .data = "typeclass To(type T, type U)\n\n    fn to(value: T, type U) -> !U\nstruct Data\n    number: u8\ninstance To(Data, u8)\n\n    fn to(value: Data, type U) -> !U = value.number\ninstance To(Data, u16)\n\n    fn to(value: Data, type U) -> !U\n        _ = value\n        return 300\n" });
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "other.mn", .data = "import convert\nimport mn\n\nstruct Large\n    number: u32\n\ninstance convert::To(convert::Data, Large)\n\n    fn to(value: convert::Data, type U) -> !U = Large{ number = mn::convert(u32, value.number) + 1000 }\n" });
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::text\nimport convert\nimport convert::To\nimport mn::stream::Writer\nimport mn::process::stdout\nimport other\n\nfn through(type Target, value: any) -> !Target = value.to(Target)\n\nfn main -> !void\n    const data = convert::Data{ number = 7 }\n    const small = try data.to(u8)\n    const wide = try data.to(u16)\n    try text::print(&stdout, \"{} {}\\n\", { small, wide })\n    const small_generic = try through(u8, data)\n    const wide_generic = try through(u16, data)\n    try text::print(&stdout, \"{} {}\\n\", { small_generic, wide_generic })\n    const large = try data.to(other::Large)\n    const large_generic = try through(other::Large, data)\n    try text::print(&stdout, \"{} {}\\n\", { large.number, large_generic.number })\n    const inferred: other::Large = try data.to(_)\n    try text::print(&stdout, \"{}\\n\", { inferred.number })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
