test "Generator.generate: builds an executable that grows a map through many sizes" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container::HashMap\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nfn main -> !void\n    with memory::Heap\n    var own seen = HashMap(u64, u64)::init()\n    defer seen.deinit(own)\n    var wrong: usize = 0\n    for index in 0..20000\n        const key = mn::convert(u64, index) * 7\n        if (seen.contains(&key) or seen.get(&key) != null) wrong += 1\n        const own added = try seen.put(&key, key + 1)\n        if (added != null) wrong += 1\n        const own repeated = try seen.put(&key, key + 2)\n        if (repeated == null or repeated.? != key + 1) wrong += 1\n        if (!seen.contains(&key) or seen.get(&key).?.* != key + 2) wrong += 1\n    try text::print(&stdout, \"inserted {} wrong {}\\n\", { seen.length(), wrong })\n    for index in 0..20000\n        const key = mn::convert(u64, index) * 7\n        if index % 3 == 0\n            const own removed = seen.remove(&key)\n            if (removed == null or removed.?[0] != key or removed.?[1] != key + 2) wrong += 1\n            const own again = seen.remove(&key)\n            if (again != null) wrong += 1\n        const lookup_281: u64 = key + 1\n        const own owned_27 = seen.remove(&lookup_281)\n        if (owned_27 != null) wrong += 1\n    try text::print(&stdout, \"removed {} wrong {}\\n\", { seen.length(), wrong })\n    for index in 0..20000\n        const key = mn::convert(u64, index) * 7\n        const expected = index % 3 != 0\n        if (seen.contains(&key) != expected) wrong += 1\n        if (expected and seen.get(&key).?.* != key + 2) wrong += 1\n    try text::print(&stdout, \"checked {} wrong {}\\n\", { seen.length(), wrong })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings(
        "inserted 20000 wrong 0\nremoved 13333 wrong 0\nchecked 13333 wrong 0\n",
        result.stdout,
    );
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that keeps a map equal to a list through puts and removes" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::compare\nimport mn::container::ArrayList\nimport mn::container::HashMap\nimport mn::convert::View\nimport mn::hash\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nstruct Entry\n    number: u64\n    value: u64\n\nstruct Clustered\n    number: u64\n\ninstance mn::compare::Equal(Clustered)\n\n    fn equal(one: *const(Clustered), two: *const(Clustered)) -> bool = one.number == two.number\n\ninstance mn::hash::Hash(Clustered)\n\n    fn hash(value: *const(Clustered)) -> u64 = 18446744073709551615 - value.number % 5\n\nfn step(state: u64) -> u64\n    var value = state\n    value ^= value << 13\n    value ^= value >> 7\n    value ^= value << 17\n    return value\n\nfn make_spread(number: u64) -> u64 = number * 1024\n\nfn read_spread(key: u64) -> u64 = key / 1024\n\nfn make_clustered(number: u64) -> Clustered = Clustered{ number = number }\n\nfn read_clustered(key: Clustered) -> u64 = key.number\n\nfn find_model(model: *ArrayList(Entry), number: u64) -> ?usize\n    for index in 0..model.length()\n        if (model.view([]const(Entry))[index].number == number) return index\n    return null\n\nfn check_all(type K, type M, map: *const(M), model: *ArrayList(Entry), make_key: *fn(u64) -> K, read_key: *fn(K) -> u64) -> usize\n    var wrong: usize = 0\n    if (map.length() != model.length() or map.length() != map.length() or map.length() != map.length()) wrong += 1\n    for entry in model.view([]const(Entry))\n        const key = make_key(entry.number)\n        const value = map.get(&key)\n        if (value == null or value.?.* != entry.value or !map.contains(&key)) wrong += 1\n    var marks: [200]u8 = undefined\n    for (index in 0..200) marks[index] = 0\n    for index in 0..map.length()\n        const position = find_model(model, read_key(map.keys()[index]))\n        if position as found\n            marks[mn::convert(usize, model.view([]const(Entry))[found].number)] += 1\n            if (model.view([]const(Entry))[found].value != map.values()[index]) wrong += 1\n        else\n            wrong += 1\n    for { key, value } in map.iterator()\n        const position = find_model(model, read_key(key))\n        if position as found\n            marks[mn::convert(usize, model.view([]const(Entry))[found].number)] += 1\n            if (model.view([]const(Entry))[found].value != value) wrong += 1\n        else\n            wrong += 1\n    for entry in model.view([]const(Entry))\n        if (marks[mn::convert(usize, entry.number)] != 2) wrong += 1\n    return wrong\n\nfn exercise(type K, type M, make_key: *fn(u64) -> K, read_key: *fn(K) -> u64) -> !usize\n    var own map = M::init()\n    defer map.deinit(own)\n    var own model = ArrayList(Entry)::init()\n    defer model.deinit(own)\n    var wrong: usize = 0\n    var state: u64 = 88172645463325252\n    for round in 0..60000\n        state = step(state)\n        const number = state % 200\n        const key = make_key(number)\n        state = step(state)\n        const action = state % 5\n        const value = state >> 8\n        const position = find_model(&model, number)\n        if action < 2\n            const own previous = try map.put(&key, value)\n            if position as found\n                if (previous == null or previous.? != model.view([]const(Entry))[found].value) wrong += 1\n                model.view([]Entry)[found].value = value\n            else\n                if (previous != null) wrong += 1\n                try model.append(Entry{ number = number, value = value })\n        else if action < 4\n            const own removed = map.remove(&key)\n            if position as found\n                if (removed == null or read_key(removed.?[0]) != number or removed.?[1] != model.view([]const(Entry))[found].value) wrong += 1\n                model.view([]Entry)[found] = model.view([]const(Entry))[model.length() - 1]\n                _ = model.pop()\n            else\n                if (removed != null) wrong += 1\n        else\n            const stored = map.get(&key)\n            if position as found\n                if (stored == null or stored.?.* != model.view([]const(Entry))[found].value) wrong += 1\n            else\n                if (stored != null or map.contains(&key)) wrong += 1\n        if (map.length() != model.length()) wrong += 1\n        if (round % 500 == 0) wrong += check_all(K, M, &map, &model, make_key, read_key)\n    wrong += check_all(K, M, &map, &model, make_key, read_key)\n    return wrong\n\nconst SpreadMap = HashMap(u64, u64)\nconst ClusteredMap = HashMap(Clustered, u64)\n\nfn main -> !void\n    with memory::Heap\n    const spread = try exercise(u64, SpreadMap, &make_spread, &read_spread)\n    const clustered = try exercise(Clustered, ClusteredMap, &make_clustered, &read_clustered)\n    try text::print(&stdout, \"wrong {} {}\\n\", { spread, clustered })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings(
        "wrong 0 0\n",
        result.stdout,
    );
    try std.testing.expectEqual(0, result.term.exited);
}

