t own reinserted = try seen.put(&lookup_416, 7)\n    const lookup_417: Key = Key{ number = 299 }\n    if (reinserted != null or seen.get(&lookup_416).?.* != 7 or !seen.contains(&lookup_417)) wrong += 1\n    try text::print(&stdout, \"reinserted {} wrong {}\\n\", { seen.length(), wrong })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
