}

test "Generator.generate: builds an executable that keeps maps of each kind of key" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::compare\nimport mn::container::HashMap\nimport mn::hash\nimport mn::hash::Hash\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::stream\nimport mn::text\n\nstruct Source\n    bytes: []const(u8)\n\ninstance stream::Reader(Source)\n\n    fn read(source: *Source, buffer: []u8) -> !usize\n        const count = if (source.bytes.length < buffer.length) source.bytes.length else buffer.length\n        for (index in 0..count) buffer[index] = source.bytes[index]\n        source.bytes = source.bytes[count..]\n        return count\n\nstruct Point\n    x: i32\n    y: i32\n\ninstance mn::compare::Equal(Point)\n\n    fn equal(one: *const(Point), two: *const(Point)) -> bool = one.x == two.x and one.y == two.y\n\ninstance mn::hash::Hash(Point)\n\n    fn hash(value: *const(Point)) -> u64 = Hash::hash(&value.x) ^ (Hash::hash(&value.y) << 1)\n\nfn digest_of(content: []const(u8)) -> ![32]u8\n    var source = Source{ bytes = content }\n    return hash::sha256(&source)\n\nfn check(type T, one: T, two: T) -> !bool\n    var own seen = HashMap(T, u8)::init()\n    defer seen.deinit(own)\n    const own first = try seen.put(&one, 1)\n    const own second = try seen.put(&two, 2)\n    const own repeated = try seen.put(&one, 3)\n    const own removed = seen.remove(&one)\n    return first == null and second == null and repeated != null and removed != null and removed.?[1] == 3 and !seen.contains(&one) and seen.get(&two).?.* == 2 and seen.length() == 1\n\nfn text_of(content: []const(u8)) -> own memory::Error![]u8\n    const own bytes = try memory::allocate(u8, content.length)\n    memory::copy(bytes, content)\n    return bytes\n\nfn end_texts(own texts: *HashMap([]u8, u8))\n    while texts.pop() as own { key, _ }\n        memory::free(own key)\n    texts.deinit(own)\n\nfn end_constants(own constants: *HashMap([]const(u8), u8))\n    while constants.pop() as own { key, _ }\n        memory::free(own key)\n    constants.deinit(own)\n\nfn main -> !void\n    with memory::Heap\n    var own digests = HashMap([32]u8, u8)::init()\n    defer digests.deinit(own)\n    const digest = try digest_of(\"abc\")\n    const own first_digest = try digests.put(&digest, 1)\n    const same = try digest_of(\"abc\")\n    const own same_digest = try digests.put(&same, 2)\n    const other = try digest_of(\"abd\")\n    const own other_digest = try digests.put(&other, 3)\n    try text::print(&stdout, \"digests {} {} {} {} {}\\n\", { first_digest == null, same_digest == null, other_digest == null, digests.length(), digests.contains(&digest) })\n    const own removed_digest = digests.remove(&digest)\n    try text::print(&stdout, \"digests {} {} {}\\n\", { removed_digest != null, digests.contains(&digest), digests.length() })\n    var own texts = HashMap([]u8, u8)::init()\n    defer end_texts(own &texts)\n    const own ok = try text_of(\"ok\")\n    defer memory::free(own ok)\n    const first_text = try texts.put(&ok, 1)\n    const first_text_empty = first_text == null\n    const same_text = try texts.put(&ok, 2)\n    const same_text_empty = same_text == null\n    var letters: [2]u8 = { 'o', 'k' }\n    const probe: []u8 = letters[..]\n    try text::print(&stdout, \"texts {} {} {} {}\\n\", { first_text_empty, same_text_empty, texts.length(), texts.contains(&probe) })\n    var own constants = HashMap([]const(u8), u8)::init()\n    defer end_constants(own &constants)\n    const first_constant = try constants.put(\"alpha\", 1)\n    const first_constant_empty = first_constant == null\n    const other_constant = try constants.put(\"beta\", 2)\n    const other_constant_empty = other_constant == null\n    const same_constant = try constants.put(\"alpha\", 3)\n    const same_constant_empty = same_constant == null\n    try text::print(&stdout, \"constants {} {} {} {}\\n\", { first_constant_empty, other_constant_empty, same_constant_empty, constants.length() })\n    var own points = HashMap(Point, u8)::init()\n    defer points.deinit(own)\n    const one_two: Point = { x = 1, y = 2 }\n    const two_one: Point = { x = 2, y = 1 }\n    const first_point = try points.put(&one_two, 1)\n    const other_point = try points.put(&two_one, 2)\n    const same_point = try points.put(&one_two, 3)\n    try text::print(&stdout, \"points {} {} {} {}\\n\", { first_point == null, other_point == null, same_point == null, points.length() })\n    const has_i8 = try check(i8, -1, 1)\n    const has_i128 = try check(i128, -1, 1)\n    const has_u128 = try check(u128, 1, 340282366920938463463374607431768211455)\n    const has_bool = try check(bool, true, false)\n    const has_usize = try check(usize, 1, 2)\n    const has_i16 = try check(i16, -300, 300)\n    const has_i32 = try check(i32, -70000, 70000)\n    const has_i64 = try check(i64, -5000000000, 5000000000)\n    const has_isize = try check(isize, -1, 1)\n    const has_u8 = try check(u8, 1, 2)\n    const has_u16 = try check(u16, 300, 301)\n    const has_u32 = try check(u32, 70000, 70001)\n    try text::print(&stdout, \"{} {} {} {} {} {} {} {} {} {} {} {}\\n\", { has_i8, has_i128, has_u128, has_bool, has_usize, has_i16, has_i32, has_i64, has_isize, has_u8, has_u16, has_u32 })\n    const zero: u64 = 0\n    const content: []const(u8) = \"abc\"\n    try text::print(&stdout, \"{} {}\\n\", { Hash::hash(&zero), Hash::hash(&content) })\n    var spread: [1024]bool = undefined\n    for (index in 0..1024) spread[index] = false\n    var filled: usize = 0\n    var neighbours: usize = 0\n    var previous: u64 = 0\n    for index in 0..1024\n        const number = mn::convert(u64, index)\n        const value = Hash::hash(&number)\n        const slot = mn::truncate(usize, value & 1023)\n        if !spread[slot]\n            spread[slot] = true\n            filled += 1\n        if (index > 0 and (value & 1023) == ((previous + 1) & 1023)) neighbours += 1\n        previous = value\n    try text::print(&stdout, \"spread {} {}\\n\", { filled > 550 and filled < 750, neighbours < 10 })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
