    try std.testing.expectEqualStrings(expected, result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that goes over the keys and values of a map" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container::HashMap\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nfn main -> !void\n    with memory::Heap\n    var own empty = HashMap(u64, u64)::init()\n    defer empty.deinit(own)\n    var empty_count: usize = 0\n    for _ in empty.keys()\n        empty_count += 1\n    for _ in empty.values()\n        empty_count += 1\n    for { _, _ } in empty.iterator()\n        empty_count += 1\n    try text::print(&stdout, \"empty {} {} {}\\n\", { empty_count, empty.length(), empty.length() })\n    var own seen = HashMap(u64, u64)::init()\n    defer seen.deinit(own)\n    for index in 0..1000\n        const key = mn::convert(u64, index) * 3\n        _ = try seen.put(&key, mn::convert(u64, index) * 5)\n    var marks: [1000]u8 = undefined\n    var wrong: usize = 0\n    for (index in 0..1000) marks[index] = 0\n    for key in seen.keys()\n        marks[mn::convert(usize, key / 3)] += 1\n    for index in 0..1000\n        if (marks[index] != 1) wrong += 1\n    for (index in 0..1000) marks[index] = 0\n    for value in seen.values()\n        marks[mn::convert(usize, value / 5)] += 1\n    for index in 0..1000\n        if (marks[index] != 1) wrong += 1\n    for (index in 0..1000) marks[index] = 0\n    for { key, value } in seen.iterator()\n        marks[mn::convert(usize, key / 3)] += 1\n        if (value / 5 != key / 3) wrong += 1\n    for index in 0..1000\n        if (marks[index] != 1) wrong += 1\n    for index in 0..seen.length()\n        if (seen.values()[index] / 5 != seen.keys()[index] / 3) wrong += 1\n    try text::print(&stdout, \"full {} {} wrong {}\\n\", { seen.length(), seen.length(), wrong })\n    for index in 0..1000\n        if index % 2 == 0\n            const lookup_471: u64 = mn::convert(u64, index) * 3\n            const own owned_46 = seen.remove(&lookup_471)\n            if (owned_46 == null) wrong += 1\n    var left: usize = 0\n    for { key, value } in seen.iterator()\n        if (key % 2 == 1 and value / 5 == key / 3) left += 1\n    for index in 0..seen.length()\n        if (seen.values()[index] / 5 != seen.keys()[index] / 3) wrong += 1\n    try text::print(&stdout, \"removed {} {} {} wrong {}\\n\", { seen.length(), left, seen.length(), wrong })\n    for *value in seen.values()\n        value.* += 1\n    for { key, value } in seen.iterator()\n        if (seen.get(&key).?.* != value or value != key / 3 * 5 + 1) wrong += 1\n    for { key, value } in seen.iterator()\n        if (value % 5 != 1 or key % 3 != 0) wrong += 1\n    const lookup_612: u64 = 3\n    try text::print(&stdout, \"updated {} wrong {}\\n\", { seen.get(&lookup_612).?.*, wrong })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
