    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings(
        "empty 0 0 0\nfull 1000 1000 wrong 0\nremoved 500 500 500 wrong 0\nupdated 6 wrong 0\n",
        result.stdout,
    );
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that allocates a map from a fixed allocator" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container::HashMap\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nstruct Fixed\n    bytes: [4096]u8\n    used: usize\n    limit: usize\n\ninstance Allocator(Fixed)\n\n    fn allocate(fixed: *Fixed, type T, count: usize) -> own memory::Error![]T\n        const size = mn::size(T) * count\n        const start = (fixed.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        if (start + size > fixed.limit) return memory::Error::OutOfMemory\n        fixed.used = start + size\n        return mn::cast(*many(T), fixed.bytes[start..fixed.used].pointer)[0..count]\n    fn(type T) resize(_: *Fixed, _: []T, _: usize) -> bool = false\n    fn(type T) free(_: *Fixed, own _: []const(T)) = noop\n\nfn main -> !void\n    with memory::Heap\n    var fixed: Fixed = undefined\n    fixed.used = 0\n    fixed.limit = 1024\n    var own from_default = HashMap(u64, u64)::init()\n    defer from_default.deinit(own)\n    for index in 0..100\n        const key = mn::convert(u64, index)\n        _ = try from_default.put(&key, 1)\n    try text::print(&stdout, \"default {} {}\\n\", { from_default.length(), fixed.used })\n    var own seen = HashMap(u64, u64)::init()\n    defer seen.deinit(own) with &fixed\n    var filled: u64 = 0\n    var failed = false\n    while !failed\n        const own owned_37 = seen.put(&filled, filled + 1) with &fixed\n        match owned_37\n            case (?u64) filled += 1\n            case (memory::Error::OutOfMemory) failed = true\n    var wrong: usize = 0\n    for number in 0..mn::convert(usize, filled)\n        const key = mn::convert(u64, number)\n        if (!seen.contains(&key) or seen.get(&key).?.* != key + 1) wrong += 1\n    try text::print(&stdout, \"filled {} {} {} {}\\n\", { filled > 3, mn::convert(u64, seen.length()) == filled, wrong, seen.contains(&filled) })\n    const lookup_471: u64 = 3\n    const own removed = seen.remove(&lookup_471)\n    const lookup_492: u64 = 100000\n    const own added = try seen.put(&lookup_492, 1) with &fixed\n    try text::print(&stdout, \"after {} {} {} {}\\n\", { removed != null, added == null, mn::convert(u64, seen.length()) == filled, seen.contains(&lookup_492) })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings(
        "default 100 0\nfilled true true 0 false\nafter true true true true\n",
        result.stdout,
    );
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that gives the absolute form of a path" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::convert::To\nimport mn::convert::View\nimport mn::filesystem\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process\nimport mn::process::stdout\nimport mn::stream::Writer\nimport mn::text\n\nfn report(content: []const(u8)) -> !void\n    var own path = try content.to(filesystem::Path)\n    defer path.deinit(own)\n    const own owned_11 = path.absolute()\n    match owned_11\n        case filesystem::Path as own full\n            defer full.deinit(own)\n            const own full_text = try full.to([]u8)\n            defer memory::free(own full_text)\n            const own original = try path.to([]u8)\n            defer memory::free(own original)\n            try text::print(&stdout, \"{s} {s}\\n\", { full_text, original })\n        case (filesystem::Error::NotFound) try text::print(&stdout, \"not_found\\n\", {})\n        case (filesystem::Error::NotDirectory) try text::print(&stdout, \"not_directory\\n\", {})\n        case (filesystem::Error::NameTooLong) try text::print(&stdout, \"name_too_long\\n\", {})\n        else try text::print(&stdout, \"unexpected\\n\", {})\n\nfn main -> !void\n    with memory::Heap\n    for argument in process::arguments()\n        try report(argument)\n    var own long_path = try \"/\".to(filesystem::Path)\n    defer long_path.deinit(own)\n    for _ in 0..1000\n        const own longer = try long_path.join(\"twelve_bytes\".view(filesystem::Path))\n        long_path.deinit(own)\n        long_path = own longer\n    const own owned_32 = long_path.absolute()\n    match owned_32\n        case filesystem::Path as own full\n            full.deinit(own)\n            try text::print(&stdout, \"resolved\\n\", {})\n        case (filesystem::Error::NameTooLong) try text::print(&stdout, \"name_too_long\\n\", {})\n        else try text::print(&stdout, \"unexpected\\n\", {})\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);
    try build_directory.createDirPath(std.testing.io, "folder/inner");
    try build_directory.writeFile(std.testing.io, .{ .sub_path = "folder/file.txt", .data = "text" });
    try build_directory.symLink(std.testing.io, "folder/inner", "link", .{});

    const root = try build_directory.realPathFileAlloc(std.testing.io, ".", allocator);
    const absolute_input = try std.fs.path.join(allocator, &.{ root, "folder" });
    const result = try std.process.run(allocator, std.testing.io, .{
        .argv = &.{ "./main", ".", "folder", "folder/../folder/file.txt", "folder/./inner", "link", absolute_input, "/", "missing", "folder/file.txt/inner" },
        .cwd = .{ .dir = build_directory },
    });
    const expected = try std.fmt.allocPrint(
        allocator,
        "{0s} .\n{0s}/folder folder\n{0s}/folder/file.txt folder/../folder/file.txt\n{0s}/folder/inner folder/./inner\n{0s}/folder/inner link\n{0s}/folder {0s}/folder\n/ /\nnot_found\nnot_directory\nname_too_long\n",
        .{root},
    );
    try std.testing.expectEqualStrings(expected, result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

