    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::compare::Equal\nimport mn::container::HashMap\nimport mn::hash\nimport mn::hash::Hash\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nstruct Data\n    name: []const(u8)\n    number: u64\n\ninstance Equal(Data)\n\n    fn equal(one: *const(Data), two: *const(Data)) -> bool = memory::equal(one.name, two.name) and one.number == two.number\n\ninstance Hash(Data)\n\n    fn hash(data: *const(Data)) -> u64 = hash::splitmix64(hash::fnv1a64(data.name) ^ data.number)\n\nfn main -> !void\n    with memory::Heap\n    try text::print(&stdout, \"{} {} {} {}\\n\", { hash::fnv1a64(\"\"), hash::fnv1a64(\"a\"), hash::fnv1a64(\"foobar\"), hash::splitmix64(0) })\n    var own map = HashMap(Data, u8)::init()\n    defer map.deinit(own)\n    const one: Data = { name = \"alpha\", number = 1 }\n    const two: Data = { name = \"alpha\", number = 2 }\n    const first = try map.put(&one, 1)\n    const second = try map.put(&two, 2)\n    const repeated = try map.put(&one, 3)\n    const probe: Data = { name = \"alpha\", number = 2 }\n    try text::print(&stdout, \"{} {} {} {} {}\\n\", { first == null, second == null, repeated != null, map.length(), map.get(&probe).?.* })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings(
        "14695981039346656037 12638187200555641996 9625390261332436968 16294208416658607535\ntrue true true 2 2\n",
        result.stdout,
    );
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that hashes slices, numbers, arrays and paths with fnv1a64 and splitmix64" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::convert::To\nimport mn::filesystem\nimport mn::hash\nimport mn::hash::Hash\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nfn main -> !void\n    with memory::Heap\n    const content: []const(u8) = \"foobar\"\n    var letters: [6]u8 = { 'f', 'o', 'o', 'b', 'a', 'r' }\n    const mutable: []u8 = letters[..]\n    const own path = try \"foobar\".to(filesystem::Path)\n    defer path.deinit(own)\n    try text::print(&stdout, \"{} {} {}\\n\", { Hash::hash(&content), Hash::hash(&mutable), Hash::hash(&path) })\n    const number: u64 = 7\n    const negative: i64 = -5\n    const truth = true\n    const wide: u128 = 18446744073709551619\n    try text::print(&stdout, \"{} {} {} {}\\n\", { Hash::hash(&number), Hash::hash(&negative), Hash::hash(&truth), Hash::hash(&wide) })\n    const pair: [2]u8 = { 1, 2 }\n    try text::print(&stdout, \"{}\\n\", { Hash::hash(&pair) })\n    const is_content_named = Hash::hash(&content) == hash::splitmix64(hash::fnv1a64(content))\n    const is_number_named = Hash::hash(&number) == hash::splitmix64(number)\n    const is_pair_named = Hash::hash(&pair) == hash::splitmix64(hash::splitmix64(0 ^ hash::splitmix64(1)) ^ hash::splitmix64(2))\n    const is_path_named = Hash::hash(&path) == hash::splitmix64(hash::fnv1a64(\"foobar\"))\n    try text::print(&stdout, \"{} {} {} {}\\n\", { is_content_named, is_number_named, is_pair_named, is_path_named })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    var mixed = [_]u64{ 0x85944171f73967e8, 7, @bitCast(@as(i64, -5)), 1, 3, 2, 0, 0 };
    for (&mixed, 0..) |*value, index| {
        if (index == 6) value.* = 0 ^ mixed[3];
        if (index == 7) value.* = mixed[6] ^ mixed[5];
        value.* +%= 0x9e3779b97f4a7c15;
        value.* = (value.* ^ (value.* >> 30)) *% 0xbf58476d1ce4e5b9;
        value.* = (value.* ^ (value.* >> 27)) *% 0x94d049bb133111eb;
        value.* ^= value.* >> 31;
    }
    const expected = try std.fmt.allocPrint(allocator, "{d} {d} {d}\n{d} {d} {d} {d}\n{d}\ntrue true true true\n", .{ mixed[0], mixed[0], mixed[0], mixed[1], mixed[2], mixed[3], mixed[4] ^ mixed[3], mixed[7] });
    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings(expected, result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

