fer memory::free(own one)\n    memory::free(own one)\n    const size = try count(1, fails)\n    return size\n\nfn main -> !void\n    var counting: Counting = undefined\n    start(&counting, 100)\n    with &counting\n    const one = load(false) catch 0\n    const two = load(true) catch 9\n    try text::print(&stdout, \"{} {} live {} twice {}\\n\", { one, two, counting.live, counting.twice })\n" });
