    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [4096]u8\n    used: usize\n    allowed: usize\n    live: usize\n    twice: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        if (counting.allowed == 0) return memory::Error::OutOfMemory\n        counting.allowed -= 1\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(_: *Counting, _: []T, _: usize) -> bool = false\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        const size = mn::size(T) * items.length\n        if counting.live < size\n            counting.twice += 1\n        else\n            counting.live -= size\n\nfn start(counting: *Counting, allowed: usize)\n    counting.used = 0\n    counting.allowed = allowed\n    counting.live = 0\n    counting.twice = 0\n\nenum Choice\n    One\n    Two\n\nfn count(size: usize, fails: bool) -> memory::Error!usize\n    if (fails) return memory::Error::OutOfMemory\n    return size\n\nfn take(own bytes: []u8, fails: bool) -> memory::Error!usize\n    if (fails) return memory::Error::OutOfMemory\n    const length = bytes.length + 1\n    memory::free(own bytes)\n    return length\n\nfn find(own bytes: []u8, present: bool) -> ?usize\n    const length = bytes.length + 1\n    memory::free(own bytes)\n    if (present) return length\n    return null\n\nfn absent(present: bool) -> ?usize\n    if (present) return 1\n    return null\n\nfn load(choice: Choice, fails: bool) -> memory::Error!usize\n    const own one = try memory::allocate(u8, 1)\n    errdefer memory::free(own one)\n    const size = try match choice\n        case One\n            memory::free(own one)\n            count(1, fails)\n        case Two\n            take(own one, fails)\n    return size\n\nfn main -> !void\n    var counting: Counting = undefined\n    start(&counting, 100)\n    with &counting\n    const one = load(Choice::One, false) catch 0\n    const two = load(Choice::Two, false) catch 0\n    const three = load(Choice::One, true) catch 9\n    const four = load(Choice::Two, true) catch 9\n    try text::print(&stdout, \"{} {} {} {} live {} twice {}\\n\", { one, two, three, four, counting.live, counting.twice })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);
    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("1 2 9 9 live 0 twice 0\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

