::allocate(u8, 1)\n    errdefer memory::free(own one)\n    const size = try match choice\n        case One\n            if flag\n                memory::free(own one)\n                count(1, fails)\n            else\n                take(own one, fails)\n        case Two\n            take(own one, fails)\n    return size\n\nfn main -> !void\n    var counting: Counting = undefined\n    start(&counting, 100)\n    with &counting\n    const one = load(Choice::One, true, false) catch 0\n    const two = load(Choice::One, false, false) catch 0\n    const three = load(Choice::Two, true, false) catch 0\n    const four = load(Choice::One, true, true) catch 9\n    const five = load(Choice::One, false, true) catch 9\n    const six = load(Choice::Two, false, true) catch 9\n    try text::print(&stdout, \"{} {} {} {} {} {} live {} twice {}\\n\", { one, two, three, four, five, six, counting.live, counting.twice })\n" });
