(u8, 1)\n    errdefer memory::free(own one)\n    const size = (if (choice == Choice::One) find(own one, present) else find(own one, present)) orelse return memory::Error::OutOfMemory\n    return size\n\nfn main -> !void\n    var counting: Counting = undefined\n    start(&counting, 100)\n    with &counting\n    const one = load(Choice::One, true) catch 0\n    const two = load(Choice::Two, true) catch 0\n    const three = load(Choice::One, false) catch 9\n    const four = load(Choice::Two, false) catch 9\n    try text::print(&stdout, \"{} {} {} {} live {} twice {}\\n\", { one, two, three, four, counting.live, counting.twice })\n" });
