test "Generator.generate: builds an executable that copies empty slices and large overlapping runs" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container\nimport mn::convert::View\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::stream::Writer\nimport mn::text\n\nfn fill(bytes: []u8)\n    for (index in 0..bytes.length) bytes[index] = mn::truncate(u8, index % 251)\n\nfn main -> !void\n    with memory::Heap\n    var own list = mn::container::ArrayList(u8)::init()\n    defer list.deinit(own)\n    memory::copy(list.view([]u8), list.view([]const(u8)))\n    const empty: []u8 = {}\n    const nothing: []const(u8) = {}\n    memory::copy(empty, nothing)\n    for (index in 0..100) try list.append(mn::truncate(u8, index))\n    var list_wrong: usize = 0\n    for index in 0..100\n        if (list.view([]const(u8))[index] != mn::truncate(u8, index)) list_wrong += 1\n    try text::print(&stdout, \"list {} {}\\n\", { list.length(), list_wrong })\n    const own bytes = try memory::allocate(u8, 100000)\n    defer memory::free(own bytes)\n    const shifts: [3]usize = { 1, 7, 1000 }\n    for shift in shifts\n        fill(bytes)\n        memory::copy(bytes[0..100000 - shift], bytes[shift..100000])\n        var forward_wrong: usize = 0\n        for index in 0..100000 - shift\n            if (bytes[index] != mn::truncate(u8, (index + shift) % 251)) forward_wrong += 1\n        fill(bytes)\n        memory::copy(bytes[shift..100000], bytes[0..100000 - shift])\n        var backward_wrong: usize = 0\n        for index in shift..100000\n            if (bytes[index] != mn::truncate(u8, (index - shift) % 251)) backward_wrong += 1\n        try text::print(&stdout, \"{} {} {}\\n\", { shift, forward_wrong, backward_wrong })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);
    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("list 100 0\n1 0 0\n7 0 0\n1000 0 0\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that calls functions of the expected type with a leading separator" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container::ArrayList\nimport mn::container::HashMap\nimport mn::convert::View\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::stream::Writer\nimport mn::text\n\nerror Failure\n    Bad\n\nenum Mode\n    Read\n    Write\n\n    fn make() -> Self = ::Write\n\n\nstruct Counter\n    value: u8\n\n    fn init() -> Self = Self{ value = 1 }\n\n\n    fn from(value: u8) -> Self = Self{ value = value }\n\n\n    fn parse(value: u8) -> Failure!Self\n        if (value == 0) return Failure::Bad\n        return ::from(value)\n\n\n    fn find(value: u8) -> ?Self\n        if (value == 0) return null\n        return ::from(value)\n\n\n    fn inside() -> Self\n        const made: Self = ::from(9)\n        return made\n\n\nstruct Named\n    own bytes: []u8\n\n    fn parse(content: []const(u8)) -> own memory::Error!Self\n        const own bytes = try memory::allocate(u8, content.length)\n        memory::copy(bytes, content)\n        return Self{ bytes = own bytes }\n\n\nstruct Holder\n    counter: Counter\n    other: Counter = ::from(8)\n\nstruct Inventory\n    own cards: ArrayList(u8)\n    own seen: HashMap(u64, u8)\n\nstruct Fixed\n    bytes: [4096]u8\n    used: usize\n\ninstance Allocator(Fixed)\n\n    fn allocate(fixed: *Fixed, type T, count: usize) -> own memory::Error![]T\n        const size = mn::size(T) * count\n        const start = (fixed.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        if (start + size > 4096) return memory::Error::OutOfMemory\n        fixed.used = start + size\n        return mn::cast(*many(T), fixed.bytes[start..fixed.used].pointer)[0..count]\n    fn(type T) resize(_: *Fixed, _: []T, _: usize) -> bool = false\n    fn(type T) free(_: *Fixed, own _: []const(T)) = noop\n\nfn show(counter: Counter) -> u8 = counter.value\n\nfn give() -> Counter\n    return ::from(2)\n\nfn give_line() -> Counter = ::init()\n\nfn give_parsed(value: u8) -> Failure!Counter\n    return ::parse(value)\n\nfn give_tried(value: u8) -> Failure!Counter\n    return try ::parse(value)\n\nfn main -> !void\n    with memory::Heap\n    try text::print(&stdout, \"argument {}\\n\", { show(::from(3)) })\n    const annotated: Counter = ::from(4)\n    try text::print(&stdout, \"annotated {}\\n\", { annotated.value })\n    var assigned = Counter::init()\n    assigned = ::from(5)\n    try text::print(&stdout, \"assignment {}\\n\", { assigned.value })\n    const parsed_result = try give_parsed(6)\n    const tried_result = try give_tried(7)\n    try text::print(&stdout, \"return {} {} {} {}\\n\", { give().value, give_line().value, parsed_result.value, tried_result.value })\n    const holder = Holder{ counter = ::init() }\n    try text::print(&stdout, \"field {} {}\\n\", { holder.counter.value, holder.other.value })\n    const items: [2]Counter = { ::init(), ::from(2) }\n    const pair: [Counter, bool] = { ::from(3), true }\n    try text::print(&stdout, \"elements {} {} {}\\n\", { items[0].value, items[1].value, pair[0].value })\n    const through_try: Counter = try ::parse(4)\n    const through_catch: Counter = ::parse(0) catch ::from(5)\n    const through_orelse: Counter = ::find(0) orelse ::from(6)\n    const optional: ?Counter = ::find(7)\n    try text::print(&stdout, \"through {} {} {} {}\\n\", { through_try.value, through_catch.value, through_orelse.value, optional.?.value })\n    const init: u8 = 40\n    const beside: Counter = ::init()\n    try text::print(&stdout, \"local {}\\n\", { init + beside.value })\n    const shadow: Counter = ::inside()\n    try text::print(&stdout, \"self {}\\n\", { shadow.value })\n    const mode: Mode = ::make()\n    const other: Mode = ::Read\n    try text::print(&stdout, \"mode {} {} {}\\n\", { mode == ::Write, mode == ::make(), other == ::make() })\n    var own inventory = Inventory{ cards = ::init(), seen = ::init() }\n    defer inventory.cards.deinit(own)\n    defer inventory.seen.deinit(own)\n    try inventory.cards.append(1)\n    const two: u64 = 2\n    _ = try inventory.seen.put(&two, 1)\n    try text::print(&stdout, \"inventory {} {}\\n\", { inventory.cards.length(), inventory.seen.length() })\n    var own list: ArrayList(u8) = ::init()\n    defer list.deinit(own)\n    try list.append(7)\n    try text::print(&stdout, \"list {}\\n\", { list.view([]const(u8))[0] })\n    const own named: Named = try ::parse(\"cards/one\")\n    defer memory::free(own named.bytes)\n    try text::print(&stdout, \"path {s}\\n\", { named.bytes })\n    var fixed: Fixed = undefined\n    fixed.used = 0\n    const own fixed_named: Named = try ::parse(\"cards\") with &fixed\n    defer memory::free(own fixed_named.bytes) with &fixed\n    try text::print(&stdout, \"with {} {}\\n\", { fixed.used > 0, fixed_named.bytes.length })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);
    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings(
        "argument 3\nannotated 4\nassignment 5\nreturn 2 1 6 7\nfield 1 8\nelements 1 2 3\nthrough 4 5 6 7\nlocal 41\nself 9\nmode true true false\ninventory 1 1\nlist 7\npath cards/one\nwith true 5\n",
        result.stdout,
    );
    try std.testing.expectEqual(0, result.term.exited);
}

