test "Generator.generate: builds an executable with loops that fit their arrays and a count of zero" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::container::HashMap\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::stream::Writer\nimport mn::text\n\nfn exact(value: [3]u8) -> u8\n    var sum: u8 = 0\n    for index in 0..3\n        sum += value[index]\n    return sum\nfn shorter(value: [3]u8) -> u8\n    var sum: u8 = 0\n    for index in 0..2\n        sum += value[index]\n    return sum\nfn later(value: [3]u8) -> u8\n    var sum: u8 = 0\n    for index in 1..3\n        sum += value[index]\n    return sum\nfn plus_one(value: [3]u8) -> u8\n    var sum: u8 = 0\n    for index in 0..2\n        sum += value[index + 1]\n    return sum\nfn through_constant(value: [3]u8) -> u8\n    var sum: u8 = 0\n    for index in 0..5\n        const position = index % 3\n        sum += value[position]\n    return sum\nfn shadowed(value: [3]u8) -> u8\n    var sum: u8 = 0\n    for index in 0..5\n        if (index == 9) sum = 0\n        for index in 0..3\n            sum += value[index]\n    return sum\nfn through_slice(value: []const(u8)) -> u8\n    var sum: u8 = 0\n    for index in 0..3\n        sum += value[index]\n    return sum\nfn at_run_time(value: [3]u8, count: usize) -> u8\n    var sum: u8 = 0\n    for index in 0..count\n        sum += value[index]\n    return sum\nfn pointer(value: *const([3]u8)) -> u8\n    var sum: u8 = 0\n    for index in 0..3\n        sum += value[index]\n    return sum\nfn zero_count(count: usize) -> usize\n    var sum: usize = 9\n    for index in 0..count\n        sum += index\n    return sum\nfn without_end() -> usize\n    var sum: usize = 0\n    for index in 5..\n        sum += index\n        break\n    return sum\n\ntypeclass Total(type T)\n\n    fn total(value: T) -> u8\n\ninstance(comptime N: usize) Total([N]u8)\n\n    fn total(value: [N]u8) -> u8\n        var sum: u8 = 0\n        for element in value\n            sum += element\n        return sum\n\nfn main -> !void\n    with memory::Heap\n    const three: [3]u8 = { 1, 2, 3 }\n    const empty: [0]u8 = {}\n    try text::print(&stdout, \"{} {} {} {}\\n\", { exact(three), shorter(three), later(three), plus_one(three) })\n    try text::print(&stdout, \"{} {} {} {}\\n\", { through_constant(three), shadowed(three), through_slice(three[..]), at_run_time(three, 2) })\n    try text::print(&stdout, \"{} {} {} {}\\n\", { pointer(&three), zero_count(0), without_end(), Total::total(empty) })\n    var own seen = HashMap([0]u8, u8)::init()\n    defer seen.deinit(own)\n    const own first = try seen.put(&empty, 1)\n    const own second = try seen.put(&empty, 2)\n    try text::print(&stdout, \"{} {} {}\\n\", { first == null, second == null, seen.length() })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);
    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("6 3 5 5\n9 30 6 3\n6 9 5 0\ntrue false 1\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

