    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container::HashMap\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [262144]u8\n    used: usize\n    fail_at: usize\n    allocations: usize\n    frees: usize\n    live: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        counting.allocations += 1\n        if (counting.allocations == counting.fail_at) return memory::Error::OutOfMemory\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(_: *Counting, _: []T, _: usize) -> bool = false\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        counting.frees += 1\n        counting.live -= mn::size(T) * items.length\n\nfn start(counting: *Counting)\n    counting.used = 0\n    counting.fail_at = 0\n    counting.allocations = 0\n    counting.frees = 0\n    counting.live = 0\n\nfn check_size(counting: *Counting, size: usize) -> !usize\n    var wrong: usize = 0\n    var own map = HashMap(u64, u64)::init()\n    errdefer map.deinit(own) with counting\n    for index in 0..size\n        const key = mn::convert(u64, index)\n        _ = try map.put(&key, 1) with counting\n    const allocations = counting.allocations\n    const live = counting.live\n    map.clear()\n    if (map.length() != 0 or map.length() != 0 or map.length() != 0 or counting.frees != 0 and counting.live != live) wrong += 1\n    for index in 0..size\n        const key = mn::convert(u64, index)\n        const own owned_53 = map.remove(&key)\n        if (map.contains(&key) or map.get(&key) != null or owned_53 != null) wrong += 1\n    for index in 0..size\n        const key = mn::convert(u64, index) + 1000\n        const own previous = try map.put(&key, 2) with counting\n        if (previous != null) wrong += 1\n    if (counting.allocations != allocations or counting.live != live or map.length() != size) wrong += 1\n    for index in 0..size\n        const lookup_641: u64 = mn::convert(u64, index) + 1000\n        const lookup_642: u64 = mn::convert(u64, index)\n        if (map.get(&lookup_641) == null or map.contains(&lookup_642)) wrong += 1\n    map.deinit(own) with counting\n    map = HashMap(u64, u64)::init()\n    const lookup_673: u64 = 1000\n    if (map.length() != 0 or counting.live != 0 or map.contains(&lookup_673) or map.length() != 0) wrong += 1\n    map.deinit(own) with counting\n    map = HashMap(u64, u64)::init()\n    const lookup_714: u64 = 7\n    const own fresh = try map.put(&lookup_714, 8) with counting\n    if (fresh != null or map.get(&lookup_714).?.* != 8 or map.length() != 1) wrong += 1\n    map.deinit(own) with counting\n    if (counting.live != 0) wrong += 1\n    return wrong\n\nfn main -> !void\n    var counting: Counting = undefined\n    var wrong: usize = 0\n    for size in 1..80\n        start(&counting)\n        wrong += try check_size(&counting, size)\n    try text::print(&stdout, \"wrong {}\\n\", { wrong })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
