length(), keys.contains(nothing) })\n\nfn check_values(counting: *Counting) -> !void\n    var own values = HashMap(u32, Marker)::init()\n    defer values.deinit(own) with counting\n    for index in 0..100\n        const key = mn::convert(u32, index)\n        const own fresh = try values.put(&key, Marker{}) with counting\n        if (fresh != null) try text::print(&stdout, \"repeated\\n\", {})\n    const lookup_591: u32 = 3\n    const own replaced = try values.put(&lookup_591, Marker{}) with counting\n    const lookup_592: u32 = 100\n    try text::print(&stdout, \"values {} {} {} {} {} {}\\n\", { replaced != null, values.length(), values.get(&lookup_591) != null, values.get(&lookup_592) == null, values.length(), values.length() })\n    var total: u32 = 0\n    for { key, _ } in values.iterator()\n        total += key\n    for index in 0..50\n        const lookup_643: u32 = mn::convert(u32, index)\n        const own owned_63 = values.remove(&lookup_643)\n        if (owned_63 == null) try text::print(&stdout, \"missing\\n\", {})\n    const lookup_664: u32 = 10\n    const lookup_665: u32 = 60\n    try text::print(&stdout, \"{} {} {} {}\\n\", { total, values.length(), values.contains(&lookup_664), values.contains(&lookup_665) })\n\nfn check_both(counting: *Counting, nothing: *const([0]u8)) -> !void\n    var own both = HashMap([0]u8, Marker)::init()\n    defer both.deinit(own) with counting\n    const own fresh_both = try both.put(nothing, Marker{}) with counting\n    const own again_both = try both.put(nothing, Marker{}) with counting\n    const both_length = both.length()\n    const own owned_70 = both.remove(nothing)\n    try text::print(&stdout, \"both {} {} {} {}\\n\", { fresh_both == null, again_both != null, both_length, owned_70 != null })\n\nfn main -> !void\n    var counting: Counting = undefined\n    start(&counting)\n    const nothing: [0]u8 = {}\n    try check_keys(&counting, &nothing)\n    try check_values(&counting)\n    try check_both(&counting, &nothing)\n    try text::print(&stdout, \"live {}\\n\", { counting.live })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("keys true 1 1 2 1 2\n2\n2 0 false\nvalues true 100 true true 100 100\n4950 50 false true\nboth true true 1 true\nlive 0\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that keeps owning keys in a map and finds them through pointers to them" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::compare::Equal\nimport mn::container::HashMap\nimport mn::hash::Hash\nimport mn::memory\nimport mn::memory::Clone\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nstruct Name\n    own bytes: []u8\n\ninstance Equal(Name)\n\n    fn equal(one: *const(Name), two: *const(Name)) -> bool = memory::equal(one.bytes, two.bytes)\n\ninstance Hash(Name)\n\n    fn hash(value: *const(Name)) -> u64 = Hash::hash(&value.bytes)\n\ninstance Clone(Name)\n\n    fn clone(name: *const(Name)) -> own memory::Error!Name = { bytes = try name.bytes.clone() }\n\nfn make(letter: u8) -> own memory::Error!Name\n    const own bytes = try memory::allocate(u8, 1)\n    bytes[0] = letter\n    return { bytes = own bytes }\n\nfn end_map(own map: *HashMap(Name, u32))\n    while map.pop() as own { key, _ }\n        memory::free(own key.bytes)\n    map.deinit(own)\n\nfn main -> !void\n    with memory::Heap\n    var own map = HashMap(Name, u32)::init()\n    defer end_map(own &map)\n    const own first_key = try make('a')\n    defer memory::free(own first_key.bytes)\n    const first = try map.put(&first_key, 1)\n    const first_empty = first == null\n    const own second_key = try make('b')\n    defer memory::free(own second_key.bytes)\n    const second = try map.put(&second_key, 2)\n    const second_empty = second == null\n    const own lookup = try make('b')\n    defer memory::free(own lookup.bytes)\n    const found = map.get(&lookup)\n    lookup.bytes[0] = 'c'\n    try text::print(&stdout, \"{} {} {} {}\\n\", { first_empty and second_empty, found.?.*, map.contains(&lookup), map.length() })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("true 2 false 2\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that hands an owned key and value to a map through the slot get_or_put reserves without cloning, finds a present key with pointers to what the map holds without allocating, replaces its value in place and stores a clone of a key it only views" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::compare::Equal\nimport mn::container::HashMap\nimport mn::hash::Hash\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Clone\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [65536]u8\n    used: usize\n    allocations: usize\n    frees: usize\n    live: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        if (count > 0) counting.allocations += 1\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(_: *Counting, _: []T, _: usize) -> bool = false\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        if (items.length > 0) counting.frees += 1\n        counting.live -= mn::size(T) * items.length\n\nstruct Name\n    own bytes: []u8\n\ninstance Equal(Name)\n\n    fn equal(one: *const(Name), two: *const(Name)) -> bool = memory::equal(one.bytes, two.bytes)\n\ninstance Hash(Name)\n\n    fn hash(value: *const(Name)) -> u64 = Hash::hash(&value.bytes)\n\ninstance Clone(Name)\n\n    fn clone(name: *const(Name)) -> own memory::Error!Name = { bytes = try name.bytes.clone() }\n\nfn make(letter: u8) -> own memory::Error!Name\n    const own bytes = try memory::allocate(u8, 1)\n    bytes[0] = letter\n    return { bytes = own bytes }\n\nfn end_map(own map: *HashMap(Name, Name))\n    while map.pop() as own { key, value }\n        memory::free(own key.bytes)\n        memory::free(own value.bytes)\n    map.deinit(own)\n\nfn check(counting: *const(Counting)) -> !void\n    var own map = HashMap(Name, Name)::init()\n    defer end_map(own &map)\n    const own other = try make('c')\n    defer memory::free(own other.bytes)\n    const own previous_other = try map.put(&other, try make('z'))\n    if previous_other as own old\n        memory::free(own old.bytes)\n    const own key = try make('a')\n    errdefer memory::free(own key.bytes)\n    const own value = try make('x')\n    errdefer memory::free(own value.bytes)\n    const key_pointer = key.bytes.pointer\n    const value_pointer = value.bytes.pointer\n    const before_new = counting.allocations\n    const fresh = try map.get_or_put(&key)\n    const fresh_found = fresh.found\n    fresh.key.* = own key\n    fresh.value.* = own value\n    const new_allocations = counting.allocations - before_new\n    try text::print(&stdout, \"new {} {} {}\\n\", { fresh_found, new_allocations, map.length() })\n    const own lookup = try make('a')\n    defer memory::free(own lookup.bytes)\n    const filled = map.get(&lookup).?\n    try text::print(&stdout, \"filled {} {}\\n\", { filled.bytes.pointer == value_pointer, map.keys()[1].bytes.pointer == key_pointer })\n    const before_present = counting.allocations\n    const present = try map.get_or_put(&lookup)\n    const present_allocations = counting.allocations - before_present\n    const is_stored = present.key.bytes.pointer == key_pointer and present.value.bytes.pointer == value_pointer\n    try text::print(&stdout, \"present {} {} {} {}\\n\", { present.found, present_allocations, is_stored, map.length() })\n    const own replacement = try make('y')\n    const replacement_pointer = replacement.bytes.pointer\n    const own replaced = memory::replace(present.value, own replacement)\n    const is_replaced = replaced.bytes.pointer == value_pointer\n    memory::free(own replaced.bytes)\n    const updated = map.get(&lookup).?\n    try text::print(&stdout, \"updated {} {} {s} {}\\n\", { is_replaced, updated.bytes.pointer == replacement_pointer, updated.bytes, map.length() })\n    const own extra = try make('b')\n    defer memory::free(own extra.bytes)\n    const added = try map.get_or_put(&extra)\n    const own stored = try extra.clone()\n    added.key.* = own stored\n    const own written = try make('w')\n    added.value.* = own written\n    const cloned = map.get(&extra).?\n    try text::print(&stdout, \"cloned {} {} {s} {}\\n\", { added.found, map.keys()[2].bytes.pointer != extra.bytes.pointer, cloned.bytes, map.length() })\n\nfn main -> !void\n    var counting: Counting = undefined\n    counting.used = 0\n    counting.allocations = 0\n    counting.frees = 0\n    counting.live = 0\n    with &counting\n    try check(&counting)\n    try text::print(&stdout, \"live {} {}\\n\", { counting.live, counting.frees == counting.allocations })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("new false 0 2\nfilled true true\npresent true 0 true 2\nupdated true true y 2\ncloned false true w 3\nlive 0 true\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that counts keys through get_or_put across the growth of a map, finds each present key of a map of each size without allocating or changing its length, and leaves the map unchanged when any allocation of get_or_put fails" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
