    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container::HashMap\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [65536]u8\n    used: usize\n    fail_at: usize\n    allocations: usize\n    live: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        counting.allocations += 1\n        if (counting.allocations == counting.fail_at) return memory::Error::OutOfMemory\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(_: *Counting, _: []T, _: usize) -> bool = false\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        counting.live -= mn::size(T) * items.length\n\nfn start(counting: *Counting)\n    counting.used = 0\n    counting.fail_at = 0\n    counting.allocations = 0\n    counting.live = 0\n\nfn check_counts(counts: *const(HashMap(u32, u32)), size: usize, expected: u32) -> usize\n    var wrong: usize = 0\n    if (counts.length() != size) wrong += 1\n    for index in 0..size\n        const word = mn::truncate(u32, index) * 7\n        const count = counts.get(&word)\n        if (count == null or count.?.* != expected) wrong += 1\n    return wrong\n\nfn add(counts: *HashMap(u32, u32), word: u32) -> !void\n    const slot = try counts.get_or_put(&word)\n    if !slot.found\n        slot.key.* = word\n        slot.value.* = 0\n    slot.value.* += 1\n\nfn check_present(counting: *Counting, size: usize) -> !usize\n    start(counting)\n    var own counts = HashMap(u32, u32)::init()\n    errdefer counts.deinit(own) with counting\n    var wrong: usize = 0\n    for index in 0..size\n        try add(&counts, mn::truncate(u32, index) * 7) with counting\n    const allocations = counting.allocations\n    for index in 0..size\n        const word = mn::truncate(u32, index) * 7\n        const slot = try counts.get_or_put(&word) with counting\n        if (!slot.found or slot.key.* != word or slot.value.* != 1) wrong += 1\n    if (counting.allocations != allocations or counts.length() != size) wrong += 1\n    counts.deinit(own) with counting\n    return wrong\n\nfn fill(counting: *Counting, fail_at: usize, failures: *usize) -> usize\n    start(counting)\n    counting.fail_at = fail_at\n    var own counts = HashMap(u32, u32)::init()\n    var wrong: usize = 0\n    var size: usize = 0\n    while size < 100\n        const live = counting.live\n        match add(&counts, mn::truncate(u32, size) * 7) with counting\n            case (OutOfMemory)\n                failures.* += 1\n                if (counting.live != live) wrong += 1\n                wrong += check_counts(&counts, size, 1)\n                break\n            else size += 1\n    counts.deinit(own) with counting\n    if (counting.live != 0) wrong += 1\n    return wrong\n\nfn main -> !void\n    var counting: Counting = undefined\n    start(&counting)\n    var own counts = HashMap(u32, u32)::init()\n    errdefer counts.deinit(own) with &counting\n    var wrong: usize = 0\n    for round in 0..3\n        for index in 0..100\n            const word = mn::truncate(u32, index) * 7\n            const slot = try counts.get_or_put(&word) with &counting\n            if (slot.found != (round > 0)) wrong += 1\n            if !slot.found\n                slot.key.* = word\n                slot.value.* = 0\n            slot.value.* += 1\n        wrong += check_counts(&counts, 100, mn::truncate(u32, round) + 1)\n    try text::print(&stdout, \"counts {} wrong {}\\n\", { counts.length(), wrong })\n    counts.deinit(own) with &counting\n    var present: usize = 0\n    for size in 1..40\n        present += try check_present(&counting, size)\n    try text::print(&stdout, \"present wrong {}\\n\", { present })\n    var failed: usize = 0\n    var failures: usize = 0\n    for fail_at in 1..20\n        failed += fill(&counting, fail_at, &failures)\n    try text::print(&stdout, \"failures {} wrong {}\\n\", { failures > 1, failed })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("counts 100 wrong 0\npresent wrong 0\nfailures true wrong 0\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that keeps values owning memory in a set and moves them out with to_owned" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::compare::Equal\nimport mn::container::HashSet\nimport mn::convert::ToOwned\nimport mn::hash::Hash\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [262144]u8\n    used: usize\n    fail_at: usize\n    allocations: usize\n    frees: usize\n    live: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        counting.allocations += 1\n        if (counting.allocations == counting.fail_at) return memory::Error::OutOfMemory\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(counting: *Counting, items: []T, count: usize) -> bool\n        if (count > items.length) return false\n        counting.live -= mn::size(T) * (items.length - count)\n        return true\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        counting.frees += 1\n        counting.live -= mn::size(T) * items.length\n\nfn start(counting: *Counting)\n    counting.used = 0\n    counting.fail_at = 0\n    counting.allocations = 0\n    counting.frees = 0\n    counting.live = 0\n\nstruct Name\n    own bytes: []u8\n\ninstance Deinit(Name)\n\n    fn deinit(own name: *Name) = memory::free(own name.bytes)\n\ninstance Equal(Name)\n\n    fn equal(one: *const(Name), two: *const(Name)) -> bool = memory::equal(one.bytes, two.bytes)\n\ninstance Hash(Name)\n\n    fn hash(value: *const(Name)) -> u64 = Hash::hash(&value.bytes)\n\nfn make(letter: u8, count: usize) -> own memory::Error!Name\n    const own bytes = try memory::allocate(u8, count)\n    for index in 0..count\n        bytes[index] = letter\n    return { bytes = own bytes }\n\nfn insert_made(set: *HashSet(Name), letter: u8, count: usize, pointer: *?*many(u8)) -> own !?Name\n    const own name = try make(letter, count)\n    errdefer memory::free(own name.bytes)\n    pointer.* = name.bytes.pointer\n    return try set.insert(own name)\n\nfn end_value(own value: ?Name)\n    if value as own name\n        memory::free(own name.bytes)\n\nfn end_set(own set: *HashSet(Name))\n    while set.pop() as own name\n        memory::free(own name.bytes)\n    set.deinit(own)\n\nfn end_values(own values: []Name)\n    for index in 0..values.length\n        const own name = memory::move(&values[index])\n        memory::free(own name.bytes)\n    memory::free(own values)\n\nfn check_set(counting: *const(Counting)) -> !void\n    var own set = HashSet(Name)::init()\n    defer end_set(own &set)\n    var a_pointer: ?*many(u8) = null\n    const own first = try insert_made(&set, 'a', 1, &a_pointer)\n    const first_empty = first == null\n    end_value(own first)\n    try text::print(&stdout, \"first {} {}\\n\", { first_empty, set.length() })\n    var b_pointer: ?*many(u8) = null\n    const own second = try insert_made(&set, 'b', 2, &b_pointer)\n    end_value(own second)\n    var again_pointer: ?*many(u8) = null\n    const allocations = counting.allocations\n    const own duplicate = (try insert_made(&set, 'a', 1, &again_pointer)) orelse return\n    defer memory::free(own duplicate.bytes)\n    try text::print(&stdout, \"duplicate {} {} {} {}\\n\", { duplicate.bytes.pointer == again_pointer.?, duplicate.bytes.pointer == a_pointer.?, counting.allocations == allocations + 1, set.length() })\n    const own long_name = try make('b', 2)\n    defer memory::free(own long_name.bytes)\n    const own short_name = try make('b', 1)\n    defer memory::free(own short_name.bytes)\n    try text::print(&stdout, \"contains {} {}\\n\", { set.contains(&long_name), set.contains(&short_name) })\n    const own removed = set.remove(&long_name) orelse return\n    defer memory::free(own removed.bytes)\n    try text::print(&stdout, \"removed {} {} {}\\n\", { removed.bytes.pointer == b_pointer.?, set.length(), set.contains(&long_name) })\n\nfn check_owned(counting: *const(Counting)) -> !void\n    var own set = HashSet(Name)::init()\n    errdefer end_set(own &set)\n    for index in 0..11\n        var unused: ?*many(u8) = null\n        const own previous = try insert_made(&set, 'a' + mn::truncate(u8, index), 1, &unused)\n        end_value(own previous)\n    const before = counting.allocations\n    const own values: []Name = try set.to_owned(own)\n    defer end_values(own values)\n    try text::print(&stdout, \"owned {} {}\\n\", { values.length, counting.allocations == before })\n\nfn main -> !void\n    var counting: Counting = undefined\n    start(&counting)\n    with &counting\n    try check_set(&counting)\n    try check_owned(&counting)\n    try text::print(&stdout, \"live {}\\n\", { counting.live })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("first true 1\nduplicate true false true 2\ncontains true false\nremoved true 1 false\nowned 11 true\nlive 0\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that leaves a set unchanged when any allocation of an insert fails" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container::HashSet\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [262144]u8\n    used: usize\n    fail_at: usize\n    allocations: usize\n    frees: usize\n    live: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        counting.allocations += 1\n        if (counting.allocations == counting.fail_at) return memory::Error::OutOfMemory\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(counting: *Counting, items: []T, count: usize) -> bool\n        if (count > items.length) return false\n        counting.live -= mn::size(T) * (items.length - count)\n        return true\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        counting.frees += 1\n        counting.live -= mn::size(T) * items.length\n\nfn start(counting: *Counting)\n    counting.used = 0\n    counting.fail_at = 0\n    counting.allocations = 0\n    counting.frees = 0\n    counting.live = 0\n\nfn fill(set: *HashSet(u32), count: usize) -> memory::Error!void\n    for index in 0..count\n        const previous = try set.insert(mn::truncate(u32, index))\n        _ = previous\n\nfn attempt(counting: *Counting, fail_at: usize) -> !void\n    start(counting)\n    counting.fail_at = fail_at\n    with counting\n    var own set = HashSet(u32)::init()\n    const filled = fill(&set, 7)\n    var failed = false\n    match filled\n        case (OutOfMemory) failed = true\n        else noop\n    var all = true\n    for index in 0..set.length()\n        const lookup_591: u32 = mn::truncate(u32, index)\n        if (!set.contains(&lookup_591)) all = false\n    const lookup_602: u32 = 6\n    const length = set.length()\n    const has_six = set.contains(&lookup_602)\n    const live = counting.live\n    set.deinit(own)\n    try text::print(&stdout, \"{} {} {} {} {} {}\\n\", { fail_at, failed, length, all, has_six, live })\n    try text::print(&stdout, \"live {}\\n\", { counting.live })\n\nfn main -> !void\n    var counting: Counting = undefined\n    for fail_at in 1..6\n        try attempt(&counting, fail_at)\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("1 true 0 true false 0\nlive 0\n2 true 0 true false 0\nlive 0\n3 true 6 true false 88\nlive 0\n4 true 6 true false 88\nlive 0\n5 false 7 true true 176\nlive 0\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that empties, clears, deinitializes and reuses sets and frees a list of sets in a loop" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container::ArrayList\nimport mn::container::HashSet\nimport mn::convert::{ ToOwned, View }\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [262144]u8\n    used: usize\n    fail_at: usize\n    allocations: usize\n    frees: usize\n    live: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        counting.allocations += 1\n        if (counting.allocations == counting.fail_at) return memory::Error::OutOfMemory\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(counting: *Counting, items: []T, count: usize) -> bool\n        if (count > items.length) return false\n        counting.live -= mn::size(T) * (items.length - count)\n        return true\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        counting.frees += 1\n        counting.live -= mn::size(T) * items.length\n\nfn start(counting: *Counting)\n    counting.used = 0\n    counting.fail_at = 0\n    counting.allocations = 0\n    counting.frees = 0\n    counting.live = 0\n\nfn add(set: *HashSet(u8), first: u8, count: usize) -> memory::Error!void\n    for index in 0..count\n        const previous = try set.insert(first + mn::truncate(u8, index))\n        _ = previous\n\nfn set_of(first: u8, count: usize) -> own memory::Error!HashSet(u8)\n    var own set = HashSet(u8)::init()\n    errdefer set.deinit(own)\n    try add(&set, first, count)\n    return set\n\nfn end_sets(own sets: *ArrayList(HashSet(u8)))\n    while sets.pop() as own set\n        set.deinit(own)\n    sets.deinit(own)\n\nfn check_reuse(counting: *const(Counting)) -> !void\n    var own set = HashSet(u8)::init()\n    errdefer set.deinit(own)\n    const lookup_541: u8 = 1\n    const removed = set.remove(&lookup_541)\n    const lookup_552: u8 = 1\n    try text::print(&stdout, \"empty {} {} {} {} {}\\n\", { set.length(), set.contains(&lookup_552), removed == null, set.length(), counting.allocations })\n    set.clear()\n    set.deinit(own)\n    set = HashSet(u8)::init()\n    const own nothing: []u8 = try set.to_owned(own)\n    defer memory::free(own nothing)\n    set = HashSet(u8)::init()\n    try text::print(&stdout, \"nothing {} {} {}\\n\", { nothing.length, counting.allocations, counting.frees })\n    try add(&set, 0, 4)\n    const allocations = counting.allocations\n    set.clear()\n    const lookup_643: u8 = 1\n    try text::print(&stdout, \"cleared {} {} {} {}\\n\", { set.length(), set.contains(&lookup_643), set.length(), counting.live > 0 })\n    try add(&set, 10, 4)\n    const lookup_664: u8 = 1\n    const lookup_665: u8 = 11\n    try text::print(&stdout, \"refilled {} {} {} {}\\n\", { set.length(), set.contains(&lookup_664), set.contains(&lookup_665), counting.allocations == allocations })\n    const lookup_676: u8 = 11\n    const middle = set.remove(&lookup_676)\n    const lookup_687: u8 = 10\n    const lookup_688: u8 = 11\n    const lookup_689: u8 = 12\n    const lookup_690: u8 = 13\n    try text::print(&stdout, \"middle {} {} {} {} {} {}\\n\", { middle.? == 11, set.length(), set.contains(&lookup_687), set.contains(&lookup_688), set.contains(&lookup_689), set.contains(&lookup_690) })\n    set.clear()\n    const own cleared: []u8 = try set.to_owned(own)\n    defer memory::free(own cleared)\n    set = HashSet(u8)::init()\n    try text::print(&stdout, \"cleared owned {} {} {}\\n\", { cleared.length, set.length(), counting.live })\n    try add(&set, 20, 2)\n    set.deinit(own)\n    set = HashSet(u8)::init()\n    const lookup_761: u8 = 20\n    try text::print(&stdout, \"deinit {} {} {}\\n\", { set.length(), set.contains(&lookup_761), counting.live })\n    try add(&set, 30, 1)\n    const lookup_782: u8 = 30\n    try text::print(&stdout, \"reused {} {}\\n\", { set.length(), set.contains(&lookup_782) })\n    set.deinit(own)\n\nfn check_sets() -> !void\n    var own sets = ArrayList(HashSet(u8))::init()\n    defer end_sets(own &sets)\n    try sets.append(try set_of(1, 2))\n    try sets.append(try set_of(3, 3))\n    const lookup_three: u8 = 3\n    try text::print(&stdout, \"sets {} {} {}\\n\", { sets.view([]const(HashSet(u8)))[0].values().length, sets.view([]const(HashSet(u8)))[1].values().length, sets.view([]const(HashSet(u8)))[1].contains(&lookup_three) })\n\nfn main -> !void\n    var counting: Counting = undefined\n    start(&counting)\n    with &counting\n    try check_reuse(&counting)\n    try check_sets()\n    try text::print(&stdout, \"live {}\\n\", { counting.live })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("empty 0 false true 0 0\nnothing 0 0 4\ncleared 0 false 0 true\nrefilled 4 false true true\nmiddle true 3 true false true true\ncleared owned 0 0 0\ndeinit 0 false 0\nreused 1 true\nsets 2 3 true\nlive 0\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that pops the last value of a set when empty, with one value, with several and between inserts and removes, and moves owning values out with own names" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container::HashSet\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nstruct Counting\n    bytes: [262144]u8\n    used: usize\n    fail_at: usize\n    allocations: usize\n    frees: usize\n    live: usize\n\ninstance Allocator(Counting)\n\n    fn allocate(counting: *Counting, type T, count: usize) -> own memory::Error![]T\n        counting.allocations += 1\n        if (counting.allocations == counting.fail_at) return memory::Error::OutOfMemory\n        const size = mn::size(T) * count\n        const start = (counting.used + mn::alignment(T) - 1) / mn::alignment(T) * mn::alignment(T)\n        counting.used = start + size\n        counting.live += size\n        return mn::cast(*many(T), counting.bytes[start..counting.used].pointer)[0..count]\n\n    fn(type T) resize(_: *Counting, _: []T, _: usize) -> bool = false\n\n    fn(type T) free(counting: *Counting, own items: []const(T))\n        counting.frees += 1\n        counting.live -= mn::size(T) * items.length\n\nfn start(counting: *Counting)\n    counting.used = 0\n    counting.fail_at = 0\n    counting.allocations = 0\n    counting.frees = 0\n    counting.live = 0\n\nfn make(letter: u8, count: usize) -> own memory::Error![]u8\n    const own bytes = try memory::allocate(u8, count)\n    for index in 0..count\n        bytes[index] = letter\n    return bytes\n\nfn release(own bytes: []u8) = memory::free(own bytes)\n\nfn check(set: *const(HashSet(u32)), popped: u32) -> usize\n    var wrong: usize = 0\n    if (set.contains(&popped)) wrong += 1\n    for index in 0..set.length()\n        const value = set.values()[index]\n        if (!set.contains(&value)) wrong += 1\n    return wrong\n\nfn main -> !void\n    var counting: Counting = undefined\n    start(&counting)\n    with &counting\n    try check_numbers()\n    try check_names(&counting)\n    try text::print(&stdout, \"live {}\\n\", { counting.live })\n\nfn check_numbers() -> !void\n    var own numbers = HashSet(u32)::init()\n    defer numbers.deinit(own)\n    const empty = numbers.pop()\n    try text::print(&stdout, \"empty {} {}\\n\", { empty == null, numbers.length() })\n    _ = try numbers.insert(7)\n    const only = numbers.pop()\n    const lookup_seven: u32 = 7\n    try text::print(&stdout, \"one {} {} {}\\n\", { only.?, numbers.length(), numbers.contains(&lookup_seven) })\n    for value in 0..6\n        _ = try numbers.insert(mn::truncate(u32, value))\n    while numbers.pop() as value\n        try text::print(&stdout, \"{} \", { value })\n    try text::print(&stdout, \"left {}\\n\", { numbers.length() })\n    _ = try numbers.insert(1)\n    _ = try numbers.insert(2)\n    _ = try numbers.insert(3)\n    const third = numbers.pop()\n    _ = try numbers.insert(4)\n    _ = try numbers.insert(2)\n    const fourth = numbers.pop()\n    const lookup_one: u32 = 1\n    const removed = numbers.remove(&lookup_one)\n    const second = numbers.pop()\n    try text::print(&stdout, \"interleaved {} {} {} {} {}\\n\", { third.?, fourth.?, removed.?, second.?, numbers.length() })\n    _ = try numbers.insert(5)\n    const lookup_two: u32 = 2\n    const lookup_five: u32 = 5\n    try text::print(&stdout, \"refilled {} {} {}\\n\", { numbers.contains(&lookup_two), numbers.contains(&lookup_five), numbers.length() })\n    _ = numbers.pop()\n    for value in 0..40\n        _ = try numbers.insert(mn::truncate(u32, value))\n    var wrong: usize = 0\n    while numbers.pop() as value\n        wrong += check(&numbers, value)\n    try text::print(&stdout, \"wrong {} {}\\n\", { wrong, numbers.length() })\n\nfn check_names(counting: *const(Counting)) -> !void\n    var own names = HashSet([]u8)::init()\n    defer names.deinit(own)\n    for index in 0..5\n        const own previous = try names.insert(try make('a' + mn::truncate(u8, index), index + 1))\n        if previous as own name\n            release(own name)\n    const before = counting.frees\n    if names.pop() as own name\n        defer release(own name)\n        try text::print(&stdout, \"first {s}\\n\", { name })\n    var count: usize = 0\n    while names.pop() as own name\n        count += name.length\n        release(own name)\n    try text::print(&stdout, \"names {} {} {}\\n\", { count, names.length(), counting.frees - before })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("empty true 0\none 7 0 false\n5 4 3 2 1 0 left 0\ninterleaved 3 4 1 2 0\nrefilled false true 1\nwrong 0 0\nfirst eeeee\nnames 10 0 5\nlive 0\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that takes a read-only address of a constant for a method" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::process::stdout\nimport mn::stream::Writer\nimport mn::text\n\ntypeclass Name(type T)\n\n    fn name(value: T) -> u8\n\ntypeclass Bump(type T)\n\n    fn bump(value: T)\n\ntypeclass Both(type T)\n\n    fn both(value: T) -> u8\n\nstruct Data\n    number: u8\n\ninstance Name(*const(Data))\n\n    fn name(value: *const(Data)) -> u8 = value.number\n\ninstance Bump(*Data)\n\n    fn bump(value: *Data)\n        value.number += 1\n\ninstance Both(*Data)\n\n    fn both(_: *Data) -> u8 = 1\n\ninstance Both(*const(Data))\n\n    fn both(_: *const(Data)) -> u8 = 2\n\nfn main -> !void\n    const fixed = Data{ number = 4 }\n    var changing = Data{ number = 5 }\n    changing.bump()\n    try text::print(&stdout, \"{} {}\\n\", { fixed.name(), changing.name() })\n    try text::print(&stdout, \"{} {}\\n\", { fixed.both(), changing.both() })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);
    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("4 6\n2 1\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

