test "Generator.generate: builds an executable that reads and writes through pointers chosen by each instance" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container\nimport mn::convert::{ To, View }\nimport mn::filesystem\nimport mn::hash\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process::stdin\nimport mn::process::stdout\nimport mn::stream\nimport mn::stream::Reader\nimport mn::stream::Writer\nimport mn::text\n\nstruct Source\n    bytes: []const(u8)\n\ninstance Reader(Source)\n\n    fn read(source: *Source, buffer: []u8) -> !usize\n        const count = if (source.bytes.length < buffer.length) source.bytes.length else buffer.length\n        memory::copy(buffer[..count], source.bytes[..count])\n        source.bytes = source.bytes[count..]\n        return count\n\nfn emit(writer: *Writer, number: u8) -> !void\n    const own line = try text::format(\"{} {}\\n\", { number, number })\n    defer memory::free(own line)\n    try writer.write(line)\n\nfn read_once(reader: *stream::Reader) -> !usize\n    var buffer: [16]u8 = undefined\n    return Reader::read(reader, buffer[..])\n\nfn show_through_pointer(path: *filesystem::Path) -> !void\n    const own content = try path.to([]u8)\n    defer memory::free(own content)\n    try text::print(&stdout, \"pointer {s}\\n\", { content })\n\nfn main -> !void\n    with memory::Heap\n    const output = stdout\n    try text::print(&output, \"constant stdout\\n\", {})\n    try text::print(&stdout, \"stdout\\n\", {})\n    try emit(&stdout, 1)\n    try emit(&output, 2)\n    var own path = try \"written.txt\".to(filesystem::Path)\n    defer path.deinit(own)\n    const file = try filesystem::File::open(path, { mode = ::Write })\n    defer file.close()\n    const own written_line = try text::format(\"line {}\\n{}\", { 3u8, 4u8 })\n    defer memory::free(own written_line)\n    try file.write(written_line)\n    try emit(&file, 5)\n    var changing = try filesystem::File::open(path)\n    defer changing.close()\n    const count = try read_once(&changing)\n    try text::print(&stdout, \"read {}\\n\", { count })\n    var own listed = mn::container::ArrayList(u8)::init()\n    defer listed.deinit(own)\n    const own listed_line = try text::format(\"{}-{}\\n\", { 6u8, 7u8 })\n    defer memory::free(own listed_line)\n    try listed.write(listed_line)\n    try emit(&listed, 8)\n    try text::print(&stdout, \"list {s}\\n\", { listed.view([]const(u8)) })\n    const own written = try path.to([]u8)\n    defer memory::free(own written)\n    const own inferred: []u8 = try path.to(_)\n    defer memory::free(own inferred)\n    const own fixed_path = try \"a/b\".to(filesystem::Path)\n    defer fixed_path.deinit(own)\n    const own fixed_text = try fixed_path.to([]u8)\n    defer memory::free(own fixed_text)\n    const own fixed_inferred: []u8 = try fixed_path.to(_)\n    defer memory::free(own fixed_inferred)\n    try text::print(&stdout, \"path {s} {s} {s} {s}\\n\", { written, inferred, fixed_text, fixed_inferred })\n    try show_through_pointer(&path)\n    var own missing = fixed_path.absolute() catch filesystem::Path::init()\n    missing.deinit(own)\n    const empty_digest = try hash::sha256(&stdin)\n    var source = Source{ bytes = \"abc\" }\n    const source_digest = try hash::sha256(&source)\n    var again = try filesystem::File::open(path)\n    defer again.close()\n    const file_digest = try hash::sha256(&again)\n    try text::print(&stdout, \"{x} {x} {}\\n\", { empty_digest[..2], source_digest[..2], file_digest.length })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings(
        "constant stdout\nstdout\n1 1\n2 2\nread 12\nlist 6-7\n8 8\n\npath written.txt written.txt a/b a/b\npointer written.txt\ne3b0 ba78 32\n",
        result.stdout,
    );
    try std.testing.expectEqual(0, result.term.exited);
    const limit: std.Io.Limit = .limited(1024);
    try std.testing.expectEqualStrings("line 3\n45 5\n", try build_directory.readFileAlloc(std.testing.io, "written.txt", allocator, limit));
}

