test "Generator.generate: builds an executable that encodes each number type and bool in little-endian fixed widths into a list and decodes them back from a byte slice" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::codec::Decode\nimport mn::codec::Decoder\nimport mn::codec::Encode\nimport mn::codec::Encoder\nimport mn::codec::binary\nimport mn::container::ArrayList\nimport mn::convert::View\nimport mn::iterator::Iterable\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::stream::Reader\nimport mn::text\n\nfn round_trip(type T, value: T) -> !bool\n    var own output = ArrayList(u8)::init()\n    defer output.deinit(own)\n    var encoder = binary::BinaryEncoder(ArrayList(u8))::init(&output)\n    try encoder.encode(&value)\n    var source = output.view([]const(u8)).iterator()\n    var decoder = binary::BinaryDecoder::init(&source)\n    const back = try decoder.decode(T)\n    var rest: [1]u8 = undefined\n    const left = try source.read(&rest)\n    return back == value and output.length() == mn::size(T) and left == 0\n\nfn show(type T, value: T) -> !void\n    var own output = ArrayList(u8)::init()\n    defer output.deinit(own)\n    var encoder = binary::BinaryEncoder(ArrayList(u8))::init(&output)\n    try encoder.encode(&value)\n    try text::print(&stdout, \"{x}\\n\", { output.view([]const(u8)) })\n\nfn main -> !void\n    with memory::Heap\n    const signed_results = { try round_trip(i8, -128), try round_trip(i8, 127), try round_trip(i16, -32768), try round_trip(i32, -2147483648), try round_trip(i64, -9223372036854775808), try round_trip(i128, -170141183460469231731687303715884105728), try round_trip(isize, -1) }\n    try text::print(&stdout, \"signed {} {} {} {} {} {} {}\\n\", signed_results)\n    const unsigned_results = { try round_trip(u8, 255), try round_trip(u16, 65535), try round_trip(u32, 4294967295), try round_trip(u64, 18446744073709551615), try round_trip(u128, 340282366920938463463374607431768211455), try round_trip(usize, 12345) }\n    try text::print(&stdout, \"unsigned {} {} {} {} {} {}\\n\", unsigned_results)\n    const float_results = { try round_trip(f16, -1.5), try round_trip(f32, 3.25), try round_trip(f64, -0.1), try round_trip(f128, 1.0e100) }\n    try text::print(&stdout, \"floats {} {} {} {}\\n\", float_results)\n    const bool_results = { try round_trip(bool, true), try round_trip(bool, false) }\n    try text::print(&stdout, \"bools {} {}\\n\", bool_results)\n    try show(u32, 0x01020304)\n    try show(i16, -2)\n    try show(f32, 1.5)\n    try show(bool, true)\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("signed true true true true true true true\nunsigned true true true true true true\nfloats true true true true\nbools true true\n04030201\nfeff\n0000c03f\n01\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

