test "Generator.generate: builds an executable that prints SHA-256 digests in hexadecimal" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::convert::To\nimport mn::filesystem\nimport mn::hash\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process::stdin\nimport mn::process::stdout\nimport mn::stream\nimport mn::stream::Writer\nimport mn::text\n\nstruct Source\n    bytes: []const(u8)\n    position: usize\n    limit: usize\n\ninstance stream::Reader(Source)\n\n    fn read(source: *Source, buffer: []u8) -> !usize\n        var count = source.bytes.length - source.position\n        if (count > source.limit) count = source.limit\n        if (count > buffer.length) count = buffer.length\n        for (index in 0..count) buffer[index] = source.bytes[source.position + index]\n        source.position += count\n        return count\n\nfn show(content: []const(u8), limit: usize) -> !void\n    var source = Source{ bytes = content, position = 0, limit = limit }\n    const digest = try hash::sha256(&source)\n    try text::print(&stdout, \"{x}\\n\", { digest[..] })\n\nfn main -> !void\n    with memory::Heap\n    const content = \"abcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijklmnop\"\n    const lengths: [8]usize = { 3, 55, 56, 63, 64, 65, 119, 120 }\n    for length in lengths\n        try show(content[..length], 64)\n    try show(content, 1)\n    const from_stdin = try hash::sha256(&stdin)\n    try text::print(&stdout, \"{x}\\n\", { from_stdin[..] })\n    var own path = try \"input.txt\".to(filesystem::Path)\n    defer path.deinit(own)\n    const file = try filesystem::File::open(path)\n    defer file.close()\n    const from_file = try hash::sha256(&file)\n    try text::print(&stdout, \"{x}\\n\", { from_file[..] })\n    const bytes: [3]u8 = { 0, 10, 255 }\n    try text::print(&stdout, \"{x}\\n\", { bytes[..] })\n    const nothing: []const(u8) = \"\"\n    try text::print(&stdout, \"[{x}]\\n\", { nothing })\n    try text::print(&stdout, \"{x}\\n\", { content[..40] })\n    const integer: u8 = 255\n    try text::print(&stdout, \"{x} {b}\\n\", { integer, integer })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    var text: [120]u8 = undefined;
    for (&text, 0..) |*byte, index| byte.* = 'a' + @as(u8, @intCast(index % 26));
    var file_text: [200]u8 = undefined;
    for (&file_text, 0..) |*byte, index| byte.* = '0' + @as(u8, @intCast(index % 10));
    try output_directory.dir.writeFile(std.testing.io, .{ .sub_path = "build/input.txt", .data = &file_text });
    var expected: std.ArrayList(u8) = .empty;
    const inputs = [_][]const u8{ text[0..3], text[0..55], text[0..56], text[0..63], text[0..64], text[0..65], text[0..119], text[0..120], &text, "", &file_text };
    for (inputs) |input| {
        var digest: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(input, &digest, .{});
        try expected.print(allocator, "{x}\n", .{digest});
    }
    try expected.print(allocator, "000aff\n[]\n{x}\nff 11111111\n", .{text[0..40]});

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);
    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings(expected.items, result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable that hashes input larger than its buffer" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::convert::To\nimport mn::filesystem\nimport mn::hash\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::stream\nimport mn::stream::Writer\nimport mn::text\n\nstruct Source\n    bytes: []const(u8)\n    position: usize\n    limit: usize\n    reads: usize\n\ninstance stream::Reader(Source)\n\n    fn read(source: *Source, buffer: []u8) -> !usize\n        source.reads += 1\n        var count = source.bytes.length - source.position\n        if (count > source.limit) count = source.limit\n        if (count > buffer.length) count = buffer.length\n        for (index in 0..count) buffer[index] = source.bytes[source.position + index]\n        source.position += count\n        return count\n\nfn show(content: []const(u8), limit: usize) -> !void\n    var source = Source{ bytes = content, position = 0, limit = limit, reads = 0 }\n    const digest = try hash::sha256(&source)\n    try text::print(&stdout, \"{x} {}\\n\", { digest[..], source.reads })\n\nfn main -> !void\n    with memory::Heap\n    var large: [200000]u8 = undefined\n    for index in 0..large.length\n        large[index] = mn::truncate(u8, index % 251)\n    const sizes: [6]usize = { 65535, 65536, 65537, 65599, 65600, 200000 }\n    for size in sizes\n        try show(large[..size], 200000)\n        try show(large[..size], 1)\n        try show(large[..size], 1000)\n    var own path = try \"large.bin\".to(filesystem::Path)\n    defer path.deinit(own)\n    const file = try filesystem::File::open(path)\n    defer file.close()\n    const from_file = try hash::sha256(&file)\n    try text::print(&stdout, \"{x}\\n\", { from_file[..] })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const large = try allocator.alloc(u8, 200000);
    for (large, 0..) |*byte, index| byte.* = @intCast(index % 251);
    try output_directory.dir.writeFile(std.testing.io, .{ .sub_path = "build/large.bin", .data = large });
    var expected: std.ArrayList(u8) = .empty;
    const cases = [_]struct { size: usize, whole_reads: usize }{
        .{ .size = 65535, .whole_reads = 2 },
        .{ .size = 65536, .whole_reads = 2 },
        .{ .size = 65537, .whole_reads = 3 },
        .{ .size = 65599, .whole_reads = 3 },
        .{ .size = 65600, .whole_reads = 3 },
        .{ .size = 200000, .whole_reads = 5 },
    };
    for (cases) |case| {
        var digest: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(large[0..case.size], &digest, .{});
        try expected.print(allocator, "{x} {d}\n", .{ digest, case.whole_reads });
        try expected.print(allocator, "{x} {d}\n", .{ digest, case.size + 1 });
        try expected.print(allocator, "{x} {d}\n", .{ digest, (case.size + 999) / 1000 + 1 });
    }
    var file_digest: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(large, &file_digest, .{});
    try expected.print(allocator, "{x}\n", .{file_digest});

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);
    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings(expected.items, result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "integration: parses every integer width at its limits through the standard library" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
