    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::memory\nimport mn::process::stdout\nimport mn::text\nimport mn::text::Parser\n\n\nfn show(type T, low: []const(u8), high: []const(u8), below: []const(u8), above: []const(u8)) -> !void\n    try text::print(&stdout, \"{} {} \", { try low.parse(T), try high.parse(T) })\n    match below.parse(T)\n        case T as value\n            try text::print(&stdout, \"{} \", { value })\n        case (Malformed) try text::print(&stdout, \"Malformed \", {})\n        case (OutOfRange) try text::print(&stdout, \"OutOfRange \", {})\n    match above.parse(T)\n        case T as value\n            try text::print(&stdout, \"{}\\n\", { value })\n        case (Malformed) try text::print(&stdout, \"Malformed\\n\", {})\n        case (OutOfRange) try text::print(&stdout, \"OutOfRange\\n\", {})\n\n\nfn main -> !void\n    with memory::Heap\n    try show(i8, \"-128\", \"127\", \"-129\", \"128\")\n    try show(i16, \"-32768\", \"32767\", \"-32769\", \"32768\")\n    try show(i32, \"-2147483648\", \"2147483647\", \"-2147483649\", \"2147483648\")\n    try show(i64, \"-9223372036854775808\", \"9223372036854775807\", \"-9223372036854775809\", \"9223372036854775808\")\n    try show(i128, \"-170141183460469231731687303715884105728\", \"170141183460469231731687303715884105727\", \"-170141183460469231731687303715884105729\", \"170141183460469231731687303715884105728\")\n    try show(isize, \"-9223372036854775808\", \"9223372036854775807\", \"-9223372036854775809\", \"9223372036854775808\")\n    try show(u8, \"0\", \"255\", \"-1\", \"256\")\n    try show(u16, \"0\", \"65535\", \"-1\", \"65536\")\n    try show(u32, \"0\", \"4294967295\", \"-1\", \"4294967296\")\n    try show(u64, \"0\", \"18446744073709551615\", \"-1\", \"18446744073709551616\")\n    try show(u128, \"0\", \"340282366920938463463374607431768211455\", \"-1\", \"340282366920938463463374607431768211456\")\n    try show(usize, \"-0\", \"18446744073709551615\", \"-1\", \"18446744073709551616\")\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
