    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("-128 127 OutOfRange OutOfRange\n-32768 32767 OutOfRange OutOfRange\n-2147483648 2147483647 OutOfRange OutOfRange\n-9223372036854775808 9223372036854775807 OutOfRange OutOfRange\n-170141183460469231731687303715884105728 170141183460469231731687303715884105727 OutOfRange OutOfRange\n-9223372036854775808 9223372036854775807 OutOfRange OutOfRange\n0 255 OutOfRange OutOfRange\n0 65535 OutOfRange OutOfRange\n0 4294967295 OutOfRange OutOfRange\n0 18446744073709551615 OutOfRange OutOfRange\n0 340282366920938463463374607431768211455 OutOfRange OutOfRange\n0 18446744073709551615 OutOfRange OutOfRange\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "integration: parses integers in an explicit base and in the base their prefix gives through the standard library" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::memory\nimport mn::process::stdout\nimport mn::text\nimport mn::text::Base\nimport mn::text::Parser\n\n\nfn show(type T, input: []const(u8), base: Base) -> !void\n    match input.parse(T, { base })\n        case T as value\n            try text::print(&stdout, \"{} \", { value })\n        case (Malformed) try text::print(&stdout, \"Malformed \", {})\n        case (OutOfRange) try text::print(&stdout, \"OutOfRange \", {})\n\n\nfn main -> !void\n    with memory::Heap\n    try show(u8, \"101\", ::Base2)\n    try show(u8, \"11111111\", ::Base2)\n    try show(u8, \"100000000\", ::Base2)\n    try show(u8, \"102\", ::Base2)\n    try show(i8, \"-10000000\", ::Base2)\n    try show(u8, \"ff\", ::Base16)\n    try show(u8, \"FF\", ::Base16)\n    try show(u16, \"fF0a\", ::Base16)\n    try show(i16, \"-8000\", ::Base16)\n    try show(i16, \"8000\", ::Base16)\n    try show(u8, \"fg\", ::Base16)\n    try show(u64, \"zz\", ::Base36)\n    try show(u64, \"ZZ\", ::Base36)\n    try show(u64, \"Monolith\", ::Base36)\n    try show(i64, \"-a\", ::Base11)\n    try show(u8, \"777\", ::Base8)\n    try show(u8, \"377\", ::Base8)\n    try show(u8, \"42\", ::Base10)\n    try show(u8, \"\", ::Base16)\n    try show(u8, \"-\", ::Base16)\n    try text::print(&stdout, \"\\n\", {})\n    try show(u8, \"0x10\", ::Base16)\n    try show(u8, \"0b101\", ::Base2)\n    try show(u8, \"0o17\", ::Base8)\n    try show(u8, \"0x10\", ::Base10)\n    try text::print(&stdout, \"\\n\", {})\n    try show(u8, \"0x1F\", ::Prefixed)\n    try show(u8, \"0xff\", ::Prefixed)\n    try show(u8, \"0o17\", ::Prefixed)\n    try show(u8, \"0b101\", ::Prefixed)\n    try show(u8, \"42\", ::Prefixed)\n    try show(u8, \"0\", ::Prefixed)\n    try show(i16, \"-0x10\", ::Prefixed)\n    try show(i16, \"-0b11\", ::Prefixed)\n    try show(i16, \"-0o10\", ::Prefixed)\n    try show(i16, \"-42\", ::Prefixed)\n    try show(u8, \"0x\", ::Prefixed)\n    try show(u8, \"0X10\", ::Prefixed)\n    try show(u8, \"0b102\", ::Prefixed)\n    try show(u8, \"0o8\", ::Prefixed)\n    try show(u8, \"0x100\", ::Prefixed)\n    try show(u8, \"+0x10\", ::Prefixed)\n    try show(u8, \"0x-10\", ::Prefixed)\n    try text::print(&stdout, \"\\n\", {})\n    try text::print(&stdout, \"{} {} {}\\n\", { try \"42\".parse(i64), try \"ff\".parse(u8, { base = ::Base16 }), try \"0b1010\".parse(u8, { base = ::Prefixed }) })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("5 255 OutOfRange Malformed -128 255 255 65290 -32768 OutOfRange Malformed 1295 1295 1777686423173 -10 OutOfRange 255 42 Malformed Malformed \nMalformed Malformed Malformed Malformed \n31 255 15 5 42 0 -16 -3 -8 -42 Malformed Malformed Malformed Malformed OutOfRange Malformed Malformed \n42 255 10\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

