test "integration: parses bytes as a copy and in a base of a power of two through the standard library" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::memory\nimport mn::process::stdout\nimport mn::text\nimport mn::text::BytesBase\nimport mn::text::Parser\n\n\nfn show(input: []const(u8), base: BytesBase) -> !void\n    match input.parse([]u8, { base })\n        case []u8 as own bytes\n            defer memory::free(own bytes)\n            try text::print(&stdout, \"[{x}] \", { bytes })\n        case (Malformed) try text::print(&stdout, \"Malformed \", {})\n        case (OutOfRange, OutOfMemory) try text::print(&stdout, \"other \", {})\n\n\nfn main -> !void\n    with memory::Heap\n    const input = \"plain text\"\n    const own copied = try input.parse([]u8)\n    defer memory::free(own copied)\n    copied[0] = 'P'\n    try text::print(&stdout, \"{s} {s}\\n\", { copied, input })\n    const own empty = try \"\".parse([]u8)\n    defer memory::free(own empty)\n    try text::print(&stdout, \"{}\\n\", { empty.length })\n    try show(\"1010010111111111\", ::Base2)\n    try show(\"22113333\", ::Base4)\n    try show(\"77777777\", ::Base8)\n    try show(\"deadBEEF\", ::Base16)\n    try show(\"00ff\", ::Base16)\n    try show(\"vvvvvvvv\", ::Base32)\n    try show(\"VVVVVVVV\", ::Base32)\n    try show(\"01234567\", ::Base32)\n    try show(\"\", ::Base16)\n    try text::print(&stdout, \"\\n\", {})\n    try show(\"1010\", ::Base2)\n    try show(\"123\", ::Base4)\n    try show(\"77777\", ::Base8)\n    try show(\"abc\", ::Base16)\n    try show(\"vvvv\", ::Base32)\n    try show(\"102\", ::Base2)\n    try show(\"124\", ::Base4)\n    try show(\"78\", ::Base8)\n    try show(\"fg\", ::Base16)\n    try show(\"0w\", ::Base32)\n    try show(\"0x10\", ::Base16)\n    try show(\"/0\", ::Base16)\n    try show(\":0\", ::Base16)\n    try show(\"@0\", ::Base16)\n    try show(\"G0\", ::Base16)\n    try show(\"`0\", ::Base16)\n    try show(\"g0\", ::Base16)\n    try text::print(&stdout, \"\\n\", {})\n    const value: [32]u8 = { 0x00, 0x0f, 0xf0, 0xff, 0x01, 0x10, 0x7f, 0x80, 0x5a, 0xa5, 0x09, 0x0a, 0x90, 0xa0, 0x12, 0x34, 0x56, 0x78, 0x9a, 0xbc, 0xde, 0xf1, 0x23, 0x45, 0x67, 0x89, 0xab, 0xcd, 0xef, 0xfe, 0xdc, 0xba }\n    const own written = try text::format(\"{x}\", { value[..] })\n    defer memory::free(own written)\n    const own read = try written.parse([]u8, { base = ::Base16 })\n    defer memory::free(own read)\n    try text::print(&stdout, \"{s} {}\\n\", { written, memory::equal(read, &value) })\n    try show(\"0xdeadBEEF\", ::Prefixed)\n    try show(\"0o77777777\", ::Prefixed)\n    try show(\"0b0000000111111111\", ::Prefixed)\n    try show(\"0x\", ::Prefixed)\n    try show(\"deadbeef\", ::Prefixed)\n    try show(\"0X10\", ::Prefixed)\n    try show(\"0xabc\", ::Prefixed)\n    try show(\"0o7777\", ::Prefixed)\n    try show(\"0b1010\", ::Prefixed)\n    try show(\"-0x10\", ::Prefixed)\n    try text::print(&stdout, \"\\n\", {})\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("Plain text plain text\n0\n[a5ff] [a5ff] [ffffff] [deadbeef] [00ff] [ffffffffff] [ffffffffff] [00443214c7] [] \nMalformed Malformed Malformed Malformed Malformed Malformed Malformed Malformed Malformed Malformed Malformed Malformed Malformed Malformed Malformed Malformed Malformed \n000ff0ff01107f805aa5090a90a0123456789abcdef123456789abcdeffedcba true\n[deadbeef] [ffffff] [01ff] [] Malformed Malformed Malformed Malformed Malformed Malformed \n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "integration: parses bytes in base64 through the standard library" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
