    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::memory\nimport mn::process::stdout\nimport mn::text\nimport mn::text::Parser\n\n\nfn show(input: []const(u8)) -> !void\n    match input.parse([]u8, { base = ::Base64 })\n        case []u8 as own bytes\n            defer memory::free(own bytes)\n            try text::print(&stdout, \"[{s}] \", { bytes })\n        case (Malformed) try text::print(&stdout, \"Malformed \", {})\n        case (OutOfRange, OutOfMemory) try text::print(&stdout, \"other \", {})\n\n\nfn show_bytes(input: []const(u8)) -> !void\n    const own bytes = try input.parse([]u8, { base = ::Base64 })\n    defer memory::free(own bytes)\n    try text::print(&stdout, \"[{x}] \", { bytes })\n\n\nfn main -> !void\n    with memory::Heap\n    try show(\"\")\n    try show(\"Zg==\")\n    try show(\"Zm8=\")\n    try show(\"Zm9v\")\n    try show(\"Zm9vYg==\")\n    try show(\"Zm9vYmE=\")\n    try show(\"Zm9vYmFy\")\n    try text::print(&stdout, \"\\n\", {})\n    try show_bytes(\"+/+/\")\n    try show_bytes(\"++++\")\n    try show_bytes(\"////\")\n    try show_bytes(\"AQIDBA==\")\n    try text::print(&stdout, \"\\n\", {})\n    try show(\"Zg=\")\n    try show(\"Zm9vY\")\n    try show(\"Zg\")\n    try show(\"Zg==Zg==\")\n    try show(\"Z===\")\n    try show(\"====\")\n    try show(\"Zm=v\")\n    try show(\"Z=9v\")\n    try show(\"Zm9v=\")\n    try show(\"Zm9-\")\n    try show(\"Zm9_\")\n    try show(\"Zm 9\")\n    try show(\"Zh==\")\n    try show(\"Zm9=\")\n    try text::print(&stdout, \"\\n\", {})\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("[] [f] [fo] [foo] [foob] [fooba] [foobar] \n[fbffbf] [fbefbe] [ffffff] [01020304] \nMalformed Malformed Malformed Malformed Malformed Malformed Malformed Malformed Malformed Malformed Malformed Malformed Malformed Malformed \n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "integration: generates the same C for a group as for single imports through the standard library" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    const sources = [_][]const u8{
        "import mn::text::{ self as words, Parser as TextParser }\nfn main -> !void\n    const value = try words::strip(\" 12 \").parse(u8)\n    _ = value\n",
        "import mn::text as words\nimport mn::text::Parser as TextParser\nfn main -> !void\n    const value = try words::strip(\" 12 \").parse(u8)\n    _ = value\n",
    };
    var generated: [sources.len][]const File = undefined;
    for (sources, &generated) |source, *files| {
        var loader = @import("monolith").Loader.init(program_path, "library");
        try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = source });
        try loader.loadMainModule(&arena, std.testing.io, "main");
        var type_registry: types.Registry = .{};
        var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
        var generator = Generator.init(try analyzer.analyze());
        files.* = try generator.generateFiles(allocator);
    }

    try std.testing.expectEqual(generated[1].len, generated[0].len);
    for (generated[0], generated[1]) |group, single| {
        try std.testing.expectEqualStrings(single.path, group.path);
        try std.testing.expectEqualStrings(single.contents, group.contents);
    }
}

