    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::process::stdout\nimport mn::text\nimport mn::text::Parser\n\n\nfn show(type T, inputs: []const([]const(u8))) -> !void\n    for input in inputs\n        match input.parse(T)\n            case T as value\n                try text::print(&stdout, \"{} \", { value })\n            case (Malformed) try text::print(&stdout, \"Malformed \", {})\n            case (OutOfRange) try text::print(&stdout, \"OutOfRange \", {})\n    try text::print(&stdout, \"\\n\", {})\n\n\nfn main -> !void\n    try show(i8, { \"127\", \"-128\", \"128\", \"-129\", \"007\", \"-0\", \"-000000000000000000000000000000000000000000000000005\", \"999999999999999999999999999999999999999999999999999999999999\", \"\", \"-\", \"+1\", \" 1\", \"1 \", \"1_000\", \"0x1\", \"1.0\", \"--1\", \"1e3\", \"999999999999999999999999999999999999999999999999999999999999x\" })\n    try show(i16, { \"32767\", \"-32768\", \"32768\", \"-32769\", \"007\", \"-0\", \"-000000000000000000000000000000000000000000000000005\", \"999999999999999999999999999999999999999999999999999999999999\", \"\", \"-\", \"+1\", \" 1\", \"1 \", \"1_000\", \"0x1\", \"1.0\", \"--1\", \"1e3\", \"999999999999999999999999999999999999999999999999999999999999x\" })\n    try show(i32, { \"2147483647\", \"-2147483648\", \"2147483648\", \"-2147483649\", \"007\", \"-0\", \"-000000000000000000000000000000000000000000000000005\", \"999999999999999999999999999999999999999999999999999999999999\", \"\", \"-\", \"+1\", \" 1\", \"1 \", \"1_000\", \"0x1\", \"1.0\", \"--1\", \"1e3\", \"999999999999999999999999999999999999999999999999999999999999x\" })\n    try show(i64, { \"9223372036854775807\", \"-9223372036854775808\", \"9223372036854775808\", \"-9223372036854775809\", \"007\", \"-0\", \"-000000000000000000000000000000000000000000000000005\", \"999999999999999999999999999999999999999999999999999999999999\", \"\", \"-\", \"+1\", \" 1\", \"1 \", \"1_000\", \"0x1\", \"1.0\", \"--1\", \"1e3\", \"999999999999999999999999999999999999999999999999999999999999x\" })\n    try show(i128, { \"170141183460469231731687303715884105727\", \"-170141183460469231731687303715884105728\", \"170141183460469231731687303715884105728\", \"-170141183460469231731687303715884105729\", \"007\", \"-0\", \"-000000000000000000000000000000000000000000000000005\", \"999999999999999999999999999999999999999999999999999999999999\", \"\", \"-\", \"+1\", \" 1\", \"1 \", \"1_000\", \"0x1\", \"1.0\", \"--1\", \"1e3\", \"999999999999999999999999999999999999999999999999999999999999x\" })\n    try show(isize, { \"9223372036854775807\", \"-9223372036854775808\", \"9223372036854775808\", \"-9223372036854775809\", \"007\", \"-0\", \"-000000000000000000000000000000000000000000000000005\", \"999999999999999999999999999999999999999999999999999999999999\", \"\", \"-\", \"+1\", \" 1\", \"1 \", \"1_000\", \"0x1\", \"1.0\", \"--1\", \"1e3\", \"999999999999999999999999999999999999999999999999999999999999x\" })\n    try show(u8, { \"255\", \"0\", \"256\", \"-1\", \"007\", \"-0\", \"-000000000000000000000000000000000000000000000000005\", \"999999999999999999999999999999999999999999999999999999999999\", \"\", \"-\", \"+1\", \" 1\", \"1 \", \"1_000\", \"0x1\", \"1.0\", \"--1\", \"1e3\", \"999999999999999999999999999999999999999999999999999999999999x\" })\n    try show(u16, { \"65535\", \"0\", \"65536\", \"-1\", \"007\", \"-0\", \"-000000000000000000000000000000000000000000000000005\", \"999999999999999999999999999999999999999999999999999999999999\", \"\", \"-\", \"+1\", \" 1\", \"1 \", \"1_000\", \"0x1\", \"1.0\", \"--1\", \"1e3\", \"999999999999999999999999999999999999999999999999999999999999x\" })\n    try show(u32, { \"4294967295\", \"0\", \"4294967296\", \"-1\", \"007\", \"-0\", \"-000000000000000000000000000000000000000000000000005\", \"999999999999999999999999999999999999999999999999999999999999\", \"\", \"-\", \"+1\", \" 1\", \"1 \", \"1_000\", \"0x1\", \"1.0\", \"--1\", \"1e3\", \"999999999999999999999999999999999999999999999999999999999999x\" })\n    try show(u64, { \"18446744073709551615\", \"0\", \"18446744073709551616\", \"-1\", \"007\", \"-0\", \"-000000000000000000000000000000000000000000000000005\", \"999999999999999999999999999999999999999999999999999999999999\", \"\", \"-\", \"+1\", \" 1\", \"1 \", \"1_000\", \"0x1\", \"1.0\", \"--1\", \"1e3\", \"999999999999999999999999999999999999999999999999999999999999x\" })\n    try show(u128, { \"340282366920938463463374607431768211455\", \"0\", \"340282366920938463463374607431768211456\", \"-1\", \"007\", \"-0\", \"-000000000000000000000000000000000000000000000000005\", \"999999999999999999999999999999999999999999999999999999999999\", \"\", \"-\", \"+1\", \" 1\", \"1 \", \"1_000\", \"0x1\", \"1.0\", \"--1\", \"1e3\", \"999999999999999999999999999999999999999999999999999999999999x\" })\n    try show(usize, { \"18446744073709551615\", \"0\", \"18446744073709551616\", \"-1\", \"007\", \"-0\", \"-000000000000000000000000000000000000000000000000005\", \"999999999999999999999999999999999999999999999999999999999999\", \"\", \"-\", \"+1\", \" 1\", \"1 \", \"1_000\", \"0x1\", \"1.0\", \"--1\", \"1e3\", \"999999999999999999999999999999999999999999999999999999999999x\" })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
