test "Generator.generate: builds an executable that reads back the same bits from every float it prints for random bit patterns of every width" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::memory\nimport mn::process::stdout\nimport mn::random::Generator\nimport mn::random::Xoshiro256\nimport mn::text\nimport mn::text::Parser\n\n\nfn copy_bits(type T, type F, value: *const(F)) -> T\n    var bits: T = undefined\n    memory::copy(mn::cast(*many(u8), &bits)[0..mn::size(T)], mn::cast(*many(const(u8)), value)[0..mn::size(F)])\n    return bits\n\n\nfn count_mismatches(type T, type B, generator: *Xoshiro256) -> !usize\n    var mismatches: usize = 0\n    for _ in 0..4000\n        const wide = (mn::convert(u128, generator.next()) << 64) | mn::convert(u128, generator.next())\n        const bits = mn::truncate(B, wide)\n        const value = copy_bits(T, B, &bits)\n        const own printed = try text::format(\"{}\", { value })\n        defer memory::free(own printed)\n        const back = try printed.parse(T)\n        if (copy_bits(B, T, &back) != bits and (value == value or back == back)) mismatches += 1\n    return mismatches\n\n\nfn main -> !void\n    with memory::Heap\n    var generator = Xoshiro256::init(42)\n    const counts = { try count_mismatches(f16, u16, &generator), try count_mismatches(f32, u32, &generator), try count_mismatches(f64, u64, &generator), try count_mismatches(f128, u128, &generator) }\n    try text::print(&stdout, \"{} {} {} {}\\n\", counts)\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("0 0 0 0\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

test "Generator.generate: builds an executable whose f128 sums, differences, products, quotients, negations and comparisons of special values have the same bits on the software path as on the native path" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::memory\nimport mn::process::stdout\nimport mn::text\n\n\nfn copy_bits(type T, type F, value: *const(F)) -> T\n    var bits: T = undefined\n    memory::copy(mn::cast(*many(u8), &bits)[0..mn::size(T)], mn::cast(*many(const(u8)), value)[0..mn::size(F)])\n    return bits\n\n\nfn show(value: f128) -> !void = text::print(&stdout, \" {x}\", { copy_bits(u128, f128, &value) })\n\n\nfn main -> !void\n    const values: [27]u128 = { 0x0, 0x80000000000000000000000000000000, 0x3fff0000000000000000000000000000, 0xbfff0000000000000000000000000000, 0x3fff8000000000000000000000000000, 0x3ffb999999999999999999999999999a, 0x3fff0000000000000000000000000001, 0x3f8e0000000000000000000000000000, 0x3f8d8000000000000000000000000000, 0x3f8e0000000000000000000000000001, 0x1, 0x3, 0xffffffffffffffffffffffffffff, 0x10000000000000000000000000000, 0x3c8d0000000000000000000000000000, 0x7ffeffffffffffffffffffffffffffff, 0xfffeffffffffffffffffffffffffffff, 0x7f8d0000000000000000000000000000, 0x7fff0000000000000000000000000000, 0xffff0000000000000000000000000000, 0x7fff8000000000000000000000000000, 0xffff8000000000000000000000000000, 0x7fff800000000000000000000000abcd, 0x7fff0000000000000000000000001234, 0xffff8000000000000000000000005678, 0xffff000000000000000000000000abcd, 0x4000c000000000000000000000000000 }\n    for left_bits in values\n        for right_bits in values\n            const left = copy_bits(f128, u128, &left_bits)\n            const right = copy_bits(f128, u128, &right_bits)\n            try text::print(&stdout, \"{x} {x}:\", { left_bits, right_bits })\n            try show(left + right)\n            try show(left - right)\n            try show(left * right)\n            try show(left / right)\n            try text::print(&stdout, \" {} {} {} {} {} {}\\n\", { left < right, left <= right, left > right, left >= right, left == right, left != right })\n        const value = copy_bits(f128, u128, &left_bits)\n        try show(-value)\n        try text::print(&stdout, \"\\n\", {})\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);
    const source_directory = try build_directory.openDir(std.testing.io, "source", .{});
    defer source_directory.close(std.testing.io);

    const native = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    const compiler = try std.process.run(allocator, std.testing.io, .{
        .argv = &.{ "sh", "-c", "gcc -std=c23 -Wall -Wextra -Wno-unused-parameter -Wno-unused-variable -pedantic -O2 -flto -DMN_SOFTWARE_F128 $(find . -name '*.c') -o ../software" },
        .cwd = .{ .dir = source_directory },
    });
    try std.testing.expectEqualStrings("", compiler.stderr);
    const software = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./software"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings(native.stdout, software.stdout);
    try std.testing.expectEqual(0, native.term.exited);
    try std.testing.expectEqual(0, software.term.exited);
}

test "Generator.generate: builds an executable whose f128 conversions from and to every integer and float type have the same bits on the software path as on the native path" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::memory\nimport mn::process::stdout\nimport mn::text\n\n\nfn widen_half(value: f16) -> f128 = return value\n\n\nfn widen_single(value: f32) -> f128 = return value\n\n\nfn widen_double(value: f64) -> f128 = return value\n\n\nfn copy_bits(type T, type F, value: *const(F)) -> T\n    var bits: T = undefined\n    memory::copy(mn::cast(*many(u8), &bits)[0..mn::size(T)], mn::cast(*many(const(u8)), value)[0..mn::size(F)])\n    return bits\n\n\nfn show(value: f128) -> !void = text::print(&stdout, \" {x}\", { copy_bits(u128, f128, &value) })\n\n\nfn from_integers(type T, values: []const(T)) -> !void\n    for value in values\n        try show(mn::convert(f128, value))\n    try text::print(&stdout, \"\\n\", {})\n\n\nfn to_integers(type T, values: []const(u128)) -> !void\n    for bits in values\n        try text::print(&stdout, \" {}\", { mn::convert(T, copy_bits(f128, u128, &bits)) })\n    try text::print(&stdout, \"\\n\", {})\n\n\nfn from_floats(type T, type B, values: []const(B)) -> !void\n    for bits in values\n        const value = copy_bits(T, B, &bits)\n        try show(mn::convert(f128, value))\n    try text::print(&stdout, \"\\n\", {})\n\n\nfn to_floats(type T, type B, values: []const(u128)) -> !void\n    for bits in values\n        const value = mn::convert(T, copy_bits(f128, u128, &bits))\n        try text::print(&stdout, \" {x}\", { copy_bits(B, T, &value) })\n    try text::print(&stdout, \"\\n\", {})\n\n\nfn main -> !void\n    try from_integers(i8, { -128, -1, 0, 1, 127 })\n    try from_integers(i16, { -32768, -1, 0, 1, 32767 })\n    try from_integers(i32, { -2147483648, -1, 0, 1, 2147483647 })\n    try from_integers(i64, { -9223372036854775808, -1, 0, 1, 9223372036854775807 })\n    try from_integers(isize, { -9223372036854775808, -1, 0, 1, 9223372036854775807 })\n    try from_integers(i128, { -170141183460469231731687303715884105728, -170141183460469231731687303715884105727, -1, 0, 1, 10384593717069655257060992658440193, 10384593717069655257060992658440195, 20769187434139310514121985316880387, 170141183460469231731687303715884105727 })\n    try from_integers(u8, { 0, 1, 255 })\n    try from_integers(u16, { 0, 1, 65535 })\n    try from_integers(u32, { 0, 1, 4294967295 })\n    try from_integers(u64, { 0, 1, 18446744073709551615 })\n    try from_integers(usize, { 0, 1, 18446744073709551615 })\n    try from_integers(u128, { 0, 1, 10384593717069655257060992658440193, 10384593717069655257060992658440194, 10384593717069655257060992658440195, 20769187434139310514121985316880390, 340282366920938463463374607431768211455 })\n    const small: [8]u128 = { 0x0, 0x80000000000000000000000000000000, 0x3ffe0000000000000000000000000000, 0xbffe0000000000000000000000000000, 0x3fffe000000000000000000000000000, 0xbfffe000000000000000000000000000, 0x00000000000000000000000000000001, 0x80010000000000000000000000000000 }\n    try to_integers(i8, &small)\n    try to_integers(i8, { 0x4005fe00000000000000000000000000, 0xc005ffe0000000000000000000000000 })\n    try to_integers(i16, { 0x400dfffe000000000000000000000000, 0xc00e0000000000000000000000000000 })\n    try to_integers(i32, { 0x401dfffffffc00000000000000000000, 0xc01e0000000000000000000000000000 })\n    try to_integers(i64, { 0x403dfffffffffffffffc000000000000, 0xc03e0000000000000000000000000000 })\n    try to_integers(isize, { 0x403dfffffffffffffffc000000000000, 0xc03e0000000000000000000000000000 })\n    try to_integers(i128, { 0x407dffffffffffffffffffffffffffff, 0xc07e0000000000000000000000000000, 0x406f0000000000000000000000000001 })\n    try to_integers(u8, small[..4])\n    try to_integers(u8, { 0x4006fe00000000000000000000000000 })\n    try to_integers(u16, { 0x400efffe000000000000000000000000 })\n    try to_integers(u32, { 0x401efffffffc00000000000000000000 })\n    try to_integers(u64, { 0x403efffffffffffffffc000000000000 })\n    try to_integers(usize, { 0x403efffffffffffffffc000000000000 })\n    try to_integers(u128, { 0x407effffffffffffffffffffffffffff, 0x406f0000000000000000000000000001 })\n    try from_floats(f16, u16, { 0x0, 0x8000, 0x1, 0x3ff, 0x400, 0x3c00, 0x7bff, 0x7c00, 0xfc00, 0x7e00, 0x7d01, 0xfe55 })\n    try from_floats(f32, u32, { 0x0, 0x80000000, 0x1, 0x7fffff, 0x800000, 0x3f800000, 0x7f7fffff, 0x7f800000, 0xff800000, 0x7fc00000, 0x7f800001, 0xffc12345 })\n    try from_floats(f64, u64, { 0x0, 0x8000000000000000, 0x1, 0xfffffffffffff, 0x10000000000000, 0x3ff0000000000000, 0x7fefffffffffffff, 0x7ff0000000000000, 0xfff0000000000000, 0x7ff8000000000000, 0x7ff0000000000123, 0xfff8000000abcdef })\n    const wide: [24]u128 = { 0x0, 0x80000000000000000000000000000000, 0x3fff0000000000000000000000000000, 0x3ffb999999999999999999999999999a, 0x3fff0000100000000000000000000000, 0x3fff0000100000000000000000000001, 0x3fff0000300000000000000000000000, 0x3fff0000000000000800000000000000, 0x3fff0000000000001800000000000000, 0x3fff0000000000000800000000000001, 0x400effe0000000000000000000000000, 0x407effffffffffffffffffffffffffff, 0x43feffffffffffffffffffffffffffff, 0x7ffeffffffffffffffffffffffffffff, 0x3ff00000000000000000000000000000, 0x3f810000000000000000000000000000, 0x3c000000000000000000000000000000, 0x3bcd0000000000000000000000000000, 0x00000000000000000000000000000001, 0x7fff0000000000000000000000000000, 0xffff0000000000000000000000000000, 0x7fff8000000000000000000000000000, 0x7fff0000000000000000000000001234, 0xffffc123456789abcdef0123456789ab }\n    try to_floats(f16, u16, &wide)\n    try to_floats(f32, u32, &wide)\n    try to_floats(f64, u64, &wide)\n    const third: f16 = 0.333\n    const tenth: f32 = 0.1\n    const huge: f64 = 1.0e300\n    try show(widen_half(third))\n    try show(widen_single(tenth))\n    try show(widen_double(huge))\n    try text::print(&stdout, \"\\n\", {})\n" });
