test "Generator.generate: builds an executable that walks a directory with a path" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::convert::To\nimport mn::convert::View\nimport mn::filesystem\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::stream::Writer\nimport mn::text\n\nfn walk(directory: filesystem::Directory, path: filesystem::Path) -> !void\n    while try directory.next() as entry\n        const own inner_path = try path.join(entry.name.view(filesystem::Path))\n        defer inner_path.deinit(own)\n        const own content = try inner_path.to([]u8)\n        defer memory::free(own content)\n        try text::print(&stdout, \"{s}\\n\", { content })\n        if entry.kind == filesystem::File::Kind::Directory\n            const inner = try filesystem::Directory::open(inner_path)\n            defer inner.close()\n            try walk(inner, inner_path)\n\nfn main -> !void\n    var heap = memory::Heap::init()\n    var own path = try \".\".to(filesystem::Path) with &heap\n    defer path.deinit(own) with &heap\n    const directory = try filesystem::Directory::open(path)\n    defer directory.close()\n    try walk(directory, path) with &heap\n    const own content = try path.to([]u8) with &heap\n    defer memory::free(own content) with &heap\n    try text::print(&stdout, \"{s}\\n\", { content })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const executable = try output_directory.dir.statFile(std.testing.io, "build/main", .{});
    try std.testing.expectEqual(.file, executable.kind);
}

test "Generator.generate: builds an executable that gives the metadata of a file, a directory, a pipe, the targets of symbolic links and a file it cannot read" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::convert::To\nimport mn::filesystem\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nfn find_kind_name(kind: filesystem::File::Kind) -> []const(u8) = match kind\n    case (filesystem::File::Kind::File) \"file\"\n    case (filesystem::File::Kind::Directory) \"directory\"\n    case (filesystem::File::Kind::SymbolicLink) \"symbolic_link\"\n    case (filesystem::File::Kind::Other) \"other\"\n\nfn report(content: []const(u8)) -> !void\n    var own path = try content.to(filesystem::Path)\n    defer path.deinit(own)\n    const metadata = try filesystem::metadata(path)\n    try text::print(&stdout, \"{s} {s} {} {} {}\\n\", { content, find_kind_name(metadata.kind), metadata.size, metadata.modified_time.seconds, metadata.modified_time.nanoseconds })\n\nfn main -> !void\n    with memory::Heap\n    try report(\"file\")\n    try report(\"empty\")\n    try report(\"large\")\n    try report(\"directory\")\n    try report(\"file_link\")\n    try report(\"directory_link\")\n    try report(\"locked\")\n    try report(\"pipe\")\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);
    const setup = try std.process.run(allocator, std.testing.io, .{ .argv = &.{ "sh", "-c", "printf hello > file && touch -m -d @1000000000.123456789 file && touch -a -d @1100000000.111111111 file && : > empty && touch -m -d @1500000000.555555555 empty && truncate -s 5000000000 large && touch -m -d @1600000000.666666666 large && mkdir directory && touch -m -d @1200000000.222222222 directory && touch -a -d @1100000000.111111111 directory && ln -s file file_link && touch -h -d @1300000000.333333333 file_link && ln -s directory directory_link && touch -h -d @1300000000.333333333 directory_link && printf secret > locked && touch -m -d @1400000000.444444444 locked && touch -a -d @1100000000.111111111 locked && chmod 000 locked && mkfifo pipe && touch -m -d @1700000000.777777777 pipe && stat -c %s directory | tr -d '\\n'" }, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("", setup.stderr);
    try std.testing.expectEqual(0, setup.term.exited);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    const expected = try std.fmt.allocPrint(allocator, "file file 5 1000000000 123456789\nempty file 0 1500000000 555555555\nlarge file 5000000000 1600000000 666666666\ndirectory directory {0s} 1200000000 222222222\nfile_link file 5 1000000000 123456789\ndirectory_link directory {0s} 1200000000 222222222\nlocked file 6 1400000000 444444444\npipe other 0 1700000000 777777777\n", .{setup.stdout});
    try std.testing.expectEqualStrings(expected, result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
}

