test "Generator.generate: builds an executable that creates a directory, leaves an existing one alone and creates missing parents when asked" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var output_directory = std.testing.tmpDir(.{});
    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::convert::To\nimport mn::filesystem\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nfn report(content: []const(u8)) -> !void\n    var own path = try content.to(filesystem::Path)\n    defer path.deinit(own)\n    const metadata = try filesystem::metadata(path)\n    try text::print(&stdout, \"{s} {}\\n\", { content, metadata.kind == filesystem::File::Kind::Directory })\n\nfn create(content: []const(u8)) -> !void\n    var own path = try content.to(filesystem::Path)\n    defer path.deinit(own)\n    try filesystem::create_directory(path)\n    try report(content)\n\nfn create_with_parents(content: []const(u8)) -> !void\n    var own path = try content.to(filesystem::Path)\n    defer path.deinit(own)\n    try filesystem::create_directory(path, { create_ancestors = true })\n    try report(content)\n\nfn main -> !void\n    with memory::Heap\n    try create(\"one\")\n    try create(\"existing\")\n    try create_with_parents(\"outer/middle/inner\")\n    try report(\"outer\")\n    try report(\"outer/middle\")\n    try create_with_parents(\"existing//deeper/deepest/\")\n    try create_with_parents(\"existing\")\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const output_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &output_directory.sub_path, "build" });
    try generator.generate(allocator, std.testing.io, "generators/c", output_path);

    const build_directory = try output_directory.dir.openDir(std.testing.io, "build", .{});
    defer build_directory.close(std.testing.io);
    const setup = try std.process.run(allocator, std.testing.io, .{ .argv = &.{ "sh", "-c", "mkdir existing && printf kept > existing/inside" }, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("", setup.stderr);
    try std.testing.expectEqual(0, setup.term.exited);

    const result = try std.process.run(allocator, std.testing.io, .{ .argv = &.{"./main"}, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("one true\nexisting true\nouter/middle/inner true\nouter true\nouter/middle true\nexisting//deeper/deepest/ true\nexisting true\n", result.stdout);
    try std.testing.expectEqual(0, result.term.exited);
    try std.testing.expectEqualStrings("kept", try build_directory.readFileAlloc(std.testing.io, "existing/inside", allocator, .unlimited));
    const permissions = try std.process.run(allocator, std.testing.io, .{ .argv = &.{ "sh", "-c", "expected=$(printf %o $((0777 & ~$(umask)))) && for name in one outer outer/middle outer/middle/inner; do test \"$(stat -c %a $name)\" = \"$expected\" || exit 1; done" }, .cwd = .{ .dir = build_directory } });
    try std.testing.expectEqualStrings("", permissions.stderr);
    try std.testing.expectEqual(0, permissions.term.exited);
}

