    defer output_directory.cleanup();
    const allocator = arena.allocator();
    const program_path = try std.fs.path.join(allocator, &.{ ".zig-cache", "tmp", &program_directory.sub_path });
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::convert::To\nimport mn::convert::View\nimport mn::filesystem\nimport mn::filesystem::Path\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::text\n\nfn report(path: Path, create_ancestors: bool) -> !void\n    match filesystem::create_directory(path, { create_ancestors = create_ancestors })\n        case (filesystem::Error::AlreadyExists) try text::print(&stdout, \"already_exists\\n\", {})\n        case (filesystem::Error::NameTooLong) try text::print(&stdout, \"name_too_long\\n\", {})\n        case (filesystem::Error::NotDirectory) try text::print(&stdout, \"not_directory\\n\", {})\n        case (filesystem::Error::NotFound) try text::print(&stdout, \"not_found\\n\", {})\n        else try text::print(&stdout, \"unexpected\\n\", {})\n\nfn report_text(content: []const(u8), create_ancestors: bool) -> !void\n    var own path = try content.to(Path)\n    defer path.deinit(own)\n    try report(path, create_ancestors)\n\nfn main -> !void\n    with memory::Heap\n    try report_text(\"missing/child\", false)\n    try report_text(\"file\", false)\n    try report_text(\"file\", true)\n    try report_text(\"dangling\", false)\n    try report_text(\"file/child\", false)\n    try report_text(\"file/child/grandchild\", true)\n    try report_text(\"\", false)\n    try report_text(\"\", true)\n    var own nested = try \"/\".to(Path)\n    defer nested.deinit(own)\n    for _ in 0..2048\n        const own longer = try nested.join(\"a\".view(Path))\n        nested.deinit(own)\n        nested = own longer\n    try report(nested, true)\n" });
