test "generateStruct: names nested types and their functions after the types around them" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("monolith").Loader.init(program_path, program_path);
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "struct Directory\n    count: u32\n    flag: bool = false\n    struct Entry\n        name: u8\n        kind: Kind\n\n        fn init(name: u8) -> Self = Self{ name = name, kind = Kind::File }\n    enum Kind\n        File\n        Directory\n    error Failure\n        Closed\n    fn first(self: Self) -> Failure!Entry\n        if (self.count == 0) return Failure::Closed\n        return Entry::init(1)\nfn Stack(type T) -> type\n    return struct\n        top: ?*Node\n        struct Node\n            value: T\n            next: ?*Node\n\n            fn init(value: T) -> Self = Self{ value = value, next = null }\n        fn init() -> Self = Self{ top = null }\n        fn push(self: *Self, node: *Node)\n            node.next = self.top\n            self.top = node\nfn main()\n    const directory = Directory{ count = 1 }\n    const entry = directory.first() catch Directory::Entry::init(0)\n    const kind: Directory::Kind = entry.kind\n    var stack = Stack(u8)::init()\n    var node = Stack(u8)::Node::init(entry.name)\n    stack.push(&node)\n    _ = kind\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqualStrings("main.h", files[0].path);
    try std.testing.expectEqualStrings("main.c", files[1].path);
    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef struct mn_main_9Directory_4Kind {\n    uint32_t tag;\n} mn_main_9Directory_4Kind;\n\ntypedef struct mn_main_9Directory_5Entry {\n    uint8_t name;\n    mn_main_9Directory_4Kind kind;\n} mn_main_9Directory_5Entry;\n\ntypedef struct mn_main_9Directory_7Failure {\n    uint32_t tag;\n} mn_main_9Directory_7Failure;\n\ntypedef struct mn_main_Directory {\n    uint32_t count;\n    bool flag;\n} mn_main_Directory;\n\ntypedef struct mn_main_7Stack_1_4Node {\n    uint8_t value;\n    struct mn_main_7Stack_1_4Node * next;\n} mn_main_7Stack_1_4Node;\n\ntypedef struct mn_main_Stack_1 {\n    struct mn_main_7Stack_1_4Node * top;\n} mn_main_Stack_1;\n\ntypedef struct mn_result_main_9Directory_7Failure_main_9Directory_5Entry mn_result_main_9Directory_7Failure_main_9Directory_5Entry;\n\nmn_main_9Directory_5Entry mn_main_9Directory_5Entry_init(uint8_t name);\nmn_result_main_9Directory_7Failure_main_9Directory_5Entry mn_main_Directory_first(mn_main_Directory self);\nmn_main_7Stack_1_4Node mn_main_7Stack_1_4Node_init(uint8_t value);\nmn_main_Stack_1 mn_main_Stack_1_init();\nvoid mn_main_Stack_1_push(struct mn_main_Stack_1 * self, struct mn_main_7Stack_1_4Node * node);\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n\n#ifndef mn_result_main_9Directory_7Failure_main_9Directory_5Entry_defined\n#define mn_result_main_9Directory_7Failure_main_9Directory_5Entry_defined\ntypedef struct mn_result_main_9Directory_7Failure_main_9Directory_5Entry {\n    mn_main_9Directory_7Failure error;\n    mn_main_9Directory_5Entry value;\n} mn_result_main_9Directory_7Failure_main_9Directory_5Entry;\n#endif\n\nmn_main_9Directory_5Entry mn_main_9Directory_5Entry_init(uint8_t name) {\n    return (mn_main_9Directory_5Entry){ .name = name, .kind = (mn_main_9Directory_4Kind){ .tag = 0 } };\n}\n\nmn_result_main_9Directory_7Failure_main_9Directory_5Entry mn_main_Directory_first(mn_main_Directory self) {\n    if (self.count == 0u) {\n        return (mn_result_main_9Directory_7Failure_main_9Directory_5Entry){ .error = (mn_main_9Directory_7Failure){ .tag = 1 } };\n    }\n    return (mn_result_main_9Directory_7Failure_main_9Directory_5Entry){ .error.tag = 0, .value = mn_main_9Directory_5Entry_init(1u) };\n}\n\nint main() {\n    const mn_main_Directory directory = (mn_main_Directory){ .count = 1u, .flag = false };\n    mn_result_main_9Directory_7Failure_main_9Directory_5Entry mn_temporary_1;\n    const mn_main_9Directory_5Entry entry = (mn_temporary_1 = mn_main_Directory_first(directory), (mn_temporary_1.error.tag == 0 ? mn_temporary_1.value : mn_main_9Directory_5Entry_init(0u)));\n    mn_main_Stack_1 stack = mn_main_Stack_1_init();\n    mn_main_7Stack_1_4Node node = mn_main_7Stack_1_4Node_init(entry.name);\n    mn_main_Stack_1_push(&stack, &node);\n}\n\nmn_main_7Stack_1_4Node mn_main_7Stack_1_4Node_init(uint8_t value) {\n    return (mn_main_7Stack_1_4Node){ .value = value, .next = NULL };\n}\n\nmn_main_Stack_1 mn_main_Stack_1_init() {\n    return (mn_main_Stack_1){ .top = NULL };\n}\n\nvoid mn_main_Stack_1_push(struct mn_main_Stack_1 * self, struct mn_main_7Stack_1_4Node * node) {\n    node->next = self->top;\n    self->top = node;\n}\n",
        files[1].contents,
    );
}

