    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    const compiler_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &compiler_directory.sub_path },
    );
    var loader = @import("monolith").Loader.init(program_path, compiler_path);
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "fn List(type T) -> type\n    return struct\n        first: T\n        count: usize = 0\n\n        fn init(first: T) -> Self = return Self{ first = first }\n        fn get(self: Self) -> T = return self.first\n        fn grow(self: *Self) = self.count += 1\nfn make() -> List(u8) = return { first = 2 }\nfn main()\n    var numbers = List(i32)::init(1)\n    numbers.grow()\n    _ = numbers.get()\n    const flags = List(bool){ first = true }\n    _ = flags.get()\n    _ = make()" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef struct mn_main_List_1 {\n    uint8_t first;\n    size_t count;\n} mn_main_List_1;\n\ntypedef struct mn_main_List_2 {\n    int32_t first;\n    size_t count;\n} mn_main_List_2;\n\ntypedef struct mn_main_List_3 {\n    bool first;\n    size_t count;\n} mn_main_List_3;\n\nmn_main_List_1 mn_main_make();\nmn_main_List_1 mn_main_List_1_init(uint8_t first);\nuint8_t mn_main_List_1_get(mn_main_List_1 self);\nvoid mn_main_List_1_grow(struct mn_main_List_1 * self);\nmn_main_List_2 mn_main_List_2_init(int32_t first);\nint32_t mn_main_List_2_get(mn_main_List_2 self);\nvoid mn_main_List_2_grow(struct mn_main_List_2 * self);\nmn_main_List_3 mn_main_List_3_init(bool first);\nbool mn_main_List_3_get(mn_main_List_3 self);\nvoid mn_main_List_3_grow(struct mn_main_List_3 * self);\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n\nmn_main_List_1 mn_main_make() {\n    return (mn_main_List_1){ .first = 2u, .count = 0u };\n}\n\nint main() {\n    mn_main_List_2 numbers = mn_main_List_2_init(1);\n    mn_main_List_2_grow(&numbers);\n    mn_main_List_2_get(numbers);\n    const mn_main_List_3 flags = (mn_main_List_3){ .first = true, .count = 0u };\n    mn_main_List_3_get(flags);\n    mn_main_make();\n}\n\nmn_main_List_1 mn_main_List_1_init(uint8_t first) {\n    return (mn_main_List_1){ .first = first, .count = 0u };\n}\n\nuint8_t mn_main_List_1_get(mn_main_List_1 self) {\n    return self.first;\n}\n\nvoid mn_main_List_1_grow(struct mn_main_List_1 * self) {\n    size_t * mn_temporary_1;\n    mn_temporary_1 = &self->count, (*mn_temporary_1) = ((*mn_temporary_1) + 1u);\n}\n\nmn_main_List_2 mn_main_List_2_init(int32_t first) {\n    return (mn_main_List_2){ .first = first, .count = 0u };\n}\n\nint32_t mn_main_List_2_get(mn_main_List_2 self) {\n    return self.first;\n}\n\nvoid mn_main_List_2_grow(struct mn_main_List_2 * self) {\n    size_t * mn_temporary_1;\n    mn_temporary_1 = &self->count, (*mn_temporary_1) = ((*mn_temporary_1) + 1u);\n}\n\nmn_main_List_3 mn_main_List_3_init(bool first) {\n    return (mn_main_List_3){ .first = first, .count = 0u };\n}\n\nbool mn_main_List_3_get(mn_main_List_3 self) {\n    return self.first;\n}\n\nvoid mn_main_List_3_grow(struct mn_main_List_3 * self) {\n    size_t * mn_temporary_1;\n    mn_temporary_1 = &self->count, (*mn_temporary_1) = ((*mn_temporary_1) + 1u);\n}\n",
        files[1].contents,
    );
}

