test "generateStruct: generates an inline struct as its field" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("monolith").Loader.init(program_path, program_path);
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "inline struct Count\n    value: u32\n\ninline struct Name\n    bytes: []const(u8)\n\nconst start: Count = { value = 3 }\n\nfn make(value: u32) -> Count = { value = value }\n\nfn read(count: *const(Count)) -> u32 = count.value + start.value\n\nfn rename(name: *Name, bytes: []const(u8)) = name.bytes = bytes\n\nfn first(name: Name) -> u8 = name.bytes[0]\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef uint32_t mn_main_Count;\n\n#ifndef mn_slice_u8_defined\n#define mn_slice_u8_defined\ntypedef struct mn_slice_u8 {\n    uint8_t *items;\n    size_t length;\n} mn_slice_u8;\n#endif\n\ntypedef struct mn_slice_u8 mn_main_Name;\n\nextern const mn_main_Count mn_main_start;\n\nmn_main_Count mn_main_make(uint32_t value);\nuint32_t mn_main_read(uint32_t const * count);\nvoid mn_main_rename(struct mn_slice_u8 * name, mn_slice_u8 bytes);\nuint8_t mn_main_first(mn_main_Name name);\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n\nconst mn_main_Count mn_main_start = 3u;\n\nmn_main_Count mn_main_make(uint32_t value) {\n    return value;\n}\n\nuint32_t mn_main_read(uint32_t const * count) {\n    return ((*count) + mn_main_start);\n}\n\nvoid mn_main_rename(struct mn_slice_u8 * name, mn_slice_u8 bytes) {\n    (*name) = bytes;\n}\n\nuint8_t mn_main_first(mn_main_Name name) {\n    return name.items[0u];\n}\n",
        files[1].contents,
    );
}

