        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef struct mn_main_ParseError {\n    uint32_t tag;\n    union {\n        uint8_t BadDigit;\n    } value;\n} mn_main_ParseError;\n\ntypedef struct mn_main_FileError {\n    uint32_t tag;\n} mn_main_FileError;\n\ntypedef struct mn_main_Token {\n    uint32_t tag;\n    union {\n        int64_t Number;\n    } value;\n} mn_main_Token;\n\ntypedef struct mn_main_ParseError_or_main_FileError mn_main_ParseError_or_main_FileError;\n\nbool mn_main_Token_is_end(mn_main_Token self);\nmn_main_ParseError_or_main_FileError mn_main_widen(mn_main_FileError failure);\nbool mn_main_is_missing(mn_main_ParseError_or_main_FileError failure);\nmn_main_ParseError mn_main_digit(uint8_t value);\nmn_main_Token mn_main_number();\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n\n#ifndef mn_main_ParseError_or_main_FileError_defined\n#define mn_main_ParseError_or_main_FileError_defined\ntypedef struct mn_main_ParseError_or_main_FileError {\n    uint32_t tag;\n    union {\n        uint8_t main_ParseError_BadDigit;\n    } value;\n} mn_main_ParseError_or_main_FileError;\n#endif\n\n#ifndef mn_main_Token_equal_defined\n#define mn_main_Token_equal_defined\nstatic inline bool mn_main_Token_equal(mn_main_Token one, mn_main_Token two) {\n    if (one.tag != two.tag) return false;\n    switch (one.tag) {\n    case 0: return one.value.Number == two.value.Number;\n    default: return true;\n    }\n}\n#endif\n\n#ifndef mn_main_ParseError_or_main_FileError_equal_defined\n#define mn_main_ParseError_or_main_FileError_equal_defined\nstatic inline bool mn_main_ParseError_or_main_FileError_equal(mn_main_ParseError_or_main_FileError one, mn_main_ParseError_or_main_FileError two) {\n    if (one.tag != two.tag) return false;\n    switch (one.tag) {\n    case 2: return one.value.main_ParseError_BadDigit == two.value.main_ParseError_BadDigit;\n    default: return true;\n    }\n}\n#endif\n\n#ifndef mn_main_ParseError_equal_defined\n#define mn_main_ParseError_equal_defined\nstatic inline bool mn_main_ParseError_equal(mn_main_ParseError one, mn_main_ParseError two) {\n    if (one.tag != two.tag) return false;\n    switch (one.tag) {\n    case 2: return one.value.BadDigit == two.value.BadDigit;\n    default: return true;\n    }\n}\n#endif\n\n#ifndef mn_main_ParseError_or_main_FileError_from_main_FileError_defined\n#define mn_main_ParseError_or_main_FileError_from_main_FileError_defined\nstatic inline mn_main_ParseError_or_main_FileError mn_main_ParseError_or_main_FileError_from_main_FileError(mn_main_FileError value) {\n    mn_main_ParseError_or_main_FileError result;\n    result.tag = value.tag;\n    return result;\n}\n#endif\n\n#ifndef mn_main_ParseError_or_main_FileError_from_main_ParseError_defined\n#define mn_main_ParseError_or_main_FileError_from_main_ParseError_defined\nstatic inline mn_main_ParseError_or_main_FileError mn_main_ParseError_or_main_FileError_from_main_ParseError(mn_main_ParseError value) {\n    mn_main_ParseError_or_main_FileError result;\n    result.tag = value.tag;\n    switch (value.tag) {\n    case 2: result.value.main_ParseError_BadDigit = value.value.BadDigit; break;\n    default: break;\n    }\n    return result;\n}\n#endif\n\nbool mn_main_Token_is_end(mn_main_Token self) {\n    return mn_main_Token_equal(self, (mn_main_Token){ .tag = 1 });\n}\n\nmn_main_ParseError_or_main_FileError mn_main_widen(mn_main_FileError failure) {\n    return mn_main_ParseError_or_main_FileError_from_main_FileError(failure);\n}\n\nbool mn_main_is_missing(mn_main_ParseError_or_main_FileError failure) {\n    return mn_main_ParseError_or_main_FileError_equal(failure, mn_main_ParseError_or_main_FileError_from_main_ParseError((mn_main_ParseError){ .tag = 1 }));\n}\n\nmn_main_ParseError mn_main_digit(uint8_t value) {\n    return (mn_main_ParseError){ .tag = 2, .value.BadDigit = value };\n}\n\nmn_main_Token mn_main_number() {\n    return (mn_main_Token){ .tag = 0, .value.Number = 4 };\n}\n",
        files[1].contents,
    );
}

