        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef struct mn_main_Square {\n    int32_t side;\n    bool flag;\n} mn_main_Square;\n\nint32_t mn_main_Square_Shape_area(mn_main_Square self);\nint32_t mn_main_Square_Shape_double(mn_main_Square self);\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n#include \"shapes.h\"\n\nint32_t mn_main_Square_Shape_area(mn_main_Square self) {\n    return self.side;\n}\n\nint main() {\n    const mn_main_Square square = (mn_main_Square){ .side = 2, .flag = false };\n    mn_main_Square_Shape_double(square);\n}\n\nint32_t mn_main_Square_Shape_double(mn_main_Square self) {\n    int32_t mn_temporary_1;\n    int32_t mn_temporary_2;\n    return (mn_temporary_1 = mn_main_Square_Shape_area(self), mn_temporary_2 = mn_shapes_scale(), (mn_temporary_1 * mn_temporary_2));\n}\n",
        files[1].contents,
    );
    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\nint32_t mn_shapes_scale();\n",
        files[2].contents,
    );
    try std.testing.expectEqualStrings(
        "#include \"shapes.h\"\n\nint32_t mn_shapes_scale() {\n    return 2;\n}\n",
        files[3].contents,
    );
}

test "generateFunction: writes an instance function that uses Self as the one that writes its type" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var directory_one = std.testing.tmpDir(.{});
    defer directory_one.cleanup();
    var directory_two = std.testing.tmpDir(.{});
    defer directory_two.cleanup();
    const path_one = try std.fs.path.join(arena.allocator(), &.{ ".zig-cache", "tmp", &directory_one.sub_path });
    const path_two = try std.fs.path.join(arena.allocator(), &.{ ".zig-cache", "tmp", &directory_two.sub_path });
    var loader_one = @import("monolith").Loader.init(path_one, path_one);
    var loader_two = @import("monolith").Loader.init(path_two, path_two);
    try directory_one.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "typeclass Make(type T)\n\n    fn make(seed: u64) -> T\n    fn total(value: *const(T)) -> u64\nstruct Data\n    side: u64\n\n    fn init(side: u64) -> Self = return Data{ side = side }\nfn Box(type T) -> type\n    return struct\n        value: T\ninstance Make(Data)\n\n    fn make(seed: u64) -> Self = return Self::init(seed)\n    fn total(value: *const(Self)) -> u64 = return value.side\ninstance(type A: Make) Make(Box(A))\n\n    fn make(seed: u64) -> Self = return Self{ value = Make(A)::make(seed + 1) }\n    fn total(value: *const(Self)) -> u64 = return 10 * Make::total(&value.value)\ninstance Make(u64)\n\n    fn make(seed: u64) -> Self = return seed\n    fn total(value: *const(Self)) -> u64 = return value.*\ninstance(type A: Make) Make(?A)\n\n    fn make(seed: u64) -> Self = return Make(A)::make(seed)\n    fn total(value: *const(Self)) -> u64\n        const inner = value.* orelse return 0\n        return Make::total(&inner)\n\nfn main()\n    const data = Make(Data)::make(1)\n    const box = Make(Box(Box(Data)))::make(1)\n    const number = Make(u64)::make(7)\n    const maybe = Make(?u64)::make(5)\n    _ = data.total() + box.total() + number.total() + maybe.total()\n" });
    try directory_two.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "typeclass Make(type T)\n\n    fn make(seed: u64) -> T\n    fn total(value: *const(T)) -> u64\nstruct Data\n    side: u64\n\n    fn init(side: u64) -> Self = return Data{ side = side }\nfn Box(type T) -> type\n    return struct\n        value: T\ninstance Make(Data)\n\n    fn make(seed: u64) -> Data = return Data::init(seed)\n    fn total(value: *const(Data)) -> u64 = return value.side\ninstance(type A: Make) Make(Box(A))\n\n    fn make(seed: u64) -> Box(A) = return Box(A){ value = Make(A)::make(seed + 1) }\n    fn total(value: *const(Box(A))) -> u64 = return 10 * Make::total(&value.value)\ninstance Make(u64)\n\n    fn make(seed: u64) -> u64 = return seed\n    fn total(value: *const(u64)) -> u64 = return value.*\ninstance(type A: Make) Make(?A)\n\n    fn make(seed: u64) -> ?A = return Make(A)::make(seed)\n    fn total(value: *const(?A)) -> u64\n        const inner = value.* orelse return 0\n        return Make::total(&inner)\n\nfn main()\n    const data = Make(Data)::make(1)\n    const box = Make(Box(Box(Data)))::make(1)\n    const number = Make(u64)::make(7)\n    const maybe = Make(?u64)::make(5)\n    _ = data.total() + box.total() + number.total() + maybe.total()\n" });
    try loader_one.loadMainModule(&arena, std.testing.io, "main");
    try loader_two.loadMainModule(&arena, std.testing.io, "main");
    var registry_one: types.Registry = .{};
    var registry_two: types.Registry = .{};
    var analyzer_one = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader_one, &registry_one);
    var analyzer_two = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader_two, &registry_two);
    var generator_one = Generator.init(try analyzer_one.analyze());
    var generator_two = Generator.init(try analyzer_two.analyze());
    const files_one = try generator_one.generateFiles(arena.allocator());
    const files_two = try generator_two.generateFiles(arena.allocator());

    try std.testing.expectEqual(files_two.len, files_one.len);
    for (files_two, files_one) |two, one| try std.testing.expectEqualStrings(two.contents, one.contents);
}

