    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "enum Token\n    Number: i32\n    End\nerror Failure\n    Failed\nfn make() -> Failure!i32 = return 1\nfn run() -> Failure!void\n    const value = try make()\n    _ = value\n    const sum = (try make()) + 1\n    _ = sum\n    const token = Token::Number{ try make() }\n    _ = token" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n\n#ifndef mn_result_main_Failure_i32_defined\n#define mn_result_main_Failure_i32_defined\ntypedef struct mn_result_main_Failure_i32 {\n    mn_main_Failure error;\n    int32_t value;\n} mn_result_main_Failure_i32;\n#endif\n\n#ifndef mn_result_main_Failure_void_defined\n#define mn_result_main_Failure_void_defined\ntypedef struct mn_result_main_Failure_void {\n    mn_main_Failure error;\n} mn_result_main_Failure_void;\n#endif\n\nmn_result_main_Failure_i32 mn_main_make() {\n    return (mn_result_main_Failure_i32){ .error.tag = 0, .value = 1 };\n}\n\nmn_result_main_Failure_void mn_main_run() {\n    mn_result_main_Failure_i32 mn_temporary_1;\n    mn_temporary_1 = mn_main_make();\n    if (mn_temporary_1.error.tag != 0) return (mn_result_main_Failure_void){ .error = mn_temporary_1.error };\n    mn_result_main_Failure_i32 mn_temporary_2;\n    mn_temporary_2 = mn_main_make();\n    if (mn_temporary_2.error.tag != 0) return (mn_result_main_Failure_void){ .error = mn_temporary_2.error };\n    mn_result_main_Failure_i32 mn_temporary_3;\n    mn_temporary_3 = mn_main_make();\n    if (mn_temporary_3.error.tag != 0) return (mn_result_main_Failure_void){ .error = mn_temporary_3.error };\n    return (mn_result_main_Failure_void){ .error.tag = 0 };\n}\n",
        files[1].contents,
    );
}

