test "generateMatch: writes a switch on the tag that binds the values of the cases" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var compiler_directory = std.testing.tmpDir(.{});
    defer compiler_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    const compiler_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &compiler_directory.sub_path },
    );
    var loader = @import("monolith").Loader.init(program_path, compiler_path);
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "enum Token\n    Number: i64\n    Flag: bool\n    End\n    Other\nerror ParseError\n    MissingEnd\n    BadDigit: u8\nerror FileError\n    MissingEnd\nfn total(token: Token) -> i64\n    match token\n        case (Number{ digits }) return digits\n        case (Flag, End) return 1\n        else return 0\nfn bump(token: *Token)\n    match token.*\n        case (Number{ *digits }) digits.* += 1\n        case (Flag{ _ }) noop\n        case (End, Other) noop\nfn sum(tokens: []const(Token)) -> i64\n    var result: i64 = 0\n    for token in tokens\n        match token\n            case (End) break\n            case (Other) continue\n            case (Number{ digits }) result += digits\n            case (Flag) noop\n    return result\nfn first(tokens: []const(Token)) -> i64\n    match tokens[0]\n        case (Number{ digits }) return digits\n        else return 0\nfn code(failure: ParseError || FileError) -> u8\n    match failure\n        case (ParseError::MissingEnd) return 1\n        case (FileError::MissingEnd) return 2\n        case (BadDigit{ digit }) return digit" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef struct mn_main_Token {\n    uint32_t tag;\n    union {\n        int64_t Number;\n        bool Flag;\n    } value;\n} mn_main_Token;\n\ntypedef struct mn_main_ParseError {\n    uint32_t tag;\n    union {\n        uint8_t BadDigit;\n    } value;\n} mn_main_ParseError;\n\ntypedef struct mn_main_FileError {\n    uint32_t tag;\n} mn_main_FileError;\n\ntypedef struct mn_slice_main_Token mn_slice_main_Token;\ntypedef struct mn_main_ParseError_or_main_FileError mn_main_ParseError_or_main_FileError;\n\nint64_t mn_main_total(mn_main_Token token);\nvoid mn_main_bump(struct mn_main_Token * token);\nint64_t mn_main_sum(mn_slice_main_Token tokens);\nint64_t mn_main_first(mn_slice_main_Token tokens);\nuint8_t mn_main_code(mn_main_ParseError_or_main_FileError failure);\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n\n#ifndef mn_slice_main_Token_defined\n#define mn_slice_main_Token_defined\ntypedef struct mn_slice_main_Token {\n    struct mn_main_Token *items;\n    size_t length;\n} mn_slice_main_Token;\n#endif\n\n#ifndef mn_main_ParseError_or_main_FileError_defined\n#define mn_main_ParseError_or_main_FileError_defined\ntypedef struct mn_main_ParseError_or_main_FileError {\n    uint32_t tag;\n    union {\n        uint8_t main_ParseError_BadDigit;\n    } value;\n} mn_main_ParseError_or_main_FileError;\n#endif\n\nint64_t mn_main_total(mn_main_Token token) {\n    switch (token.tag) {\n    case 0: {\n        const int64_t digits = token.value.Number;\n        return digits;\n    }\n    case 1:\n    case 2: {\n        return 1;\n    }\n    default: {\n        return 0;\n    }\n    }\n}\n\nvoid mn_main_bump(struct mn_main_Token * token) {\n    struct mn_main_Token * const mn_match_value_1 = &(*token);\n    switch (mn_match_value_1->tag) {\n    case 0: {\n        int64_t * const digits = &mn_match_value_1->value.Number;\n        int64_t * mn_temporary_1;\n        mn_temporary_1 = &(*digits), (*mn_temporary_1) = ((*mn_temporary_1) + 1);\n        break;\n    }\n    case 1: break;\n    default: break;\n    }\n}\n\nint64_t mn_main_sum(mn_slice_main_Token tokens) {\n    int64_t result = 0;\n    for (size_t mn_index_1 = 0; mn_index_1 < tokens.length; mn_index_1 += 1) {\n        const mn_main_Token token = tokens.items[mn_index_1];\n        switch (token.tag) {\n        case 2: {\n            goto mn_break_1;\n        }\n        case 3: {\n            goto mn_continue_1;\n        }\n        case 0: {\n            const int64_t digits = token.value.Number;\n            result = (result + digits);\n            break;\n        }\n        default: break;\n        }\n        mn_continue_1:;\n    }\n    mn_break_1:;\n    return result;\n}\n\nint64_t mn_main_first(mn_slice_main_Token tokens) {\n    const mn_main_Token mn_match_value_1 = tokens.items[0u];\n    switch (mn_match_value_1.tag) {\n    case 0: {\n        const int64_t digits = mn_match_value_1.value.Number;\n        return digits;\n    }\n    default: {\n        return 0;\n    }\n    }\n}\n\nuint8_t mn_main_code(mn_main_ParseError_or_main_FileError failure) {\n    switch (failure.tag) {\n    case 1: {\n        return 1u;\n    }\n    case 3: {\n        return 2u;\n    }\n    default: {\n        const uint8_t digit = failure.value.main_ParseError_BadDigit;\n        return digit;\n    }\n    }\n}\n",
        files[1].contents,
    );
}

