    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef struct mn_main_Failure {\n    uint32_t tag;\n} mn_main_Failure;\n\ntypedef struct mn_slice_optional_tuple_2_i64_i64 mn_slice_optional_tuple_2_i64_i64;\ntypedef struct mn_result_main_Failure_tuple_2_i64_i64 mn_result_main_Failure_tuple_2_i64_i64;\n\nvoid mn_main_bump(mn_slice_optional_tuple_2_i64_i64 pairs);\nint64_t mn_main_rest(mn_result_main_Failure_tuple_2_i64_i64 value);\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n\n#ifndef mn_slice_optional_tuple_2_i64_i64_defined\n#define mn_slice_optional_tuple_2_i64_i64_defined\ntypedef struct mn_slice_optional_tuple_2_i64_i64 {\n    struct mn_optional_tuple_2_i64_i64 *items;\n    size_t length;\n} mn_slice_optional_tuple_2_i64_i64;\n#endif\n\n#ifndef mn_tuple_2_i64_i64_defined\n#define mn_tuple_2_i64_i64_defined\ntypedef struct mn_tuple_2_i64_i64 {\n    int64_t _0;\n    int64_t _1;\n} mn_tuple_2_i64_i64;\n#endif\n\n#ifndef mn_optional_tuple_2_i64_i64_defined\n#define mn_optional_tuple_2_i64_i64_defined\ntypedef struct mn_optional_tuple_2_i64_i64 {\n    mn_tuple_2_i64_i64 value;\n    bool present;\n} mn_optional_tuple_2_i64_i64;\n#endif\n\n#ifndef mn_result_main_Failure_tuple_2_i64_i64_defined\n#define mn_result_main_Failure_tuple_2_i64_i64_defined\ntypedef struct mn_result_main_Failure_tuple_2_i64_i64 {\n    mn_main_Failure error;\n    mn_tuple_2_i64_i64 value;\n} mn_result_main_Failure_tuple_2_i64_i64;\n#endif\n\nvoid mn_main_bump(mn_slice_optional_tuple_2_i64_i64 pairs) {\n    struct mn_optional_tuple_2_i64_i64 * const mn_match_value_1 = &pairs.items[0u];\n    if (mn_match_value_1->present) {\n        const int64_t first = mn_match_value_1->value._0;\n        int64_t * const second = &mn_match_value_1->value._1;\n        int64_t * mn_temporary_1;\n        mn_temporary_1 = &(*second), (*mn_temporary_1) = ((*mn_temporary_1) + first);\n    }\n}\n\nint64_t mn_main_rest(mn_result_main_Failure_tuple_2_i64_i64 value) {\n    switch (value.error.tag) {\n    case 1: {\n        return 0;\n    }\n    default: {\n        const int64_t first = value.value._0;\n        const int64_t second = value.value._1;\n        return (first - second);\n    }\n    }\n}\n",
        files[1].contents,
    );
}

test "generateBranch: points into a constant and a zero-sized value and leaves loops with goto" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var compiler_directory = std.testing.tmpDir(.{});
    defer compiler_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    const compiler_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &compiler_directory.sub_path },
    );
    var loader = @import("monolith").Loader.init(program_path, compiler_path);
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "enum Token\n    Number: i64\n    Empty: [0]u8\n    End\nconst ORIGIN = Token::Number{ 7 }\nfn make() -> Token = return Token::End\nfn origin() -> i64\n    match ORIGIN\n        case (Number{ *digits }) return digits.*\n        else return 0\nfn kind() -> i64\n    match make()\n        case (Number) return 1\n        else return 0\nfn take(bytes: *const([0]u8)) = _ = bytes\nfn hollow(token: Token)\n    match token\n        case (Empty{ *bytes }) take(bytes)\n        else noop\nfn scan(tokens: []const(Token)) -> i64\n    var count: i64 = 0\n    while count < 10\n        for token in tokens\n            match token\n                case (End) break\n                else\n                    match make()\n                        case (Number{ digits }) count += digits\n                        else continue\n    else count = 1\n    return count" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef struct mn_main_Token {\n    uint32_t tag;\n    union {\n        int64_t Number;\n    } value;\n} mn_main_Token;\n\ntypedef struct mn_slice_main_Token mn_slice_main_Token;\n\nmn_main_Token mn_main_make();\nint64_t mn_main_origin();\nint64_t mn_main_kind();\nvoid mn_main_take(void const *);\nvoid mn_main_hollow(mn_main_Token token);\nint64_t mn_main_scan(mn_slice_main_Token tokens);\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n\n#ifndef mn_slice_main_Token_defined\n#define mn_slice_main_Token_defined\ntypedef struct mn_slice_main_Token {\n    struct mn_main_Token *items;\n    size_t length;\n} mn_slice_main_Token;\n#endif\n\nmn_main_Token mn_main_make() {\n    return (mn_main_Token){ .tag = 2 };\n}\n\nint64_t mn_main_origin() {\n    switch ((mn_main_Token){ .tag = 0, .value = { .Number = 7 } }.tag) {\n    case 0: {\n        int64_t const * const digits = &(mn_main_Token){ .tag = 0, .value = { .Number = 7 } }.value.Number;\n        return (*digits);\n    }\n    default: {\n        return 0;\n    }\n    }\n}\n\nint64_t mn_main_kind() {\n    switch (mn_main_make().tag) {\n    case 0: {\n        return 1;\n    }\n    default: {\n        return 0;\n    }\n    }\n}\n\nvoid mn_main_take(void const *) {}\n\nvoid mn_main_hollow(mn_main_Token token) {\n    switch (token.tag) {\n    case 1: {\n        void const * const bytes = ((void const *)mn_zero_sized);\n        mn_main_take(bytes);\n        break;\n    }\n    default: break;\n    }\n}\n\nint64_t mn_main_scan(mn_slice_main_Token tokens) {\n    int64_t count = 0;\n    while (count < 10) {\n        for (size_t mn_index_2 = 0; mn_index_2 < tokens.length; mn_index_2 += 1) {\n            const mn_main_Token token = tokens.items[mn_index_2];\n            switch (token.tag) {\n            case 2: {\n                goto mn_break_2;\n            }\n            default: {\n                const mn_main_Token mn_match_value_2 = mn_main_make();\n                switch (mn_match_value_2.tag) {\n                case 0: {\n                    const int64_t digits = mn_match_value_2.value.Number;\n                    count = (count + digits);\n                    break;\n                }\n                default: {\n                    goto mn_continue_2;\n                }\n                }\n            }\n            }\n            mn_continue_2:;\n        }\n        mn_break_2:;\n    }\n    count = 1;\n    return count;\n}\n",
        files[1].contents,
    );
}

