\n    result.tag = value.tag;\n    return result;\n}\n#endif\n\n#ifndef mn_main_ParseError_or_main_FileError_from_main_FileError_defined\n#define mn_main_ParseError_or_main_FileError_from_main_FileError_defined\nstatic inline mn_main_ParseError_or_main_FileError mn_main_ParseError_or_main_FileError_from_main_FileError(mn_main_FileError value) {\n    mn_main_ParseError_or_main_FileError result;\n    result.tag = value.tag;\n    return result;\n}\n#endif\n\n#ifndef mn_main_ParseError_or_main_FileError_from_never_defined\n#define mn_main_ParseError_or_main_FileError_from_never_defined\nstatic inline mn_main_ParseError_or_main_FileError mn_main_ParseError_or_main_FileError_from_never(mn_never value) {\n    mn_main_ParseError_or_main_FileError result;\n    result.tag = value.tag;\n    return result;\n}\n#endif\n\nvoid mn_runtime_error_report(char const *name);\n\nmn_result_main_ParseError_u8 mn_main_parse(bool bad) {\n    if (bad) {\n        return (mn_result_main_ParseError_u8){ .error = (mn_main_ParseError){ .tag = 1 } };\n    }\n    return (mn_result_main_ParseError_u8){ .error.tag = 0, .value = 1u };\n}\n\nmn_result_main_FileError_u8 mn_main_open(bool bad) {\n    if (bad) {\n        return (mn_result_main_FileError_u8){ .error = (mn_main_FileError){ .tag = 2 } };\n    }\n    return (mn_result_main_FileError_u8){ .error.tag = 0, .value = 2u };\n}\n\nmn_result_main_ParseError_or_main_FileError_u8 mn_main_load(bool bad) {\n    mn_result_main_ParseError_u8 mn_temporary_1;\n    uint8_t mn_temporary_2;\n    mn_result_main_FileError_u8 mn_temporary_3;\n    uint8_t mn_temporary_4;\n    mn_temporary_1 = mn_main_parse(bad);\n    if (mn_temporary_1.error.tag != 0) return (mn_result_main_ParseError_or_main_FileError_u8){ .error = mn_main_ParseError_or_main_FileError_from_main_ParseError(mn_temporary_1.error) };\n    mn_temporary_2 = mn_temporary_1.value;\n    mn_temporary_3 = mn_main_open(bad);\n    if (mn_temporary_3.error.tag != 0) return (mn_result_main_ParseError_or_main_FileError_u8){ .error = mn_main_ParseError_or_main_FileError_from_main_FileError(mn_temporary_3.error) };\n    mn_temporary_4 = mn_temporary_3.value;\n    return (mn_result_main_ParseError_or_main_FileError_u8){ .error.tag = 0, .value = ((uint8_t)(mn_temporary_2 + mn_temporary_4)) };\n}\n\nmn_result_never_u8 mn_main_quiet() {\n    return (mn_result_never_u8){ .error.tag = 0, .value = 3u };\n}\n\nmn_result_main_ParseError_or_main_FileError_void mn_main_main() {\n    mn_result_main_ParseError_or_main_FileError_u8 mn_temporary_1;\n    mn_temporary_1 = mn_main_load(false);\n    if (mn_temporary_1.error.tag != 0) return (mn_result_main_ParseError_or_main_FileError_void){ .error = mn_temporary_1.error };\n    mn_result_never_u8 mn_temporary_2;\n    mn_temporary_2 = mn_main_quiet();\n    if (mn_temporary_2.error.tag != 0) return (mn_result_main_ParseError_or_main_FileError_void){ .error = mn_main_ParseError_or_main_FileError_from_never(mn_temporary_2.error) };\n    return (mn_result_main_ParseError_or_main_FileError_void){ .error.tag = 0 };\n}\n\nint main() {\n    mn_result_main_ParseError_or_main_FileError_void result = mn_main_main();\n    if (result.error.tag == 0) return 0;\n    switch (result.error.tag) {\n    case 1: mn_runtime_error_report(\"Bad\"); break;\n    case 2: mn_runtime_error_report(\"Missing\"); break;\n    }\n    return 1;\n}\n",
