    );
    var loader = @import("monolith").Loader.init(program_path, compiler_path);
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "fn find() -> ?[i64, bool] = return null\nfn pick(value: ?[i64, bool]) -> i64\n    if value as { number, flag }\n        if (flag) return number\n    var stored = value\n    if (stored as { _, *flag }) flag.* = true\n    while find() as { number, _ }\n        return number\n    return 0" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef struct mn_optional_tuple_2_i64_bool mn_optional_tuple_2_i64_bool;\n\nmn_optional_tuple_2_i64_bool mn_main_find();\nint64_t mn_main_pick(mn_optional_tuple_2_i64_bool value);\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n\n#ifndef mn_tuple_2_i64_bool_defined\n#define mn_tuple_2_i64_bool_defined\ntypedef struct mn_tuple_2_i64_bool {\n    int64_t _0;\n    bool _1;\n} mn_tuple_2_i64_bool;\n#endif\n\n#ifndef mn_optional_tuple_2_i64_bool_defined\n#define mn_optional_tuple_2_i64_bool_defined\ntypedef struct mn_optional_tuple_2_i64_bool {\n    mn_tuple_2_i64_bool value;\n    bool present;\n} mn_optional_tuple_2_i64_bool;\n#endif\n\nmn_optional_tuple_2_i64_bool mn_main_find() {\n    return (mn_optional_tuple_2_i64_bool){ .present = false };\n}\n\nint64_t mn_main_pick(mn_optional_tuple_2_i64_bool value) {\n    if (value.present) {\n        const int64_t number = value.value._0;\n        const bool flag = value.value._1;\n        if (flag) {\n            return number;\n        }\n    }\n    mn_optional_tuple_2_i64_bool stored = value;\n    if (stored.present) {\n        bool * const flag_2 = &stored.value._1;\n        (*flag_2) = true;\n    }\n    while (true) {\n        const mn_optional_tuple_2_i64_bool mn_while_value_1 = mn_main_find();\n        if (!mn_while_value_1.present) break;\n        {\n            const int64_t number_2 = mn_while_value_1.value._0;\n            return number_2;\n        }\n    }\n    return 0;\n}\n",
        files[1].contents,
    );
}

