test "generateLiftedJump: leaves a loop from a match branch and runs the deferred statements of the loop body" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("monolith").Loader.init(program_path, program_path);
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "enum Token\n    Number: i64\n    End\nfn read(token: Token) -> ?i64\n    match token\n        case (Number{ digits }) return digits\n        else return null\nfn sum(tokens: []const(Token)) -> i64\n    var result: i64 = 0\n    for token in tokens\n        match token\n            case (End) noop\n            else\n                const digits = read(token) orelse break\n                result += digits\n        const again = read(token) orelse continue\n        result += again\n    return result\nfn count(tokens: []const(Token), log: *i64) -> i64\n    var total: i64 = 0\n    for token in tokens\n        defer log.* += 1\n        total += read(token) orelse break\n    return total" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef struct mn_main_Token {\n    uint32_t tag;\n    union {\n        int64_t Number;\n    } value;\n} mn_main_Token;\n\ntypedef struct mn_optional_i64 mn_optional_i64;\ntypedef struct mn_slice_main_Token mn_slice_main_Token;\n\nmn_optional_i64 mn_main_read(mn_main_Token token);\nint64_t mn_main_sum(mn_slice_main_Token tokens);\nint64_t mn_main_count(mn_slice_main_Token tokens, int64_t * log);\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n\n#ifndef mn_slice_main_Token_defined\n#define mn_slice_main_Token_defined\ntypedef struct mn_slice_main_Token {\n    struct mn_main_Token *items;\n    size_t length;\n} mn_slice_main_Token;\n#endif\n\n#ifndef mn_optional_i64_defined\n#define mn_optional_i64_defined\ntypedef struct mn_optional_i64 {\n    int64_t value;\n    bool present;\n} mn_optional_i64;\n#endif\n\nmn_optional_i64 mn_main_read(mn_main_Token token) {\n    switch (token.tag) {\n    case 0: {\n        const int64_t digits = token.value.Number;\n        return (mn_optional_i64){ .value = digits, .present = true };\n    }\n    default: {\n        return (mn_optional_i64){ .present = false };\n    }\n    }\n}\n\nint64_t mn_main_sum(mn_slice_main_Token tokens) {\n    int64_t result = 0;\n    for (size_t mn_index_1 = 0; mn_index_1 < tokens.length; mn_index_1 += 1) {\n        const mn_main_Token token = tokens.items[mn_index_1];\n        switch (token.tag) {\n        case 1: break;\n        default: {\n            mn_optional_i64 mn_temporary_1;\n            int64_t mn_temporary_2;\n            mn_temporary_1 = mn_main_read(token);\n            if (!(mn_temporary_1.present)) {\n                goto mn_break_1;\n            } else {\n                mn_temporary_2 = mn_temporary_1.value;\n            }\n            const int64_t digits = mn_temporary_2;\n            result = (result + digits);\n        }\n        }\n        mn_optional_i64 mn_temporary_3;\n        int64_t mn_temporary_4;\n        mn_temporary_3 = mn_main_read(token);\n        if (!(mn_temporary_3.present)) {\n            continue;\n        } else {\n            mn_temporary_4 = mn_temporary_3.value;\n        }\n        const int64_t again = mn_temporary_4;\n        result = (result + again);\n    }\n    mn_break_1:;\n    return result;\n}\n\nint64_t mn_main_count(mn_slice_main_Token tokens, int64_t * log) {\n    int64_t total = 0;\n    for (size_t mn_index_1 = 0; mn_index_1 < tokens.length; mn_index_1 += 1) {\n        const mn_main_Token token = tokens.items[mn_index_1];\n        int64_t mn_temporary_2;\n        mn_optional_i64 mn_temporary_3;\n        int64_t mn_temporary_4;\n        mn_temporary_2 = total;\n        mn_temporary_3 = mn_main_read(token);\n        if (!(mn_temporary_3.present)) {\n            {\n                int64_t * mn_temporary_1;\n                mn_temporary_1 = &(*log), (*mn_temporary_1) = ((*mn_temporary_1) + 1);\n            }\n            break;\n        } else {\n            mn_temporary_4 = mn_temporary_3.value;\n        }\n        total = (mn_temporary_2 + mn_temporary_4);\n        {\n            int64_t * mn_temporary_1;\n            mn_temporary_1 = &(*log), (*mn_temporary_1) = ((*mn_temporary_1) + 1);\n        }\n    }\n    return total;\n}\n",
        files[1].contents,
    );
}

test "generateInlinedCall: writes the body of an inline function at each call" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("monolith").Loader.init(program_path, program_path);
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nerror Failure\n    Bad\nfn next(counter: *i32) -> i32\n    counter.* += 1\n    return counter.*\nfn log(counter: *i32, amount: i32) = counter.* += amount\ninline fn double(value: i32) -> i32 = return value * 2\ninline fn quadruple(value: i32) -> i32 = return double(double(value))\ninline fn clamp(value: i32) -> i32\n    if (value > 10) return 10\n    return value\ninline fn checked(value: i32) -> Failure!i32\n    if (value < 0) return Failure::Bad\n    return value\ninline fn parse(value: i32) -> Failure!i32\n    const result = try checked(value)\n    return result + 1\ninline fn deferred(counter: *i32) -> i32\n    defer log(counter, 100)\n    return counter.*\ninline fn guarded(counter: *i32, fail: bool) -> Failure!i32\n    errdefer log(counter, 1000)\n    if (fail) return Failure::Bad\n    return 1\nstruct Box\n    value: i32\n    flag: bool = false\n\n    inline fn get(self: Self) -> i32 = return self.value\ninline fn first(type T, values: []const(T)) -> T = return values[0]\nfn run(counter: *i32) -> Failure!i32\n    const value: i32 = 3\n    const doubled = double(next(counter)) + clamp(value * 5)\n    const box = Box{ value = 7 }\n    const values: [2]u8 = { 4, 5 }\n    const total = doubled + quadruple(box.get()) + deferred(counter) + mn::convert(i32, first(u8, &values))\n    const guard = try guarded(counter, total > 100)\n    return try parse(total + guard)" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef struct mn_main_Failure {\n    uint32_t tag;\n} mn_main_Failure;\n\ntypedef struct mn_main_Box {\n    int32_t value;\n    bool flag;\n} mn_main_Box;\n\ntypedef struct mn_result_main_Failure_i32 mn_result_main_Failure_i32;\n\nint32_t mn_main_next(int32_t * counter);\nvoid mn_main_log(int32_t * counter, int32_t amount);\nmn_result_main_Failure_i32 mn_main_run(int32_t * counter);\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n\n#ifndef mn_slice_u8_defined\n#define mn_slice_u8_defined\ntypedef struct mn_slice_u8 {\n    uint8_t *items;\n    size_t length;\n} mn_slice_u8;\n#endif\n\n#ifndef mn_result_main_Failure_i32_defined\n#define mn_result_main_Failure_i32_defined\ntypedef struct mn_result_main_Failure_i32 {\n    mn_main_Failure error;\n    int32_t value;\n} mn_result_main_Failure_i32;\n#endif\n\n#ifndef mn_array_2_u8_defined\n#define mn_array_2_u8_defined\ntypedef struct mn_array_2_u8 {\n    uint8_t items[2];\n} mn_array_2_u8;\n#endif\n\nint32_t mn_main_next(int32_t * counter) {\n    int32_t * mn_temporary_1;\n    mn_temporary_1 = &(*counter), (*mn_temporary_1) = ((*mn_temporary_1) + 1);\n    return (*counter);\n}\n\nvoid mn_main_log(int32_t * counter, int32_t amount) {\n    int32_t * mn_temporary_1;\n    mn_temporary_1 = &(*counter), (*mn_temporary_1) = ((*mn_temporary_1) + amount);\n}\n\nmn_result_main_Failure_i32 mn_main_run(int32_t * counter) {\n    const int32_t value = 3;\n    int32_t mn_temporary_1;\n    int32_t mn_temporary_2;\n    int32_t mn_temporary_3;\n    mn_temporary_1 = mn_main_next(counter);\n    {\n        [[maybe_unused]] const int32_t mn_inline_1_value = mn_temporary_1;\n        mn_temporary_2 = (mn_inline_1_value * 2);\n        goto mn_inline_end_1;\n    }\n    mn_inline_end_1:;\n    {\n        [[maybe_unused]] const int32_t mn_inline_2_value = (value * 5);\n        if (mn_inline_2_value > 10) {\n            mn_temporary_3 = 10;\n            goto mn_inline_end_2;\n        }\n        mn_temporary_3 = mn_inline_2_value;\n        goto mn_inline_end_2;\n    }\n    mn_inline_end_2:;\n    const int32_t doubled = (mn_temporary_2 + mn_temporary_3);\n    const mn_main_Box box = (mn_main_Box){ .value = 7, .flag = false };\n    const mn_array_2_u8 values = (mn_array_2_u8){ .items = { 4u, 5u } };\n    int32_t mn_temporary_4;\n    int32_t mn_temporary_5;\n    int32_t mn_temporary_6;\n    uint8_t mn_temporary_7;\n    int32_t mn_temporary_8;\n    {\n        [[maybe_unused]] const mn_main_Box mn_inline_3_self = box;\n        mn_temporary_4 = mn_inline_3_self.value;\n        goto mn_inline_end_3;\n    }\n    mn_inline_end_3:;\n    {\n        [[maybe_unused]] const int32_t mn_inline_4_value = mn_temporary_4;\n        int32_t mn_temporary_13;\n        int32_t mn_temporary_14;\n        {\n            [[maybe_unused]] const int32_t mn_inline_5_value = mn_inline_4_value;\n            mn_temporary_13 = (mn_inline_5_value * 2);\n            goto mn_inline_end_5;\n        }\n        mn_inline_end_5:;\n        {\n            [[maybe_unused]] const int32_t mn_inline_6_value = mn_temporary_13;\n            mn_temporary_14 = (mn_inline_6_value * 2);\n            goto mn_inline_end_6;\n        }\n        mn_inline_end_6:;\n        mn_temporary_5 = mn_temporary_14;\n        goto mn_inline_end_4;\n    }\n    mn_inline_end_4:;\n    {\n        [[maybe_unused]] int32_t * const mn_inline_7_counter = counter;\n        const int32_t mn_returned = (*mn_inline_7_counter);\n        mn_main_log(mn_inline_7_counter, 100);\n        mn_temporary_6 = mn_returned;\n        goto mn_inline_end_7;\n    }\n    mn_inline_end_7:;\n    {\n        [[maybe_unused]] const mn_slice_u8 mn_inline_8_values = (mn_slice_u8){ .items = (uint8_t *)(&values)->items, .length = 2 };\n        mn_temporary_7 = mn_inline_8_values.items[0u];\n        goto mn_inline_end_8;\n    }\n    mn_inline_end_8:;\n    mn_temporary_8 = ((int32_t)mn_temporary_7);\n    const int32_t total = (((doubled + mn_temporary_5) + mn_temporary_6) + mn_temporary_8);\n    mn_result_main_Failure_i32 mn_temporary_9;\n    int32_t mn_temporary_10;\n    {\n        [[maybe_unused]] int32_t * const mn_inline_9_counter = counter;\n        [[maybe_unused]] const bool mn_inline_9_fail = (total > 100);\n        if (mn_inline_9_fail) {\n            const mn_result_main_Failure_i32 mn_returned = (mn_result_main_Failure_i32){ .error = (mn_main_Failure){ .tag = 1 } };\n            mn_main_log(mn_inline_9_counter, 1000);\n            mn_temporary_9 = mn_returned;\n            goto mn_inline_end_9;\n        }\n        const mn_result_main_Failure_i32 mn_returned = (mn_result_main_Failure_i32){ .error.tag = 0, .value = 1 };\n        mn_temporary_9 = mn_returned;\n        goto mn_inline_end_9;\n    }\n    mn_inline_end_9:;\n    if (mn_temporary_9.error.tag != 0) return (mn_result_main_Failure_i32){ .error = mn_temporary_9.error };\n    mn_temporary_10 = mn_temporary_9.value;\n    const int32_t guard = mn_temporary_10;\n    mn_result_main_Failure_i32 mn_temporary_11;\n    int32_t mn_temporary_12;\n    {\n        [[maybe_unused]] const int32_t mn_inline_10_value = (total + guard);\n        mn_result_main_Failure_i32 mn_temporary_13;\n        int32_t mn_temporary_14;\n        {\n            [[maybe_unused]] const int32_t mn_inline_11_value = mn_inline_10_value;\n            if (mn_inline_11_value < 0) {\n                mn_temporary_13 = (mn_result_main_Failure_i32){ .error = (mn_main_Failure){ .tag = 1 } };\n                goto mn_inline_end_11;\n            }\n            mn_temporary_13 = (mn_result_main_Failure_i32){ .error.tag = 0, .value = mn_inline_11_value };\n            goto mn_inline_end_11;\n        }\n        mn_inline_end_11:;\n        if (mn_temporary_13.error.tag != 0) {\n            mn_temporary_11 = (mn_result_main_Failure_i32){ .error = mn_temporary_13.error };\n            goto mn_inline_end_10;\n        }\n        mn_temporary_14 = mn_temporary_13.value;\n        const int32_t result = mn_temporary_14;\n        mn_temporary_11 = (mn_result_main_Failure_i32){ .error.tag = 0, .value = (result + 1) };\n        goto mn_inline_end_10;\n    }\n    mn_inline_end_10:;\n    if (mn_temporary_11.error.tag != 0) return (mn_result_main_Failure_i32){ .error = mn_temporary_11.error };\n    mn_temporary_12 = mn_temporary_11.value;\n    return (mn_result_main_Failure_i32){ .error.tag = 0, .value = mn_temporary_12 };\n}\n",
        files[1].contents,
    );
}

test "generateInlinedCall: writes the body in a loop condition and on the right of a short-circuit operator" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("monolith").Loader.init(program_path, program_path);
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "inline fn positive(value: i32) -> bool = return value > 0\nfn count(start: i32, flag: bool) -> i32\n    var current = start\n    while (positive(current)) current -= 1\n    if (flag and positive(start)) return 1\n    return current" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
