    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::iterator::Zip\nfn sum(cards: []u32) -> u32\n    var total: u32 = 0\n    for { card, index } in Zip::zip({ cards, 0.. })\n        total += card * mn::convert(u32, index)\n    return total\nfn constant(cards: []const(u32)) -> u32\n    var total: u32 = 0\n    for { card, index } in Zip::zip({ cards, 0.. })\n        total += card * mn::convert(u32, index)\n    return total" });
