    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\n\nstruct Marker\n\nerror Error\n    Failed\n\nfn attempt(counter: *i32) -> Error!*many(Marker)\n    counter.* += 1\n    return mn::cast(*many(Marker), counter)\n\nfn identity(counter: *i32, pointer: *many(Marker)) -> *many(Marker)\n    counter.* += 100\n    return pointer\n\nfn part(counter: *i32, count: usize) -> Error![]Marker\n    return identity(counter, try attempt(counter))[0..count]\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n\n#ifndef mn_slice_main_Marker_defined\n#define mn_slice_main_Marker_defined\ntypedef struct mn_slice_main_Marker {\n    void *items;\n    size_t length;\n} mn_slice_main_Marker;\n#endif\n\n#ifndef mn_result_main_Error_pointer_many_main_Marker_defined\n#define mn_result_main_Error_pointer_many_main_Marker_defined\ntypedef struct mn_result_main_Error_pointer_many_main_Marker {\n    mn_main_Error error;\n    void * value;\n} mn_result_main_Error_pointer_many_main_Marker;\n#endif\n\n#ifndef mn_result_main_Error_slice_main_Marker_defined\n#define mn_result_main_Error_slice_main_Marker_defined\ntypedef struct mn_result_main_Error_slice_main_Marker {\n    mn_main_Error error;\n    mn_slice_main_Marker value;\n} mn_result_main_Error_slice_main_Marker;\n#endif\n\nmn_result_main_Error_pointer_many_main_Marker mn_main_attempt(int32_t * counter) {\n    int32_t * mn_temporary_1;\n    mn_temporary_1 = &(*counter), (*mn_temporary_1) = ((*mn_temporary_1) + 1);\n    return (mn_result_main_Error_pointer_many_main_Marker){ .error.tag = 0, .value = ((void *)counter) };\n}\n\nvoid * mn_main_identity(int32_t * counter, void * pointer) {\n    int32_t * mn_temporary_1;\n    mn_temporary_1 = &(*counter), (*mn_temporary_1) = ((*mn_temporary_1) + 100);\n    return pointer;\n}\n\nmn_result_main_Error_slice_main_Marker mn_main_part(int32_t * counter, size_t count) {\n    mn_result_main_Error_pointer_many_main_Marker mn_temporary_1;\n    void * mn_temporary_2;\n    mn_temporary_1 = mn_main_attempt(counter);\n    if (mn_temporary_1.error.tag != 0) return (mn_result_main_Error_slice_main_Marker){ .error = mn_temporary_1.error };\n    mn_temporary_2 = mn_temporary_1.value;\n    mn_main_identity(counter, mn_temporary_2);\n    return (mn_result_main_Error_slice_main_Marker){ .error.tag = 0, .value = (mn_slice_main_Marker){ .length = count - 0u } };\n}\n",
        files[1].contents,
    );
}

