test "generateBuiltinCall: writes sizes and alignments as constants and conversions as casts" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var compiler_directory = std.testing.tmpDir(.{});
    defer compiler_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    const compiler_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &compiler_directory.sub_path },
    );
    var loader = @import("monolith").Loader.init(program_path, compiler_path);
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::reflection\nstruct Pair\n    small: u8\n    large: i32\nenum Token\n    Number: i64\n    End\nerror Failure\n    Bad: u8\nfn size() -> usize = return mn::size(Pair)\nfn alignment() -> usize = return mn::alignment(Pair)\nfn token() -> usize = return mn::size(Token)\nfn maybe() -> usize = return mn::size(?i32)\nfn text() -> usize = return mn::size([]const(u8))\nfn result() -> usize = return mn::size(Failure!u16)\nfn whole(value: f64) -> i32 = return mn::convert(i32, value)\nfn low(value: i32) -> u8 = return mn::truncate(u8, value)\nfn wide(value: u8) -> u64 = return value\nfn float(value: f32) -> f64 = return value\nfn count() -> usize = return mn::reflection::length([u8, bool])\nfn pairs() -> [i32, bool]\n    const number: i32 = 4\n    return { number, true }\nfn use(pair: Pair, token: Token, failure: Failure!u16) -> usize\n    _ = pair\n    _ = token\n    _ = failure\n    return 0" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef struct mn_main_Token {\n    uint32_t tag;\n    union {\n        int64_t Number;\n    } value;\n} mn_main_Token;\n\ntypedef struct mn_main_Failure {\n    uint32_t tag;\n    union {\n        uint8_t Bad;\n    } value;\n} mn_main_Failure;\n\ntypedef struct mn_main_Pair {\n    uint8_t small;\n    int32_t large;\n} mn_main_Pair;\n\ntypedef struct mn_tuple_2_i32_bool mn_tuple_2_i32_bool;\ntypedef struct mn_result_main_Failure_u16 mn_result_main_Failure_u16;\n\nsize_t mn_main_size();\nsize_t mn_main_alignment();\nsize_t mn_main_token();\nsize_t mn_main_maybe();\nsize_t mn_main_text();\nsize_t mn_main_result();\nint32_t mn_main_whole(double value);\nuint8_t mn_main_low(int32_t value);\nuint64_t mn_main_wide(uint8_t value);\ndouble mn_main_float(float value);\nsize_t mn_main_count();\nmn_tuple_2_i32_bool mn_main_pairs();\nsize_t mn_main_use(mn_main_Pair, mn_main_Token, mn_result_main_Failure_u16);\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n\n#ifndef mn_tuple_2_i32_bool_defined\n#define mn_tuple_2_i32_bool_defined\ntypedef struct mn_tuple_2_i32_bool {\n    int32_t _0;\n    bool _1;\n} mn_tuple_2_i32_bool;\n#endif\n\n#ifndef mn_result_main_Failure_u16_defined\n#define mn_result_main_Failure_u16_defined\ntypedef struct mn_result_main_Failure_u16 {\n    mn_main_Failure error;\n    uint16_t value;\n} mn_result_main_Failure_u16;\n#endif\n\nsize_t mn_main_size() {\n    return 8u;\n}\n\nsize_t mn_main_alignment() {\n    return 4u;\n}\n\nsize_t mn_main_token() {\n    return 16u;\n}\n\nsize_t mn_main_maybe() {\n    return 8u;\n}\n\nsize_t mn_main_text() {\n    return 16u;\n}\n\nsize_t mn_main_result() {\n    return 12u;\n}\n\nint32_t mn_main_whole(double value) {\n    return ((int32_t)value);\n}\n\nuint8_t mn_main_low(int32_t value) {\n    return ((uint8_t)value);\n}\n\nuint64_t mn_main_wide(uint8_t value) {\n    return value;\n}\n\ndouble mn_main_float(float value) {\n    return value;\n}\n\nsize_t mn_main_count() {\n    return 2u;\n}\n\nmn_tuple_2_i32_bool mn_main_pairs() {\n    const int32_t number = 4;\n    return (mn_tuple_2_i32_bool){ ._0 = number, ._1 = true };\n}\n\nsize_t mn_main_use(mn_main_Pair, mn_main_Token, mn_result_main_Failure_u16) {\n    return 0u;\n}\n",
        files[1].contents,
    );
}

test "generateBuiltinCall: casts pointers and aligns a multiple value pointer through the runtime" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    var compiler_directory = std.testing.tmpDir(.{});
    defer compiler_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    const compiler_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &compiler_directory.sub_path },
    );
    var loader = @import("monolith").Loader.init(program_path, compiler_path);
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nexternal struct Header\n    size: u32\n    flags: [2]u8\nfn read(buffer: []const(u8)) -> *const(Header) = return mn::cast(*const(Header), buffer.pointer)\nfn next(buffer: []u8, alignment: usize) -> *many(u8) = return mn::align(buffer.pointer, alignment)\nfn count(buffer: *[]u8) -> usize = return buffer.length\nexternal fn keep(pointer: *const(void))\nfn hide(header: *Header)\n    keep(header)\n    keep(mn::cast(*many(const(u8)), header))" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\n#ifndef mn_array_2_u8_defined\n#define mn_array_2_u8_defined\ntypedef struct mn_array_2_u8 {\n    uint8_t items[2];\n} mn_array_2_u8;\n#endif\n\ntypedef struct mn_main_Header {\n    uint32_t size;\n    mn_array_2_u8 flags;\n} mn_main_Header;\n\ntypedef struct mn_slice_u8 mn_slice_u8;\n\nvoid keep(void const * pointer);\n\nstruct mn_main_Header const * mn_main_read(mn_slice_u8 buffer);\nuint8_t * mn_main_next(mn_slice_u8 buffer, size_t alignment);\nsize_t mn_main_count(struct mn_slice_u8 * buffer);\nvoid mn_main_hide(struct mn_main_Header * header);\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n\n#ifndef mn_slice_u8_defined\n#define mn_slice_u8_defined\ntypedef struct mn_slice_u8 {\n    uint8_t *items;\n    size_t length;\n} mn_slice_u8;\n#endif\n\nstruct mn_main_Header const * mn_main_read(mn_slice_u8 buffer) {\n    return ((struct mn_main_Header const *)buffer.items);\n}\n\nuint8_t * mn_main_next(mn_slice_u8 buffer, size_t alignment) {\n    return ((uint8_t *)mn_align_address((uintptr_t)buffer.items, alignment));\n}\n\nsize_t mn_main_count(struct mn_slice_u8 * buffer) {\n    return buffer->length;\n}\n\nvoid mn_main_hide(struct mn_main_Header * header) {\n    keep(header);\n    keep(((uint8_t const *)header));\n}\n",
        files[1].contents,
    );
}

