test "generateFunction: allocates through mn::memory with Heap, Arena and ArrayList" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container\nimport mn::convert::View\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nstruct Card\n    value: i64\n    wide: u128\nfn run() -> memory::Error!i64\n    var heap = memory::Heap::init()\n    const own cards = try heap.allocate(Card, 4)\n    defer heap.free(own cards)\n    cards[0] = Card{ value = 1, wide = 2 }\n    const own card = try heap.create(Card)\n    defer heap.destroy(own card)\n    card.* = cards[0]\n    var own arena = memory::Arena(memory::Heap)::init(heap)\n    defer arena.deinit(own)\n    const own bytes = try arena.allocate(u8, 100)\n    defer arena.free(own bytes)\n    const own more = try arena.allocate(Card, 300)\n    defer arena.free(own more)\n    var own list = mn::container::ArrayList(i64)::init()\n    defer list.deinit(own) with &heap\n    for (index in 0..20) try list.append(mn::convert(i64, index)) with &heap\n    var own arena_list = mn::container::ArrayList(Card)::init()\n    defer arena_list.deinit(own) with &arena\n    try arena_list.append(card.*) with &arena\n    return list.view([]const(i64))[19] + mn::convert(i64, bytes.length) + arena_list.view([]const(Card))[0].value\nfn main()\n    _ = run() catch 0" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());
    try std.testing.expectEqual(18, files.len);
    try std.testing.expectEqualStrings("main.h", files[0].path);
    try std.testing.expectEqualStrings("main.c", files[1].path);
    try std.testing.expectEqualStrings("mn/container.h", files[2].path);
    try std.testing.expectEqualStrings("mn/container.c", files[3].path);
    try std.testing.expectEqualStrings("mn/convert.h", files[4].path);
    try std.testing.expectEqualStrings("mn/memory.h", files[5].path);
    try std.testing.expectEqualStrings("mn/memory.c", files[6].path);
    try std.testing.expectEqualStrings("mn/compare.h", files[9].path);
    try std.testing.expectEqualStrings("mn/compare.c", files[10].path);
    try std.testing.expectEqualStrings("mn/hash.h", files[11].path);
    try std.testing.expectEqualStrings("mn/hash.c", files[12].path);
    try std.testing.expectEqualStrings("mn/iterator.h", files[13].path);
    try std.testing.expectEqualStrings("mn/iterator.c", files[14].path);
    try std.testing.expectEqualStrings("mn/reflection.h", files[17].path);
    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef struct mn_main_Card {\n    int64_t value;\n    uint128_t wide;\n} mn_main_Card;\n\ntypedef struct mn_result_mn_memory_Error_i64 mn_result_mn_memory_Error_i64;\n\nmn_result_mn_memory_Error_i64 mn_main_run();\n",
        files[0].contents,
