test "generateWrapping: computes in the unsigned type of the operands and converts back" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("monolith").Loader.init(program_path, program_path);
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::math\nfn add_u8(value: u8) -> u8 = return math::add_wrapping(value, 1)\nfn subtract_i8(value: i8) -> i8 = return math::subtract_wrapping(value, 1)\nfn multiply_u16(one: u16, two: u16) -> u16 = return math::multiply_wrapping(one, two)\nfn add_u64(value: u64) -> u64 = return math::add_wrapping(value, 1)\nfn multiply_i64(one: i64, two: i64) -> i64 = return math::multiply_wrapping(one, two)\nfn next() -> i32 = return 7\nfn ignore(value: i32) = _ = math::add_wrapping(value, next())" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\nuint8_t mn_main_add_u8(uint8_t value);\nint8_t mn_main_subtract_i8(int8_t value);\nuint16_t mn_main_multiply_u16(uint16_t one, uint16_t two);\nuint64_t mn_main_add_u64(uint64_t value);\nint64_t mn_main_multiply_i64(int64_t one, int64_t two);\nint32_t mn_main_next();\nvoid mn_main_ignore(int32_t value);\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n\nuint8_t mn_main_add_u8(uint8_t value) {\n    return ((uint8_t)(1u * (uint8_t)(value) + (uint8_t)(1u)));\n}\n\nint8_t mn_main_subtract_i8(int8_t value) {\n    return ((int8_t)(uint8_t)(1u * (uint8_t)(value) - (uint8_t)(1)));\n}\n\nuint16_t mn_main_multiply_u16(uint16_t one, uint16_t two) {\n    return ((uint16_t)(1u * (uint16_t)(one) * (uint16_t)(two)));\n}\n\nuint64_t mn_main_add_u64(uint64_t value) {\n    return ((uint64_t)(1u * (uint64_t)(value) + (uint64_t)(1u)));\n}\n\nint64_t mn_main_multiply_i64(int64_t one, int64_t two) {\n    return ((int64_t)(uint64_t)(1u * (uint64_t)(one) * (uint64_t)(two)));\n}\n\nint32_t mn_main_next() {\n    return 7;\n}\n\nvoid mn_main_ignore(int32_t value) {\n    (void)(((int32_t)(uint32_t)(1u * (uint32_t)(value) + (uint32_t)(mn_main_next()))));\n}\n",
        files[1].contents,
    );
}

test "generateFunction: generates mn::random with its generator, range and entropy" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::random\nimport mn::random::Generator\nfn roll(generator: *random::Xoshiro256) -> usize = return generator.range(1..7)\nfn main()\n    var generator = random::Xoshiro256::init(random::entropy())\n    _ = roll(&generator)\n    _ = Generator::next(&generator)" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqualStrings("main.h", files[0].path);
    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef struct mn_mn_random_Xoshiro256 mn_mn_random_Xoshiro256;\n\nsize_t mn_main_roll(struct mn_mn_random_Xoshiro256 * generator);\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings("main.c", files[1].path);
    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n#include \"mn/random.h\"\n#include \"mn/range.h\"\n\n#ifndef mn_optional_usize_defined\n#define mn_optional_usize_defined\ntypedef struct mn_optional_usize {\n    size_t value;\n    bool present;\n} mn_optional_usize;\n#endif\n\nsize_t mn_main_roll(struct mn_mn_random_Xoshiro256 * generator) {\n    return mn_mn_random_Xoshiro256_Generator_range(generator, (mn_mn_range_Range){ .start = 1u, .end = (mn_optional_usize){ .value = 7u, .present = true } });\n}\n\nint main() {\n    mn_mn_random_Xoshiro256 generator = mn_mn_random_Xoshiro256_init(mn_runtime_random_entropy());\n    mn_main_roll(&generator);\n    mn_mn_random_Xoshiro256_Generator_next(&generator);\n}\n",
        files[1].contents,
    );
    try std.testing.expectEqualStrings("mn/random.h", files[2].path);
    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"../runtime/monolith.h\"\n\n#ifndef mn_array_4_u64_defined\n#define mn_array_4_u64_defined\ntypedef struct mn_array_4_u64 {\n    uint64_t items[4];\n} mn_array_4_u64;\n#endif\n\ntypedef struct mn_mn_random_Xoshiro256 {\n    mn_array_4_u64 state;\n} mn_mn_random_Xoshiro256;\n\ntypedef struct mn_mn_range_Range mn_mn_range_Range;\n\nuint64_t mn_runtime_random_entropy();\n\nmn_mn_random_Xoshiro256 mn_mn_random_Xoshiro256_init(uint64_t seed);\nuint64_t mn_mn_random_Xoshiro256_Generator_next(struct mn_mn_random_Xoshiro256 * generator);\nuint64_t mn_mn_random_draw_seed_word(uint64_t * state);\nsize_t mn_mn_random_Xoshiro256_Generator_range(struct mn_mn_random_Xoshiro256 * generator, mn_mn_range_Range range);\n",
        files[2].contents,
    );
    try std.testing.expectEqualStrings("mn/random.c", files[3].path);
    try std.testing.expectEqualStrings(
        "#include \"random.h\"\n#include \"hash.h\"\n#include \"range.h\"\n\n#ifndef mn_optional_usize_defined\n#define mn_optional_usize_defined\ntypedef struct mn_optional_usize {\n    size_t value;\n    bool present;\n} mn_optional_usize;\n#endif\n\nmn_mn_random_Xoshiro256 mn_mn_random_Xoshiro256_init(uint64_t seed) {\n    uint64_t mixer = seed;\n    uint64_t mn_temporary_1;\n    uint64_t mn_temporary_2;\n    uint64_t mn_temporary_3;\n    uint64_t mn_temporary_4;\n    return (mn_temporary_1 = mn_mn_random_draw_seed_word(&mixer), mn_temporary_2 = mn_mn_random_draw_seed_word(&mixer), mn_temporary_3 = mn_mn_random_draw_seed_word(&mixer), mn_temporary_4 = mn_mn_random_draw_seed_word(&mixer), (mn_mn_random_Xoshiro256){ .state = (mn_array_4_u64){ .items = { mn_temporary_1, mn_temporary_2, mn_temporary_3, mn_temporary_4 } } });\n}\n\nuint64_t mn_mn_random_Xoshiro256_Generator_next(struct mn_mn_random_Xoshiro256 * generator) {\n    struct mn_array_4_u64 * const state = &generator->state;\n    const uint64_t scaled = ((uint64_t)(1u * (uint64_t)(state->items[1u]) * (uint64_t)(5u)));\n    const uint64_t result = ((uint64_t)(1u * (uint64_t)((mn_shift_left_u64(scaled, 7u) | mn_shift_right_u64(scaled, 57u))) * (uint64_t)(9u)));\n    const uint64_t shifted = mn_shift_left_u64(state->items[1u], 17u);\n    uint64_t * mn_temporary_1;\n    mn_temporary_1 = &state->items[2u], (*mn_temporary_1) = ((*mn_temporary_1) ^ state->items[0u]);\n    uint64_t * mn_temporary_2;\n    mn_temporary_2 = &state->items[3u], (*mn_temporary_2) = ((*mn_temporary_2) ^ state->items[1u]);\n    uint64_t * mn_temporary_3;\n    mn_temporary_3 = &state->items[1u], (*mn_temporary_3) = ((*mn_temporary_3) ^ state->items[2u]);\n    uint64_t * mn_temporary_4;\n    mn_temporary_4 = &state->items[0u], (*mn_temporary_4) = ((*mn_temporary_4) ^ state->items[3u]);\n    uint64_t * mn_temporary_5;\n    mn_temporary_5 = &state->items[2u], (*mn_temporary_5) = ((*mn_temporary_5) ^ shifted);\n    state->items[3u] = (mn_shift_left_u64(state->items[3u], 45u) | mn_shift_right_u64(state->items[3u], 19u));\n    return result;\n}\n\nuint64_t mn_mn_random_draw_seed_word(uint64_t * state) {\n    const uint64_t word = mn_mn_hash_splitmix64((*state));\n    (*state) = ((uint64_t)(1u * (uint64_t)((*state)) + (uint64_t)(0x9e3779b97f4a7c15u)));\n    return word;\n}\n\nsize_t mn_mn_random_Xoshiro256_Generator_range(struct mn_mn_random_Xoshiro256 * generator, mn_mn_range_Range range) {\n    const uint64_t count = ((uint64_t)(range.end.value - range.start));\n    const uint64_t threshold = (((uint64_t)(1u * (uint64_t)(0u) - (uint64_t)(count))) % count);\n    while (true) {\n        const uint64_t bits = mn_mn_random_Xoshiro256_Generator_next(generator);\n        if (bits >= threshold) {\n            return (range.start + ((size_t)(bits % count)));\n        }\n    }\n}\n",
        files[3].contents,
    );
