        "#include \"stream.h\"\n#include \"iterator.h\"\n#include \"memory.h\"\n\n#ifndef mn_slice_u8_defined\n#define mn_slice_u8_defined\ntypedef struct mn_slice_u8 {\n    uint8_t *items;\n    size_t length;\n} mn_slice_u8;\n#endif\n\n#ifndef mn_never_defined\n#define mn_never_defined\ntypedef struct mn_never {\n    uint32_t tag;\n} mn_never;\n#endif\n\n#ifndef mn_result_never_usize_defined\n#define mn_result_never_usize_defined\ntypedef struct mn_result_never_usize {\n    mn_never error;\n    size_t value;\n} mn_result_never_usize;\n#endif\n\nmn_result_never_usize mn_mn_stream_mn_iterator_SliceIterator_2_Reader_read(struct mn_slice_u8 * source, mn_slice_u8 buffer) {\n    size_t count = (*source).length;\n    if (buffer.length < count) {\n        count = buffer.length;\n    }\n    mn_mn_memory_copy_1((mn_slice_u8){ .items = buffer.items, .length = count }, (mn_slice_u8){ .items = (*source).items, .length = count });\n    (*source) = (mn_slice_u8){ .items = (*source).items + count, .length = (*source).length - count };\n    return (mn_result_never_usize){ .error.tag = 0, .value = count };\n}\n\nmn_result_never_usize mn_mn_stream_mn_iterator_SliceIterator_1_Reader_read(struct mn_slice_u8 * source, mn_slice_u8 buffer) {\n    size_t count = (*source).length;\n    if (buffer.length < count) {\n        count = buffer.length;\n    }\n    mn_mn_memory_copy_1((mn_slice_u8){ .items = buffer.items, .length = count }, (mn_slice_u8){ .items = (*source).items, .length = count });\n    (*source) = (mn_slice_u8){ .items = (*source).items + count, .length = (*source).length - count };\n    return (mn_result_never_usize){ .error.tag = 0, .value = count };\n}\n",
        files[15].contents,
    );
    try std.testing.expectEqualStrings("mn/reflection.h", files[16].path);
    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"../runtime/monolith.h\"\n",
        files[16].contents,
    );
    try std.testing.expectEqual(17, files.len);
    try std.testing.expectEqual(2, generator.runtime_functions.items.len);
    try std.testing.expectEqualStrings("mn_runtime_random_entropy", generator.runtime_functions.items[0]);
    try std.testing.expectEqualStrings("mn_runtime_memory_copy", generator.runtime_functions.items[1]);
}

test "generateFunction: gives functions that call each other the error sets inferred for them together" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "error FileError\n    Missing\nfn first(n: u8) -> !u8\n    if (n == 0) return 0\n    const value = try second(n - 1)\n    if (value == 7) return FileError::Missing\n    return value\nfn second(n: u8) -> !u8 = try first(n)\nfn main -> !void\n    _ = try first(3)" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqualStrings("main.h", files[0].path);
    try std.testing.expectEqualStrings("main.c", files[1].path);
    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef struct mn_main_FileError {\n    uint32_t tag;\n} mn_main_FileError;\n\ntypedef struct mn_result_main_FileError_u8 mn_result_main_FileError_u8;\ntypedef struct mn_result_main_FileError_void mn_result_main_FileError_void;\n\nmn_result_main_FileError_u8 mn_main_first(uint8_t n);\nmn_result_main_FileError_u8 mn_main_second(uint8_t n);\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n\n#ifndef mn_result_main_FileError_u8_defined\n#define mn_result_main_FileError_u8_defined\ntypedef struct mn_result_main_FileError_u8 {\n    mn_main_FileError error;\n    uint8_t value;\n} mn_result_main_FileError_u8;\n#endif\n\n#ifndef mn_result_main_FileError_void_defined\n#define mn_result_main_FileError_void_defined\ntypedef struct mn_result_main_FileError_void {\n    mn_main_FileError error;\n} mn_result_main_FileError_void;\n#endif\n\nvoid mn_runtime_error_report(char const *name);\n\nmn_result_main_FileError_u8 mn_main_first(uint8_t n) {\n    if (n == 0u) {\n        return (mn_result_main_FileError_u8){ .error.tag = 0, .value = 0u };\n    }\n    mn_result_main_FileError_u8 mn_temporary_1;\n    uint8_t mn_temporary_2;\n    mn_temporary_1 = mn_main_second(((uint8_t)(n - 1u)));\n    if (mn_temporary_1.error.tag != 0) return (mn_result_main_FileError_u8){ .error = mn_temporary_1.error };\n    mn_temporary_2 = mn_temporary_1.value;\n    const uint8_t value = mn_temporary_2;\n    if (value == 7u) {\n        return (mn_result_main_FileError_u8){ .error = (mn_main_FileError){ .tag = 1 } };\n    }\n    return (mn_result_main_FileError_u8){ .error.tag = 0, .value = value };\n}\n\nmn_result_main_FileError_u8 mn_main_second(uint8_t n) {\n    mn_result_main_FileError_u8 mn_temporary_1;\n    uint8_t mn_temporary_2;\n    mn_temporary_1 = mn_main_first(n);\n    if (mn_temporary_1.error.tag != 0) return (mn_result_main_FileError_u8){ .error = mn_temporary_1.error };\n    mn_temporary_2 = mn_temporary_1.value;\n    return (mn_result_main_FileError_u8){ .error.tag = 0, .value = mn_temporary_2 };\n}\n\nmn_result_main_FileError_void mn_main_main() {\n    mn_result_main_FileError_u8 mn_temporary_1;\n    mn_temporary_1 = mn_main_first(3u);\n    if (mn_temporary_1.error.tag != 0) return (mn_result_main_FileError_void){ .error = mn_temporary_1.error };\n    return (mn_result_main_FileError_void){ .error.tag = 0 };\n}\n\nint main() {\n    mn_result_main_FileError_void result = mn_main_main();\n    if (result.error.tag == 0) return 0;\n    switch (result.error.tag) {\n    case 1: mn_runtime_error_report(\"Missing\"); break;\n    }\n    return 1;\n}\n",
        files[1].contents,
    );
}

test "generateFunction: generates a generic function that calls itself with an inferred error set and an array as long as a constant" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
