    );
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\ntypeclass Sized(type T)\n\n    fn size(value: T) -> usize\nstruct Data\ninstance Sized(Data)\n\n    fn size(_: Data) -> usize = 4\nerror Failure\n    Empty\nconst LENGTH: usize = 8\nfn count(value: Sized, depth: usize) -> !usize\n    var buffer: [LENGTH]u8 = undefined\n    buffer[0] = 1\n    if (depth == 0) return Failure::Empty\n    return try count(value, depth - 1) + Sized::size(value) + mn::convert(usize, buffer[0])\nfn main -> !void\n    _ = try count(Data{}, 2)" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqualStrings("main.h", files[0].path);
    try std.testing.expectEqualStrings("main.c", files[1].path);
    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef struct mn_main_Failure {\n    uint32_t tag;\n} mn_main_Failure;\n\ntypedef struct mn_result_main_Failure_void mn_result_main_Failure_void;\ntypedef struct mn_result_main_Failure_usize mn_result_main_Failure_usize;\n\nsize_t mn_main_Data_Sized_size();\nmn_result_main_Failure_usize mn_main_count_2(size_t depth);\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n\n#ifndef mn_result_main_Failure_void_defined\n#define mn_result_main_Failure_void_defined\ntypedef struct mn_result_main_Failure_void {\n    mn_main_Failure error;\n} mn_result_main_Failure_void;\n#endif\n\n#ifndef mn_result_main_Failure_usize_defined\n#define mn_result_main_Failure_usize_defined\ntypedef struct mn_result_main_Failure_usize {\n    mn_main_Failure error;\n    size_t value;\n} mn_result_main_Failure_usize;\n#endif\n\n#ifndef mn_array_8_u8_defined\n#define mn_array_8_u8_defined\ntypedef struct mn_array_8_u8 {\n    uint8_t items[8];\n} mn_array_8_u8;\n#endif\n\nvoid mn_runtime_error_report(char const *name);\n\nsize_t mn_main_Data_Sized_size() {\n    return 4u;\n}\n\nmn_result_main_Failure_void mn_main_main() {\n    mn_result_main_Failure_usize mn_temporary_1;\n    mn_temporary_1 = mn_main_count_2(2u);\n    if (mn_temporary_1.error.tag != 0) return (mn_result_main_Failure_void){ .error = mn_temporary_1.error };\n    return (mn_result_main_Failure_void){ .error.tag = 0 };\n}\n\nint main() {\n    mn_result_main_Failure_void result = mn_main_main();\n    if (result.error.tag == 0) return 0;\n    switch (result.error.tag) {\n    case 1: mn_runtime_error_report(\"Empty\"); break;\n    }\n    return 1;\n}\n\nmn_result_main_Failure_usize mn_main_count_2(size_t depth) {\n    mn_array_8_u8 buffer;\n    buffer.items[0u] = 1u;\n    if (depth == 0u) {\n        return (mn_result_main_Failure_usize){ .error = (mn_main_Failure){ .tag = 1 } };\n    }\n    mn_result_main_Failure_usize mn_temporary_1;\n    size_t mn_temporary_2;\n    size_t mn_temporary_3;\n    size_t mn_temporary_4;\n    mn_temporary_1 = mn_main_count_2((depth - 1u));\n    if (mn_temporary_1.error.tag != 0) return (mn_result_main_Failure_usize){ .error = mn_temporary_1.error };\n    mn_temporary_2 = mn_temporary_1.value;\n    mn_temporary_3 = mn_main_Data_Sized_size();\n    mn_temporary_4 = ((size_t)buffer.items[0u]);\n    return (mn_result_main_Failure_usize){ .error.tag = 0, .value = ((mn_temporary_2 + mn_temporary_3) + mn_temporary_4) };\n}\n",
        files[1].contents,
    );
}

