test "generateFunctionCall: passes a pointer to the allocator only to the functions that need it" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nfn plain(value: usize) -> usize = value + 1\nfn take(count: usize) -> memory::Error!usize\n    with allocator\n    const own items = try allocator.allocate(u8, plain(count))\n    defer allocator.free(own items)\n    return items.length\nfn middle(count: usize) -> memory::Error!usize = take(count)\nfn main -> !void\n    var heap = memory::Heap::init()\n    var own arena = memory::Arena(memory::Heap)::init(heap)\n    defer arena.deinit(own)\n    _ = try middle(1) with &heap\n    _ = try middle(2) with &arena\n    _ = plain(3)\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqualStrings("main.h", files[0].path);
    try std.testing.expectEqualStrings("main.c", files[1].path);
    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef struct mn_result_mn_memory_Error_void mn_result_mn_memory_Error_void;\ntypedef struct mn_result_mn_memory_Error_usize mn_result_mn_memory_Error_usize;\ntypedef struct mn_mn_memory_Arena_1 mn_mn_memory_Arena_1;\n\nsize_t mn_main_plain(size_t value);\nmn_result_mn_memory_Error_usize mn_main_middle_1(size_t count, [[maybe_unused]] void * mn_allocator);\nmn_result_mn_memory_Error_usize mn_main_middle_2(size_t count, [[maybe_unused]] struct mn_mn_memory_Arena_1 * mn_allocator);\nmn_result_mn_memory_Error_usize mn_main_take_1(size_t count, [[maybe_unused]] void * mn_allocator);\nmn_result_mn_memory_Error_usize mn_main_take_2(size_t count, [[maybe_unused]] struct mn_mn_memory_Arena_1 * mn_allocator);\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n#include \"mn/memory.h\"\n\n#ifndef mn_slice_u8_defined\n#define mn_slice_u8_defined\ntypedef struct mn_slice_u8 {\n    uint8_t *items;\n    size_t length;\n} mn_slice_u8;\n#endif\n\n#ifndef mn_result_mn_memory_Error_void_defined\n#define mn_result_mn_memory_Error_void_defined\ntypedef struct mn_result_mn_memory_Error_void {\n    mn_mn_memory_Error error;\n} mn_result_mn_memory_Error_void;\n#endif\n\n#ifndef mn_result_mn_memory_Error_usize_defined\n#define mn_result_mn_memory_Error_usize_defined\ntypedef struct mn_result_mn_memory_Error_usize {\n    mn_mn_memory_Error error;\n    size_t value;\n} mn_result_mn_memory_Error_usize;\n#endif\n\n#ifndef mn_result_mn_memory_Error_slice_u8_defined\n#define mn_result_mn_memory_Error_slice_u8_defined\ntypedef struct mn_result_mn_memory_Error_slice_u8 {\n    mn_mn_memory_Error error;\n    mn_slice_u8 value;\n} mn_result_mn_memory_Error_slice_u8;\n#endif\n\nvoid mn_runtime_error_report(char const *name);\n\nsize_t mn_main_plain(size_t value) {\n    return (value + 1u);\n}\n\nmn_result_mn_memory_Error_void mn_main_main() {\n    mn_mn_memory_Heap_init();\n    mn_mn_memory_Arena_1 arena = mn_mn_memory_Arena_1_init();\n    mn_result_mn_memory_Error_usize mn_temporary_1;\n    mn_temporary_1 = mn_main_middle_1(1u, ((void *)mn_zero_sized));\n    if (mn_temporary_1.error.tag != 0) {\n        mn_mn_memory_Arena_1_Deinit_deinit(&arena);\n        return (mn_result_mn_memory_Error_void){ .error = mn_temporary_1.error };\n    }\n    mn_result_mn_memory_Error_usize mn_temporary_2;\n    mn_temporary_2 = mn_main_middle_2(2u, &arena);\n    if (mn_temporary_2.error.tag != 0) {\n        mn_mn_memory_Arena_1_Deinit_deinit(&arena);\n        return (mn_result_mn_memory_Error_void){ .error = mn_temporary_2.error };\n    }\n    mn_main_plain(3u);\n    mn_mn_memory_Arena_1_Deinit_deinit(&arena);\n    return (mn_result_mn_memory_Error_void){ .error.tag = 0 };\n}\n\nint main() {\n    mn_result_mn_memory_Error_void result = mn_main_main();\n    if (result.error.tag == 0) return 0;\n    switch (result.error.tag) {\n    case 1: mn_runtime_error_report(\"OutOfMemory\"); break;\n    }\n    return 1;\n}\n\nmn_result_mn_memory_Error_usize mn_main_middle_1(size_t count, [[maybe_unused]] void * mn_allocator) {\n    return mn_main_take_1(count, mn_allocator);\n}\n\nmn_result_mn_memory_Error_usize mn_main_middle_2(size_t count, [[maybe_unused]] struct mn_mn_memory_Arena_1 * mn_allocator) {\n    return mn_main_take_2(count, mn_allocator);\n}\n\nmn_result_mn_memory_Error_usize mn_main_take_1(size_t count, [[maybe_unused]] void * mn_allocator) {\n    void * const allocator = mn_allocator;\n    size_t mn_temporary_1;\n    mn_result_mn_memory_Error_slice_u8 mn_temporary_2;\n    mn_slice_u8 mn_temporary_3;\n    mn_temporary_1 = mn_main_plain(count);\n    mn_temporary_2 = mn_mn_memory_Heap_Allocator_allocate_2(allocator, mn_temporary_1);\n    if (mn_temporary_2.error.tag != 0) return (mn_result_mn_memory_Error_usize){ .error = mn_temporary_2.error };\n    mn_temporary_3 = mn_temporary_2.value;\n    const mn_slice_u8 items = mn_temporary_3;\n    const mn_result_mn_memory_Error_usize mn_returned = (mn_result_mn_memory_Error_usize){ .error.tag = 0, .value = items.length };\n    mn_mn_memory_Heap_Allocator_free_2(allocator, items);\n    return mn_returned;\n}\n\nmn_result_mn_memory_Error_usize mn_main_take_2(size_t count, [[maybe_unused]] struct mn_mn_memory_Arena_1 * mn_allocator) {\n    struct mn_mn_memory_Arena_1 * const allocator = mn_allocator;\n    size_t mn_temporary_1;\n    mn_result_mn_memory_Error_slice_u8 mn_temporary_2;\n    mn_slice_u8 mn_temporary_3;\n    mn_temporary_1 = mn_main_plain(count);\n    mn_temporary_2 = mn_mn_memory_Arena_1_Allocator_allocate_3(allocator, mn_temporary_1);\n    if (mn_temporary_2.error.tag != 0) return (mn_result_mn_memory_Error_usize){ .error = mn_temporary_2.error };\n    mn_temporary_3 = mn_temporary_2.value;\n    const mn_slice_u8 items = mn_temporary_3;\n    const mn_result_mn_memory_Error_usize mn_returned = (mn_result_mn_memory_Error_usize){ .error.tag = 0, .value = items.length };\n    mn_mn_memory_Arena_1_Allocator_free_3(allocator, items);\n    return mn_returned;\n}\n",
        files[1].contents,
    );
}

