test "generateFunctionCall: keeps the heap and the arena instances of a cycle apart with a written error set" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::memory\nimport mn::memory::Allocator\nimport mn::memory::Deinit\nfn even(count: usize) -> memory::Error!usize\n    if (count == 0) return 0\n    return try odd(count - 1)\nfn odd(count: usize) -> memory::Error!usize\n    with allocator\n    const own items = try allocator.allocate(u8, 1)\n    allocator.free(own items)\n    return try even(count)\nfn main -> !void\n    with memory::Heap\n    var own arena = memory::Arena(memory::Heap)::init(memory::Heap::init())\n    defer arena.deinit(own)\n    _ = try even(2)\n    _ = try even(3) with &arena\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqualStrings("main.h", files[0].path);
    try std.testing.expectEqualStrings("main.c", files[1].path);
    try std.testing.expectEqualStrings("mn/memory.h", files[2].path);
    try std.testing.expectEqualStrings("mn/memory.c", files[3].path);
    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef struct mn_result_mn_memory_Error_void mn_result_mn_memory_Error_void;\ntypedef struct mn_result_mn_memory_Error_usize mn_result_mn_memory_Error_usize;\ntypedef struct mn_mn_memory_Arena_1 mn_mn_memory_Arena_1;\n\nmn_result_mn_memory_Error_usize mn_main_even_1(size_t count, [[maybe_unused]] void * mn_allocator);\nmn_result_mn_memory_Error_usize mn_main_even_2(size_t count, [[maybe_unused]] struct mn_mn_memory_Arena_1 * mn_allocator);\nmn_result_mn_memory_Error_usize mn_main_odd_1(size_t count, [[maybe_unused]] void * mn_allocator);\nmn_result_mn_memory_Error_usize mn_main_odd_2(size_t count, [[maybe_unused]] struct mn_mn_memory_Arena_1 * mn_allocator);\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n#include \"mn/memory.h\"\n\n#ifndef mn_slice_u8_defined\n#define mn_slice_u8_defined\ntypedef struct mn_slice_u8 {\n    uint8_t *items;\n    size_t length;\n} mn_slice_u8;\n#endif\n\n#ifndef mn_result_mn_memory_Error_void_defined\n#define mn_result_mn_memory_Error_void_defined\ntypedef struct mn_result_mn_memory_Error_void {\n    mn_mn_memory_Error error;\n} mn_result_mn_memory_Error_void;\n#endif\n\n#ifndef mn_result_mn_memory_Error_usize_defined\n#define mn_result_mn_memory_Error_usize_defined\ntypedef struct mn_result_mn_memory_Error_usize {\n    mn_mn_memory_Error error;\n    size_t value;\n} mn_result_mn_memory_Error_usize;\n#endif\n\n#ifndef mn_result_mn_memory_Error_slice_u8_defined\n#define mn_result_mn_memory_Error_slice_u8_defined\ntypedef struct mn_result_mn_memory_Error_slice_u8 {\n    mn_mn_memory_Error error;\n    mn_slice_u8 value;\n} mn_result_mn_memory_Error_slice_u8;\n#endif\n\nvoid mn_runtime_error_report(char const *name);\n\nmn_result_mn_memory_Error_void mn_main_main() {\n    void * const mn_context = ((void *)mn_zero_sized);\n    mn_mn_memory_Arena_1 arena = (mn_mn_memory_Heap_init(), mn_mn_memory_Arena_1_init());\n    mn_result_mn_memory_Error_usize mn_temporary_1;\n    mn_temporary_1 = mn_main_even_1(2u, mn_context);\n    if (mn_temporary_1.error.tag != 0) {\n        mn_mn_memory_Arena_1_Deinit_deinit(&arena);\n        return (mn_result_mn_memory_Error_void){ .error = mn_temporary_1.error };\n    }\n    mn_result_mn_memory_Error_usize mn_temporary_2;\n    mn_temporary_2 = mn_main_even_2(3u, &arena);\n    if (mn_temporary_2.error.tag != 0) {\n        mn_mn_memory_Arena_1_Deinit_deinit(&arena);\n        return (mn_result_mn_memory_Error_void){ .error = mn_temporary_2.error };\n    }\n    mn_mn_memory_Arena_1_Deinit_deinit(&arena);\n    return (mn_result_mn_memory_Error_void){ .error.tag = 0 };\n}\n\nint main() {\n    mn_result_mn_memory_Error_void result = mn_main_main();\n    if (result.error.tag == 0) return 0;\