test "generateFunctionCall: calls the instance of the allocator of a with statement from a known local constant" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::memory\nimport mn::memory::Allocator\nfn take() -> memory::Error!usize\n    with allocator\n    const own items = try allocator.allocate(u8, 1)\n    defer allocator.free(own items)\n    return items.length\nfn main()\n    with memory::Heap\n    const size = take() catch 0\n    _ = size" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqualStrings("main.h", files[0].path);
    try std.testing.expectEqualStrings("main.c", files[1].path);
    try std.testing.expectEqualStrings("mn/memory.h", files[2].path);
    try std.testing.expectEqualStrings("mn/memory.c", files[3].path);
    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef struct mn_result_mn_memory_Error_usize mn_result_mn_memory_Error_usize;\n\nmn_result_mn_memory_Error_usize mn_main_take_1([[maybe_unused]] void * mn_allocator);\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n#include \"mn/memory.h\"\n\n#ifndef mn_slice_u8_defined\n#define mn_slice_u8_defined\ntypedef struct mn_slice_u8 {\n    uint8_t *items;\n    size_t length;\n} mn_slice_u8;\n#endif\n\n#ifndef mn_result_mn_memory_Error_usize_defined\n#define mn_result_mn_memory_Error_usize_defined\ntypedef struct mn_result_mn_memory_Error_usize {\n    mn_mn_memory_Error error;\n    size_t value;\n} mn_result_mn_memory_Error_usize;\n#endif\n\n#ifndef mn_result_mn_memory_Error_slice_u8_defined\n#define mn_result_mn_memory_Error_slice_u8_defined\ntypedef struct mn_result_mn_memory_Error_slice_u8 {\n    mn_mn_memory_Error error;\n    mn_slice_u8 value;\n} mn_result_mn_memory_Error_slice_u8;\n#endif\n\nint main() {\n    void * const mn_context = ((void *)mn_zero_sized);\n    mn_result_mn_memory_Error_usize mn_temporary_1;\n    (void)(mn_temporary_1 = mn_main_take_1(mn_context), (mn_temporary_1.error.tag == 0 ? mn_temporary_1.value : 0u));\n}\n\nmn_result_mn_memory_Error_usize mn_main_take_1([[maybe_unused]] void * mn_allocator) {\n    void * const allocator = mn_allocator;\n    mn_result_mn_memory_Error_slice_u8 mn_temporary_1;\n    mn_slice_u8 mn_temporary_2;\n    mn_temporary_1 = mn_mn_memory_Heap_Allocator_allocate_2(allocator, 1u);\n    if (mn_temporary_1.error.tag != 0) return (mn_result_mn_memory_Error_usize){ .error = mn_temporary_1.error };\n    mn_temporary_2 = mn_temporary_1.value;\n    const mn_slice_u8 items = mn_temporary_2;\n    const mn_result_mn_memory_Error_usize mn_returned = (mn_result_mn_memory_Error_usize){ .error.tag = 0, .value = items.length };\n    mn_mn_memory_Heap_Allocator_free_1(allocator, items);\n    return mn_returned;\n}\n",
        files[1].contents,
    );
    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"../runtime/monolith.h\"\n\ntypedef struct mn_mn_memory_Error {\n    uint32_t tag;\n} mn_mn_memory_Error;\n\ntypedef struct mn_slice_u8 mn_slice_u8;\ntypedef struct mn_result_mn_memory_Error_slice_u8 mn_result_mn_memory_Error_slice_u8;\n\nuint8_t * mn_runtime_memory_allocate(size_t size, size_t alignment);\nvoid mn_runtime_memory_copy(void * destination, void const * source, size_t size);\nvoid mn_runtime_memory_free(uint8_t * pointer);\n\nvoid mn_mn_memory_Heap_init();\nbool mn_mn_memory_equal(mn_slice_u8 one, mn_slice_u8 two);\nvoid mn_mn_memory_copy_1(mn_slice_u8 destination, mn_slice_u8 source);\nmn_result_mn_memory_Error_slice_u8 mn_mn_memory_Heap_Allocator_allocate_2(void *, [[maybe_unused]] size_t count);\nvoid mn_mn_memory_Heap_Allocator_free_1(void *, mn_slice_u8 items);\n",
        files[2].contents,
