cate((mn_temporary_1 * count), mn_temporary_2);\n    if (!(mn_temporary_3 != NULL)) {\n        return (mn_result_mn_memory_Error_slice_u8){ .error = (mn_mn_memory_Error){ .tag = 1 } };\n    } else {\n        mn_temporary_4 = mn_temporary_3;\n    }\n    uint8_t * const pointer = mn_temporary_4;\n    return (mn_result_mn_memory_Error_slice_u8){ .error.tag = 0, .value = (mn_slice_u8){ .items = ((uint8_t *)pointer) + 0u, .length = count - 0u } };\n}\n\nvoid mn_mn_memory_Heap_Allocator_free_1(void *, mn_slice_u8 items) {\n    if (items.length == 0u) {\n        return;\n    }\n    mn_runtime_memory_free(((uint8_t *)items.items));\n}\n",
