test "integration: checks a run-time condition that calls a function with a type argument" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "cards.mn", .data = "struct Card\n    question: []const(u8)\n    answer:   []const(u8)\n\nconst cards: [_]Card = {\n    { question = \"Question 1\", answer = \"Answer 1\" },\n    { question = \"Question 2\", answer = \"Answer 2\" },\n}\n" });
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::memory\nimport mn::process::stdin\nimport mn::process::stdout\nimport mn::stream::Reader\nimport mn::stream::Writer\nimport mn::text\n\nimport cards::cards\n\n\nfn main() -> !void\n    var input_buffer: [4096]u8 = undefined\n    var byte_count: usize = 0\n    var card_index: usize = 0\n\n    while card_index < cards.length\n        try text::print(&stdout, \"{s}\\n\", { cards[card_index].question })\n        byte_count = try stdin.read(&input_buffer)\n        if (byte_count == 0) break\n\n        try text::print(&stdout, \"{s}\\n\", { cards[card_index].answer })\n        byte_count = try stdin.read(&input_buffer)\n        if (byte_count == 0) break\n\n        if memory::equal(text::strip(input_buffer[..byte_count]), \"y\")\n           card_index += 1\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqual(24, files.len);
    var main_file: []const u8 = "";
    for (files) |file| {
        if (std.mem.eql(u8, file.path, "main.c")) main_file = file.contents;
    }
    try std.testing.expect(std.mem.indexOf(u8, main_file, "while (card_index < 2u) {") != null);
    try std.testing.expect(std.mem.indexOf(u8, main_file, "if (mn_mn_memory_equal(mn_mn_text_strip((mn_slice_u8){ .items = input_buffer.items, .length = byte_count }), (mn_slice_u8){ .items = (uint8_t *)\"y\", .length = 1 })) {") != null);
}

test "integration: generates the standard streams and a file read through the library" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::convert::To\nimport mn::filesystem\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process::stdin\nimport mn::process::stdout\nimport mn::stream::Reader\nimport mn::stream::Writer\nimport mn::text\n\nfn main -> !void\n    try text::print(&stdout, \"hi\\n\", {})\n    var buffer: [64]u8 = undefined\n    const count = try stdin.read(&buffer)\n    try stdout.write(buffer[..count])\n    var heap = memory::Heap::init()\n    var own path = try \"cards.toml\".to(filesystem::Path) with &heap\n    defer path.deinit(own) with &heap\n    _ = try measure(path)\n\nfn measure(path: filesystem::Path) -> filesystem::Error!usize\n    const file = filesystem::File::open(path) catch return 0\n    defer file.close()\n    var buffer: [64]u8 = undefined\n    const count = try file.read(&buffer)\n    return count + try file.size()\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqual(30, files.len);
    try std.testing.expectEqualStrings("main.h", files[0].path);
    try std.testing.expectEqualStrings("main.c", files[1].path);
    try std.testing.expectEqualStrings("mn/filesystem.h", files[3].path);
    try std.testing.expectEqualStrings("mn/filesystem.c", files[4].path);
    try std.testing.expectEqualStrings("mn/process.h", files[7].path);
    try std.testing.expectEqualStrings("mn/process.c", files[8].path);
    try std.testing.expectEqualStrings("mn/text.h", files[11].path);
    try std.testing.expectEqualStrings("mn/text.c", files[12].path);
    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef struct mn_result_mn_filesystem_Error_or_mn_memory_Error_or_mn_process_Error_void mn_result_mn_filesystem_Error_or_mn_memory_Error_or_mn_process_Error_void;\ntypedef struct mn_slice_u8 mn_mn_filesystem_Path;\ntypedef struct mn_result_mn_filesystem_Error_usize mn_result_mn_filesystem_Error_usize;\n\nmn_result_mn_filesystem_Error_usize mn_main_measure(mn_mn_filesystem_Path path);\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
