test "integration: generates a recursive walk of a directory that keeps a path" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::convert::To\nimport mn::convert::View\nimport mn::filesystem\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::stream::Writer\nimport mn::text\n\nfn walk(directory: filesystem::Directory, path: filesystem::Path) -> !void\n    while try directory.next() as entry\n        const own inner_path = try path.join(entry.name.view(filesystem::Path))\n        defer inner_path.deinit(own)\n        const own content = try inner_path.to([]u8)\n        defer memory::free(own content)\n        try text::print(&stdout, \"{s}\\n\", { content })\n        if entry.kind == filesystem::File::Kind::Directory\n            const inner = try filesystem::Directory::open(inner_path)\n            defer inner.close()\n            try walk(inner, inner_path)\n\nfn main -> !void\n    var heap = memory::Heap::init()\n    var own path = try \".\".to(filesystem::Path) with &heap\n    defer path.deinit(own) with &heap\n    const directory = try filesystem::Directory::open(path)\n    defer directory.close()\n    try walk(directory, path) with &heap\n    const own content = try path.to([]u8) with &heap\n    defer memory::free(own content) with &heap\n    try text::print(&stdout, \"{s}\\n\", { content })\n" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqual(30, files.len);
    try std.testing.expectEqualStrings("main.h", files[0].path);
    try std.testing.expectEqualStrings("main.c", files[1].path);
    try std.testing.expectEqualStrings("mn/convert.h", files[2].path);
    try std.testing.expectEqualStrings("mn/filesystem.h", files[3].path);
    try std.testing.expectEqualStrings("mn/filesystem.c", files[4].path);
    try std.testing.expectEqualStrings("mn/memory.h", files[5].path);
    try std.testing.expectEqualStrings("mn/memory.c", files[6].path);
    try std.testing.expectEqualStrings("mn/process.h", files[7].path);
    try std.testing.expectEqualStrings("mn/process.c", files[8].path);
    try std.testing.expectEqualStrings("mn/text.h", files[11].path);
    try std.testing.expectEqualStrings("mn/text.c", files[12].path);
    try std.testing.expectEqualStrings("mn/compare.h", files[15].path);
    try std.testing.expectEqualStrings("mn/compare.c", files[16].path);
    try std.testing.expectEqualStrings("mn/hash.h", files[17].path);
    try std.testing.expectEqualStrings("mn/hash.c", files[18].path);
    try std.testing.expectEqualStrings("mn/time.h", files[19].path);
    try std.testing.expectEqualStrings("mn/time.c", files[20].path);
    try std.testing.expectEqualStrings("mn/reflection.h", files[21].path);
    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef struct mn_result_mn_filesystem_Error_or_mn_memory_Error_or_mn_process_Error_void mn_result_mn_filesystem_Error_or_mn_memory_Error_or_mn_process_Error_void;\ntypedef struct mn_mn_filesystem_Directory mn_mn_filesystem_Directory;\ntypedef struct mn_slice_u8 mn_mn_filesystem_Path;\n\nmn_result_mn_filesystem_Error_or_mn_memory_Error_or_mn_process_Error_void mn_main_walk_1(mn_mn_filesystem_Directory directory, mn_mn_filesystem_Path path, [[maybe_unused]] void * mn_allocator);\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
