test "integration: prints each type with each placeholder through the standard library" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::process::stdout\nimport mn::stream::Writer\nimport mn::text\n\nfn main -> !void\n    try text::print(&stdout, \"{} {x} {b} {} {x} {b}\\n\", { -128i8, -2i16, 3i32, -4i64, 255i128, -6isize })\n    try text::print(&stdout, \"{} {x} {b} {} {x} {b}\\n\", { 7u8, 255u16, 9u32, 10u64, 11u128, 12usize })\n    try text::print(&stdout, \"{} {s} {{}} {}\\n\", { true, \"text\", false })" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqualStrings("main.h", files[0].path);
    try std.testing.expectEqualStrings("main.c", files[1].path);
    try std.testing.expectEqualStrings("mn/process.h", files[2].path);
    try std.testing.expectEqualStrings("mn/process.c", files[3].path);
    try std.testing.expectEqualStrings("mn/text.h", files[6].path);
    try std.testing.expectEqualStrings("mn/text.c", files[7].path);
    try std.testing.expectEqualStrings("mn/reflection.h", files[8].path);
    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef struct mn_result_mn_process_Error_void mn_result_mn_process_Error_void;\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n#include \"mn/process.h\"\n#include \"mn/text.h\"\n\n#ifndef mn_slice_u8_defined\n#define mn_slice_u8_defined\ntypedef struct mn_slice_u8 {\n    uint8_t *items;\n    size_t length;\n} mn_slice_u8;\n#endif\n\n#ifndef mn_result_mn_process_Error_void_defined\n#define mn_result_mn_process_Error_void_defined\ntypedef struct mn_result_mn_process_Error_void {\n    mn_mn_process_Error error;\n} mn_result_mn_process_Error_void;\n#endif\n\n#ifndef mn_tuple_6_i8_i16_i32_i64_i128_isize_defined\n#define mn_tuple_6_i8_i16_i32_i64_i128_isize_defined\ntypedef struct mn_tuple_6_i8_i16_i32_i64_i128_isize {\n    int8_t _0;\n    int16_t _1;\n    int32_t _2;\n    int64_t _3;\n    int128_t _4;\n    ptrdiff_t _5;\n} mn_tuple_6_i8_i16_i32_i64_i128_isize;\n#endif\n\n#ifndef mn_tuple_6_u8_u16_u32_u64_u128_usize_defined\n#define mn_tuple_6_u8_u16_u32_u64_u128_usize_defined\ntypedef struct mn_tuple_6_u8_u16_u32_u64_u128_usize {\n    uint8_t _0;\n    uint16_t _1;\n    uint32_t _2;\n    uint64_t _3;\n    uint128_t _4;\n    size_t _5;\n} mn_tuple_6_u8_u16_u32_u64_u128_usize;\n#endif\n\n#ifndef mn_tuple_3_bool_slice_u8_bool_defined\n#define mn_tuple_3_bool_slice_u8_bool_defined\ntypedef struct mn_tuple_3_bool_slice_u8_bool {\n    bool _0;\n    mn_slice_u8 _1;\n    bool _2;\n} mn_tuple_3_bool_slice_u8_bool;\n#endif\n\nvoid mn_runtime_error_report(char const *name);\n\n#ifndef mn_slice_u8_defined\n#define mn_slice_u8_defined\ntypedef struct mn_slice_u8 {\n    uint8_t *items;\n    size_t length;\n} mn_slice_u8;\n#endif\n\nvoid mn_runtime_process_start(int count, char **values, mn_slice_u8 *arguments);\n\nmn_result_mn_process_Error_void mn_main_main() {\n    mn_result_mn_process_Error_void mn_temporary_1;\n    mn_temporary_1 = mn_mn_text_print_1(((void const *)mn_zero_sized), (mn_tuple_6_i8_i16_i32_i64_i128_isize){ ._0 = -128, ._1 = -2, ._2 = 3, ._3 = -4, ._4 = ((int128_t)0x0u << 64 | 0xffu), ._5 = -6 });\n    if (mn_temporary_1.error.tag != 0) return (mn_result_mn_process_Error_void){ .error = mn_temporary_1.error };\n    mn_result_mn_process_Error_void mn_temporary_2;\n    mn_temporary_2 = mn_mn_text_print_2(((void const *)mn_zero_sized), (mn_tuple_6_u8_u16_u32_u64_u128_usize){ ._0 = 7u, ._1 = 255u, ._2 = 9u, ._3 = 10u, ._4 = ((uint128_t)0x0u << 64 | 0xbu), ._5 = 12u });\n    if (mn_temporary_2.error.tag != 0) return (mn_result_mn_process_Error_void){ .error = mn_temporary_2.error };\n    mn_result_mn_process_Error_void mn_temporary_3;\n    mn_temporary_3 = mn_mn_text_print_3(((void const *)mn_zero_sized), (mn_tuple_3_bool_slice_u8_bool){ ._0 = true, ._1 = (mn_slice_u8){ .items = (uint8_t *)\"text\", .length = 4 }, ._2 = false });\n    if (mn_temporary_3.error.tag != 0) return (mn_result_mn_process_Error_void){ .error = mn_temporary_3.error };\n    return (mn_result_mn_process_Error_void){ .error.tag = 0 };\n}\n\nint main(int argc, char **argv) {\n    mn_slice_u8 arguments[argc + 1];\n    mn_runtime_process_start(argc, argv, arguments);\n    mn_result_mn_process_Error_void result = mn_main_main();\n    if (result.error.tag == 0) return 0;\n    switch (result.error.tag) {\n    case 1: mn_runtime_error_report(\"BrokenPipe\"); break;\n    case 2: mn_runtime_error_report(\"ConnectionFailure\"); break;\n    case 3: mn_runtime_error_report(\"DeviceFailure\"); break;\n    case 4: mn_runtime_error_report(\"IsDirectory\"); break;\n    case 5: mn_runtime_error_report(\"NoSpace\"); break;\n    case 6: mn_runtime_error_report(\"NotOpen\"); break;\n    case 7: mn_runtime_error_report(\"WouldBlock\"); break;\n    case 8: mn_runtime_error_report(\"SystemFailure\"); break;\n    }\n    return 1;\n}\n",
        files[1].contents,
    );
    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"../runtime/monolith.h\"\n\ntypedef struct mn_mn_process_Error {\n    uint32_t tag;\n} mn_mn_process_Error;\n\ntypedef struct mn_slice_u8 mn_slice_u8;\ntypedef struct mn_slice_slice_u8 mn_slice_slice_u8;\ntypedef struct mn_result_mn_process_Error_usize mn_result_mn_process_Error_usize;\ntypedef struct mn_result_mn_process_Error_void mn_result_mn_process_Error_void;\n\nptrdiff_t mn_runtime_io_read(int32_t descriptor, mn_slice_u8 buffer);\nptrdiff_t mn_runtime_io_write(int32_t descriptor, mn_slice_u8 bytes);\nmn_slice_slice_u8 mn_runtime_process_arguments();\nmn_slice_u8 mn_runtime_process_invoked_as();\n\nmn_slice_slice_u8 mn_mn_process_arguments();\nmn_slice_u8 mn_mn_process_invoked_as();\nmn_result_mn_process_Error_usize mn_mn_process_Stdin_Reader_read(void const *, mn_slice_u8 buffer);\nmn_result_mn_process_Error_usize mn_mn_process_read_descriptor(int32_t descriptor, mn_slice_u8 buffer);\nmn_mn_process_Error mn_mn_process_find_error(ptrdiff_t code);\nmn_result_mn_process_Error_void mn_mn_process_Stdout_Writer_write(void const *, mn_slice_u8 bytes);\nmn_result_mn_process_Error_void mn_mn_process_write_descriptor(int32_t descriptor, mn_slice_u8 bytes);\n",
        files[2].contents,
    );
