test "integration: formats into a list of bytes and to the standard output through the standard library" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn::memory\nimport mn::process::stdout\nimport mn::text\n\nfn main -> !void\n    var heap = memory::Heap::init()\n    const own child = try text::format(\"{s}/{s}\", { \"parent\", \"name\" }) with &heap\n    defer memory::free(own child) with &heap\n    try text::print(&stdout, \"{s} has {} cards\\n\", { child, 3u32 })" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqualStrings("main.h", files[0].path);
    try std.testing.expectEqualStrings("main.c", files[1].path);
    try std.testing.expectEqualStrings("mn/memory.h", files[2].path);
    try std.testing.expectEqualStrings("mn/memory.c", files[3].path);
    try std.testing.expectEqualStrings("mn/process.h", files[4].path);
    try std.testing.expectEqualStrings("mn/process.c", files[5].path);
    try std.testing.expectEqualStrings("mn/text.h", files[6].path);
    try std.testing.expectEqualStrings("mn/text.c", files[7].path);
    try std.testing.expectEqualStrings("mn/reflection.h", files[8].path);
    try std.testing.expectEqualStrings("mn/container.h", files[13].path);
    try std.testing.expectEqualStrings("mn/container.c", files[14].path);
    try std.testing.expectEqualStrings("mn/convert.h", files[15].path);
    try std.testing.expectEqualStrings("mn/compare.h", files[11].path);
    try std.testing.expectEqualStrings("mn/compare.c", files[12].path);
    try std.testing.expectEqualStrings("mn/hash.h", files[20].path);
    try std.testing.expectEqualStrings("mn/hash.c", files[21].path);
    try std.testing.expectEqualStrings("mn/iterator.h", files[16].path);
    try std.testing.expectEqualStrings("mn/iterator.c", files[17].path);
    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef struct mn_result_mn_memory_Error_or_mn_process_Error_void mn_result_mn_memory_Error_or_mn_process_Error_void;\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
