test "integration: gives a generic function that writes the allocator only for the writer that needs it" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var program_directory = std.testing.tmpDir(.{});
    defer program_directory.cleanup();
    const program_path = try std.fs.path.join(
        arena.allocator(),
        &.{ ".zig-cache", "tmp", &program_directory.sub_path },
    );
    var loader = @import("monolith").Loader.init(program_path, "library");
    try program_directory.dir.writeFile(std.testing.io, .{ .sub_path = "main.mn", .data = "import mn\nimport mn::container\nimport mn::memory\nimport mn::memory::Deinit\nimport mn::process::stdout\nimport mn::stream::Writer\n\nfn report(writer: *Writer, count: u32) -> !void\n    _ = count\n    try writer.write(\"cards\")\n\nfn main -> !void\n    var heap = memory::Heap::init()\n    var own text = mn::container::ArrayList(u8)::init()\n    defer text.deinit(own) with &heap\n    try report(&text, 3) with &heap\n    try report(&stdout, 4)" });
    try loader.loadMainModule(&arena, std.testing.io, "main");
    var type_registry: types.Registry = .{};
    var analyzer = @import("monolith").Analyzer.init(&arena, std.testing.io, &loader, &type_registry);
    const program = try analyzer.analyze();
    var generator = Generator.init(program);
    const files = try generator.generateFiles(arena.allocator());

    try std.testing.expectEqualStrings("main.h", files[0].path);
    try std.testing.expectEqualStrings("main.c", files[1].path);
    try std.testing.expectEqualStrings(
        "#pragma once\n\n#include \"runtime/monolith.h\"\n\ntypedef struct mn_result_mn_memory_Error_or_mn_process_Error_void mn_result_mn_memory_Error_or_mn_process_Error_void;\ntypedef struct mn_mn_container_ArrayList_1 mn_mn_container_ArrayList_1;\ntypedef struct mn_result_mn_memory_Error_void mn_result_mn_memory_Error_void;\ntypedef struct mn_result_mn_process_Error_void mn_result_mn_process_Error_void;\n\nmn_result_mn_memory_Error_void mn_main_report_2(struct mn_mn_container_ArrayList_1 * writer, uint32_t, [[maybe_unused]] void * mn_allocator);\nmn_result_mn_process_Error_void mn_main_report_3(void const * writer, uint32_t);\n",
        files[0].contents,
    );
    try std.testing.expectEqualStrings(
        "#include \"main.h\"\n#include \"mn/memory.h\"\n#include \"mn/process.h\"\n#include \"mn/container.h\"\n\n#ifndef mn_slice_u8_defined\n#define mn_slice_u8_defined\ntypedef struct mn_slice_u8 {\n    uint8_t *items;\n    size_t length;\n} mn_slice_u8;\n#endif\n\n#ifndef mn_mn_memory_Error_or_mn_process_Error_defined\n#define mn_mn_memory_Error_or_mn_process_Error_defined\ntypedef struct mn_mn_memory_Error_or_mn_process_Error {\n    uint32_t tag;\n} mn_mn_memory_Error_or_mn_process_Error;\n#endif\n\n#ifndef mn_result_mn_memory_Error_or_mn_process_Error_void_defined\n#define mn_result_mn_memory_Error_or_mn_process_Error_void_defined\ntypedef struct mn_result_mn_memory_Error_or_mn_process_Error_void {\n    mn_mn_memory_Error_or_mn_process_Error error;\n} mn_result_mn_memory_Error_or_mn_process_Error_void;\n#endif\n\n#ifndef mn_result_mn_memory_Error_void_defined\n#define mn_result_mn_memory_Error_void_defined\ntypedef struct mn_result_mn_memory_Error_void {\n    mn_mn_memory_Error error;\n} mn_result_mn_memory_Error_void;\n#endif\n\n#ifndef mn_result_mn_process_Error_void_defined\n#define mn_result_mn_process_Error_void_defined\ntypedef struct mn_result_mn_process_Error_void {\n    mn_mn_process_Error error;\n} mn_result_mn_process_Error_void;\n#endif\n\n#ifndef mn_mn_memory_Error_or_mn_process_Error_from_mn_memory_Error_defined\n#define mn_mn_memory_Error_or_mn_process_Error_from_mn_memory_Error_defined\nstatic inline mn_mn_memory_Error_or_mn_process_Error mn_mn_memory_Error_or_mn_process_Error_from_mn_memory_Error(mn_mn_memory_Error value) {\n    mn_mn_memory_Error_or_mn_process_Error result;\n    result.tag = value.tag;\n    return result;\n}\n#endif\n\n#ifndef mn_mn_memory_Error_or_mn_process_Error_from_mn_process_Error_defined\n#define mn_mn_memory_Error_or_mn_process_Error_from_mn_process_Error_defined\nstatic inline mn_mn_memory_Error_or_mn_process_Error mn_mn_memory_Error_or_mn_process_Error_from_mn_process_Error(mn_mn_process_Error value) {\n    mn_mn_memory_Error_or_mn_process_Error result;\n    result.tag = value.tag;\n    return result;\n}\n#endif\n\nvoid mn_runtime_error_report(char const *name);\n\n#ifndef mn_slice_u8_defined\n#define mn_slice_u8_defined\ntypedef struct mn_slice_u8 {\n    uint8_t *items;\n    size_t length;\n} mn_slice_u8;\n#endif\n\nvoid mn_runtime_process_start(int count, char **values, mn_slice_u8 *arguments);\n\nmn_result_mn_memory_Error_or_mn_process_Error_void mn_main_main() {\n    mn_mn_memory_Heap_init();\n    mn_mn_container_ArrayList_1 text = mn_mn_container_ArrayList_1_init();\n    mn_result_mn_memory_Error_void mn_temporary_1;\n    mn_temporary_1 = mn_main_report_2(&text, 3u, ((void *)mn_zero_sized));\n    if (mn_temporary_1.error.tag != 0) {\n        mn_mn_container_ArrayList_1_Deinit_deinit_1(&text, ((void *)mn_zero_sized));\n        return (mn_result_mn_memory_Error_or_mn_process_Error_void){ .error = mn_mn_memory_Error_or_mn_process_Error_from_mn_memory_Error(mn_temporary_1.error) };\n    }\n    mn_result_mn_process_Error_void mn_temporary_2;\n    mn_temporary_2 = mn_main_report_3(((void const *)mn_zero_sized), 4u);\n    if (mn_temporary_2.error.tag != 0) {\n        mn_mn_container_ArrayList_1_Deinit_deinit_1(&text, ((void *)mn_zero_sized));\n        return (mn_result_mn_memory_Error_or_mn_process_Error_void){ .error = mn_mn_memory_Error_or_mn_process_Error_from_mn_process_Error(mn_temporary_2.error) };\n    }\n    mn_mn_container_ArrayList_1_Deinit_deinit_1(&text, ((void *)mn_zero_sized));\n    return (mn_result_mn_memory_Error_or_mn_process_Error_void){ .error.tag = 0 };\n}\n\nint main(int argc, char **argv) {\n    mn_slice_u8 arguments[argc + 1];\n    mn_runtime_process_start(argc, argv, arguments);\n    mn_result_mn_memory_Error_or_mn_process_Error_void result = mn_main_main();\n    if (result.error.tag == 0) return 0;\n    switch (result.error.tag) {\n    case 1: mn_runtime_error_report(\"OutOfMemory\"); break;\n    case 2: mn_runtime_error_report(\"BrokenPipe\"); break;\n    case 3: mn_runtime_error_report(\"ConnectionFailure\"); break;\n    case 4: mn_runtime_error_report(\"DeviceFailure\"); break;\n    case 5: mn_runtime_error_report(\"IsDirectory\"); break;\n    case 6: mn_runtime_error_report(\"NoSpace\"); break;\n    case 7: mn_runtime_error_report(\"NotOpen\"); break;\n    case 8: mn_runtime_error_report(\"WouldBlock\"); break;\n    case 9: mn_runtime_error_report(\"SystemFailure\"); break;\n    }\n    return 1;\n}\n\nmn_result_mn_memory_Error_void mn_main_report_2(struct mn_mn_container_ArrayList_1 * writer, uint32_t, [[maybe_unused]] void * mn_allocator) {\n    mn_result_mn_memory_Error_void mn_temporary_1;\n    mn_temporary_1 = mn_mn_container_ArrayList_1_Writer_write_1(writer, (mn_slice_u8){ .items = (uint8_t *)\"cards\", .length = 5 }, mn_allocator);\n    if (mn_temporary_1.error.tag != 0) return (mn_result_mn_memory_Error_void){ .error = mn_temporary_1.error };\n    return (mn_result_mn_memory_Error_void){ .error.tag = 0 };\n}\n\nmn_result_mn_process_Error_void mn_main_report_3(void const * writer, uint32_t) {\n    mn_result_mn_process_Error_void mn_temporary_1;\n    mn_temporary_1 = mn_mn_process_Stdout_Writer_write(writer, (mn_slice_u8){ .items = (uint8_t *)\"cards\", .length = 5 });\n    if (mn_temporary_1.error.tag != 0) return (mn_result_mn_process_Error_void){ .error = mn_temporary_1.error };\n    return (mn_result_mn_process_Error_void){ .error.tag = 0 };\n}\n",
        files[1].contents,
    );
}
